import actions from './actions'

const initialState = {
  data: [],
  message: '',
  status: '',
  statusCancelPolicy: undefined,
  statusTerminatePolicy: undefined,
  dataTransaction: [],
  statusGetTransactionList: '',
  statusGetSuspendedList: '',
  dataSuspended: []
}

export default function gocarReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE:
      return {
        ...state,
        statusCancelPolicy: '',
        status: '',
        statusTerminatePolicy: '',
        statusGetSuspendedList: ''
      }
    case actions.GET_GOCAR_SIMPLE_DATA_SUCCESS:
    case actions.GET_GOCAR_SIMPLE_DATA_FAILURE:
      return {
        ...state,
        status: action.getDataStatus,
        goCarList: action.data.data,
        metadata: action.data.metadata
      }
    case actions.GET_GOCAR_KOMPLIT_DATA_SUCCESS:
    case actions.GET_GOCAR_KOMPLIT_DATA_FAILURE:
      return {
        ...state,
        status: action.getDataStatus,
        goCarList: action.data.data,
        metadata: action.data.metadata
      }
    case actions.STATUS_UPDATE_POLICY_NUMBER:
      return {
        ...state,
        newPolicyNumber: action.data
      }
    case actions.SUCCESS_UPLOAD_FILE:
      return {
        ...state,
        status: action.status
      }
    case actions.FAILED_UPLOAD_FILE:
      return {
        ...state,
        status: action.status
      }
    case actions.UPLOAD_LIST_DATA:
      return {
        ...state,
        data: action.data,
        status: action.status
      }
    case actions.FAILED_GET_UPLOAD_LIST:
      return {
        ...state,
        status: action.status
      }
    case actions.GET_DETAIL_UPLOAD_LIST_SUCCESS:
    case actions.GET_DETAIL_UPLOAD_LIST_FAILURE:
      return {
        ...state,
        fileDetail: action.data,
        status: action.status
      }
    case actions.DATA_GOCAR_DETAILS:
      return {
        ...state,
        data: action.data,
        status: action.status
      }
    case actions.FAILED_GET_DATA_GOCAR_DETAILS:
      return {
        ...state,
        data: [],
        status: action.status
      }
    case actions.FAILED_UPDATE_POLICY_NUMBER:
      return {
        ...state,
        updatePolicyStatus: action.updatePolicyStatus
      }
    case actions.GOCAR_PAYMENT_DETAILS:
      return {
        ...state,
        payment: action.data,
        status: action.status
      }
    case actions.CANCEL_POLICY_SUCCESS:
    case actions.CANCEL_POLICY_FAILURE:
      return {
        ...state,
        statusCancelPolicy: action.statusCancelPolicy
      }
    case actions.TERMINATE_POLICY_SUCCESS:
    case actions.TERMINATE_POLICY_FAILURE:
      return {
        ...state,
        statusTerminatePolicy: action.statusTerminatePolicy
      }
    case actions.DATA_TRANSACTION_LIST:
      return {
        ...state,
        dataTransaction: action.dataTransaction,
        statusGetTransactionList: action.statusGetTransactionList
      }
    case actions.FAILED_GET_TRANSACTION_LIST:
      return {
        ...state,
        statusGetTransactionList: action.statusGetTransactionList
      }
    case actions.DATA_SUSPENDED_LIST:
      return {
        ...state,
        dataSuspended: action.dataSuspended,
        statusGetSuspendedList: action.statusGetSuspendedList
      }
    case actions.FAILED_GET_SUSPENDED_LIST:
      return {
        ...state,
        statusGetSuspendedList: action.statusGetSuspendedList
      }
    case actions.DATA_PRODUCTS:
      return {
        ...state,
        products: action.products
      }
    case actions.GET_GOCAR_FILE_TEMPLATES_SUCCESS:
    case actions.GET_GOCAR_FILE_TEMPLATES_FAILURE:
      return {
        ...state,
        templateList: action.data,
        templateListMessage: action.message
      }
    case actions.GET_GOCAR_TEMPLATE_SAMPLE_SUCCESS:
    case actions.GET_GOCAR_TEMPLATE_SAMPLE_FAILURE:
      return {
        ...state,
        getFileTemplateSampleMessage: action.message
      }
    case actions.UPLOAD_GOCAR_BULK_EXCEL_SUCCESS:
    case actions.UPLOAD_GOCAR_BULK_EXCEL_FAILURE:
      return {
        ...state,
        uploadGocarBulkExcelMessage: action.message
      }
    case actions.CHECK_MISSING_PAYMENT_SUCCESS:
    case actions.CHECK_MISSING_PAYMENT_FAILURE:
      return {
        ...state,
        missingPayment: action.data
      }
    case actions.ADD_PAYMENT_SUCCESS:
    case actions.ADD_PAYMENT_FAILURE:
      return {
        ...state,
        addPaymentStatus: action.data
      }
    default:
      return state
  }
}
