import { language } from '../../settings'

import Indonesia from '../../image/flag/indonesia.svg'
import English from '../../image/flag/united-states.svg'
import Thai from '../../image/flag/thailand.svg'
import Vietnam from '../../image/flag/vietnam.svg'

/*
{
  languageId: "english", human readable language name
  locale: "en", locale key
  messagesId: "eng", key used to get translated messages in anuvadak
  text: "English", displayable value
  code: "EN", code displayed in header
  icon: English displayable icon, imported variable
}
*/
const config = {
  defaultLanguage: language,
  options: [
    {
      languageId: 'indonesia',
      locale: 'id',
      messagesId: 'ind',
      text: 'Indonesia',
      code: 'ID',
      icon: Indonesia
    },
    {
      languageId: 'english',
      locale: 'en',
      messagesId: 'eng',
      text: 'English',
      code: 'EN',
      icon: English
    },
    {
      languageId: 'thai',
      locale: 'th',
      messagesId: 'tha',
      text: 'Thailand',
      code: 'TH',
      icon: Thai
    },
    {
      languageId: 'viet',
      locale: 'vi',
      messagesId: 'vie',
      text: 'Vietnam',
      code: 'VN',
      icon: Vietnam
    }
  ]
}

export function getCurrentLanguage (lang) {
  const selectedLanguage = config.options[1]
  const configLanguage = config.options.find(x => x.locale === lang)
  return configLanguage || selectedLanguage
}
export default config
