import actions from './actions'

const initialState = {
  getTranslationsStatus: '',
  postTranslationsStatus: '',
  postTranslationsEntryStatus: ''
}

export default function umbrellaReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_TRANSLATIONS_REDUX:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state,
          ...initialState
        }
      }
    case actions.GET_TRANSLATIONS_SUCCESS:
    case actions.GET_TRANSLATIONS_FAILURE:
      return { ...state, getTranslationsStatus: action.message }
    case actions.POST_TRANSLATIONS_SUCCESS:
    case actions.POST_TRANSLATIONS_FAILURE:
      return { ...state, postTranslationsStatus: action.message }
    case actions.POST_TRANSLATIONS_ENTRY_SUCCESS:
    case actions.POST_TRANSLATIONS_ENTRY_FAILURE:
      return { ...state, postTranslationsEntryStatus: action.message }
    default:
      return state
  }
}
