import actions from './actions'

const initialState = {
  reportingList: [],
  reportingListMessage: '',
  reportingConfigDetails: [],
  getReportingDetailsMessage: '',
  getReportingConfigStatusMessage: '',
  createReportingConfigMessage: '',
  updateReportingConfigMessage: '',
  reportLogs: [],
  reportLogsMessage: '',
  updateReportLogsMessage: '',
  updateLogs: [],
  updateLogsMessage: ''
}
export default function reportingConfigReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REPORTING_CONFIG: {
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    }
    case actions.GET_REPORTING_LIST_SUCCESS:
    case actions.GET_REPORTING_LIST_FAILURE:
      return {
        ...state,
        reportingList: action.data,
        reportingListMessage: action.getReportingListMessage
      }
    case actions.GET_REPORTING_CONFIG_DETAILS_SUCCESS:
    case actions.GET_REPORTING_CONFIG_DETAILS_FAILURE:
      return {
        ...state,
        reportingConfigDetails: action.data,
        getReportingDetailsMessage: action.getReportingDetailsMessage
      }
    case actions.GET_REPORTING_CONFIG_STATUS_SUCCESS:
    case actions.GET_REPORTING_CONFIG_STATUS_FAILURE:
      return {
        ...state,
        getReportingConfigStatusDetails: action.data,
        getReportingConfigStatusMessage: action.message
      }
    case actions.CREATE_REPORTING_CONFIG_DETAILS_SUCCESS:
    case actions.CREATE_REPORTING_CONFIG_DETAILS_FAILURE:
      return {
        ...state,
        craeteReportConfigData: action.data,
        createReportingConfigMessage: action.message
      }
    case actions.UPDATE_REPORTING_CONFIG_DETAILS_SUCCESS:
    case actions.UPDATE_REPORTING_CONFIG_DETAILS_FAILURE:
      return {
        ...state,
        updateReportConfigData: action.data,
        updateReportingConfigMessage: action.message
      }
    case actions.GET_REPORT_LOG_SUCCESS:
    case actions.GET_REPORT_LOG_FAILURE:
      return {
        ...state,
        reportLogs: action.data,
        reportLogsMessage: action.message,
        updateReportLogs: [],
        updateReportLogsMessage: ''
      }
    case actions.UPDATE_REPORT_LOG_SUCCESS:
    case actions.UPDATE_REPORT_LOG_FAILURE:
      return {
        ...state,
        updateReportLogs: action.data,
        updateReportLogsMessage: action.message
      }
    case actions.GET_UPDATE_LOG_SUCCESS:
    case actions.GET_UPDATE_LOG_FAILURE:
      return {
        ...state,
        updateLogs: action.data,
        updateLogsMessage: action.message
      }
    default:
      return state
  }
}
