import { all, takeEvery, call, fork, put } from 'redux-saga/effects'
import actions from './actions'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import urls from '../../../request/urls/reportingConfig'

export function * getReportingList () {
  yield takeEvery(actions.GET_REPORTING_LIST_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, {
        query: payload.query,
        url: urls.getReportingListUrl
      })
      if (res.status === 200) {
        yield put({
          type: actions.GET_REPORTING_LIST_SUCCESS,
          data: res.data,
          getReportingListMessage: 'success'
        })
      } else {
        yield put({
          type: actions.GET_REPORTING_LIST_FAILURE,
          data: [],
          getReportingListMessage: 'error'
        })
      }
    } catch (error) {
      yield put({
        type: actions.GET_REPORTING_LIST_FAILURE,
        data: [],
        getReportingListMessage: error.message
      })
    }
  })
}

