export default function * rootSaga () {
  yield all([
    fork(getReportingList),
    fork(getReportingConfigDetailsList),
    fork(getReportingConfigStatus),
    fork(createReportingConfig),
    fork(updateReportingConfig),
    fork(getReportLogs),
    fork(updateReportLogs),
    fork(getUpdateLogs)
  ])
}
