import actions from './actions'

const initialState = {
  productList: {},
  productListMessage: undefined,
  productDetail: {},
  productDetailMessage: undefined,
  productDetailAttributes: {},
  productDetailAttributesMessage: undefined,
  productDetailPackges: {},
  productDetailPackgesMessage: undefined,
  getproductPackageValidation: {},
  getproductPackageValidationMessage: undefined,
  getProductCategories: {},
  getProductCategoriesMessage: undefined,
  getProductRegulatoryCategories: {},
  getProductRegulatoryCategoriesMessage: undefined,
  getAllProductAttributes: {},
  getAllProductAttributesMessage: undefined,
  getAllProductValidation: {},
  getAllProductValidationMessage: undefined,
  getAllProviders: [],
  getAllProvidersMessage: undefined,
  getAllCountries: {},
  getAllCountriesMessage: undefined,
  getAllTimezones: {},
  getAllTimezonesMessage: undefined,
  addconfigProductData: {},
  addconfigProductMessage: undefined,
  addProductAttributesMessage: undefined,
  addProductPackagesresponse: {},
  addProductPackagesMessage: undefined,
  addProductDataValidation: undefined,
  getExistinProductPackageData: {},
  getExistinProductPackageMessage: undefined,
  editProductMessage: undefined,
  editProductData: {},
  editPackageMessage: undefined,
  editPackageData: {},
  editProductValidationsMessage: undefined,
  editProductValidationsData: {},
  addPolicyCreationData: [],
  addEndorsementCreationData: [],
  hashListData: {},
  hashListDataMessage: undefined,
  exportProductData: {},
  exportProductDataMessage: undefined,
  importProductData: {},
  importProductDataMessage: undefined,
  exportPackageData: {},
  exportPackageDataMessage: undefined,
  importPackageData: {},
  importPackageDataMessage: undefined,
  validationUniqueIdentifierData: {},
  validationUniqueIdentifierMessage: undefined,
  pubLishUndoMessage: undefined,
  pubLishUndoStatusMessage: undefined,
  getAllProductConfigSlugData: [],
  getAllProductConfigSlugMessage: undefined,
  addPackageConfigData: [],
  addPackageConfigMessage: undefined,
  getAllProductConfigData: [],
  getAllProductConfigMessage: undefined,
  createAddonData: [],
  createAddonMessage: undefined,
  getListAddonsData: [],
  getListAddonsMessage: undefined,
  getDetailAddonsData: [],
  getDetailAddonsMessage: undefined,
  editAddonData: [],
  editAddonMessage: undefined,
  updatePackageConfigstatusData: [],
  updatePackageConfigstatusMessage: undefined
}
export default function productConfigReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_PRODUCT_CONFIG: {
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    }
    case actions.GET_PRODUCT_LIST_SUCCESS:
    case actions.GET_PRODUCT_LIST_FAILURE:
      return {
        ...state,
        productList: action.data,
        productListMessage: action.getProductListMessage
      }
    case actions.PRODUCT_DETAIL_SUCCESS:
    case actions.PRODUCT_DETAIL_FAILURE:
      return {
        ...state,
        productDetail: action.data,
        productDetailMessage: action.getProductDetailMessage
      }
    case actions.PRODUCT_DETAILS_ATTRIBUTE_SUCCESS:
    case actions.PRODUCT_DETAILS_ATTRIBUTE_FAILURE:
      return {
        ...state,
        productDetailAttributes: action.data,
        productDetailAttributesMessage: action.getProductDetailAttributeMessage
      }
    case actions.GET_PRODUCT_PACKGES_SUCCESS:
    case actions.GET_PRODUCT_PACKGES_FAILURE:
      return {
        ...state,
        productDetailPackges: action.data,
        productDetailPackgesMessage: action.getProductDetailPackagesMessage
      }
    case actions.GET_PACKAGES_VALIDATION_FAILURE:
    case actions.GET_PACKAGES_VALIDATION_SUCCESS:
      return {
        ...state,
        getproductPackageValidation: action.data,
        getproductPackageValidationMessage: action.getPackagesValidationMessage
      }
    case actions.GET_PRODUCT_CATEGORIES_SUCCESS:
    case actions.GET_PRODUCT_CATEGORIES_FAILURE:
      return {
        ...state,
        getProductCategories: action.data,
        getProductCategoriesMessage: action.getProductCategoriesMessage
      }
    case actions.GET_PRODUCT_REGULATORY_CATEGORIES_SUCCESS:
    case actions.GET_PRODUCT_REGULATORY_CATEGORIES_FAILURE:
      return {
        ...state,
        getProductRegulatoryCategories: action.data,
        getProductRegulatoryCategoriesMessage:
          action.getProductRegulatoryCategoriesMessage
      }
    case actions.GET_ALL_PRODUCT_ATTRIBUTES_SUCCESS:
    case actions.GET_ALL_PRODUCT_ATTRIBUTES_FAILURE:
      return {
        ...state,
        getAllProductAttributes: action.data,
        getAllProductAttributesMessage: action.getAllProductAttributesMessage
      }
    case actions.GET_ALL_ATTRIBUTES_VALIDATIONS_SUCCESS:
    case actions.GET_ALL_ATTRIBUTES_VALIDATIONS_FAILURE:
      return {
        ...state,
        getAllProductValidation: action.data,
        getAllProductValidationMessage:
          action.getAllProductAttributesValidationMessage
      }
    case actions.GET_ALL_PROVIDER_FAILURE:
    case actions.GET_ALL_PROVIDER_SUCCESS:
      return {
        getAllProviders: action.data,
        getAllProvidersMessage: action.getAllProductProvidersMessage
      }
    case actions.GET_ALL_TIMEZONES_FAILURE:
    case actions.GET_ALL_TIMEZONES_SUCCESS:
      return {
        getAllTimezones: action.data,
        getAllTimezonesMessage: action.getAllProductTimezonesMessage
      }
    case actions.GET_ALL_COUNTRIES_FAILURE:
    case actions.GET_ALL_COUNTRIES_SUCCESS:
      return {
        getAllCountries: action.data,
        getAllCountriesMessage: action.getAllProductCountriesMessage
      }
    case actions.CREATE_NEW_PRODUCT_SUCCESS:
    case actions.CREATE_NEW_PRODUCT_FAILURE:
      return {
        addconfigProductData: action.data,
        addconfigProductMessage: action.createConfigProductMessage
      }
    case actions.ADD_PRODUCT_ATTRIBUTES_SUCCESS:
    case actions.ADD_PRODUCT_ATTRIBUTES_FAILURE:
      return {
        addProductAttributesMessage: action.createProductAttributesMessage
      }
    case actions.ADD_PACKAGE_SUCCESS:
    case actions.ADD_PACKAGE_FAILURE:
      return {
        addProductPackagesresponse: action.data,
        addProductPackagesMessage: action.createProductPackagesMessage
      }
    case actions.ADD_DATA_VALIDATION_SUCCESS:
    case actions.ADD_DATA_VALIDATION_FAILURE:
      return {
        addProductDataValidation: action.addProductDataValidationsMessage
      }
    case actions.GET_EXISTING_PRODUCT_PACKAGE_SUCCESS:
    case actions.GET_EXISTING_PRODUCT_PACKAGE_FAILURE:
      return {
        getExistinProductPackageData: action.data,
        getExistinProductPackageMessage: action.message
      }
    case actions.EDIT_PRODUCT_CONFIG_FAILURE:
    case actions.EDIT_PRODUCT_CONFIG_SUCCESS:
      return {
        editProductMessage: action.message,
        editProductData: action.data
      }
    case actions.EDIT_PACKAGE_FAILURE:
    case actions.EDIT_PACKAGE_SUCCESS:
      return {
        editPackageMessage: action.message,
        editPackageData: action.data
      }
    case actions.EDIT_PRODUCT_ATTRIBUTES_SUCCESS:
    case actions.EDIT_PRODUCT_ATTRIBUTES_FAILURE:
      return {
        editProductValidationsMessage: action.message,
        editProductValidationsData: action.data
      }
    case actions.ADD_POLICY_CREATION_DATA:
      return {
        addPolicyCreationData: action.payload
      }
    case actions.ADD_ENDORSEMENT_CREATION_DATA:
      return {
        addEndorsementCreationData: action.payload
      }
    case actions.GET_LIST_HASH_CONFIG_SUCCESS:
    case actions.GET_LIST_HASH_CONFIG_FAILURE:
      return {
        hashListData: action.data,
        hashListDataMessage: action.message
      }
    case actions.EXPORT_PRODUCT_FAILURE:
    case actions.EXPORT_PRODUCT_SUCCESS:
      return {
        exportProductData: action.data,
        exportProductDataMessage: action.message
      }
    case actions.IMPORT_PRODUCT_SUCCESS:
    case actions.IMPORT_PRODUCT_FAILURE:
      return {
        importProductData: action.data,
        importProductDataMessage: action.message
      }
    case actions.EXPORT_PACKAGE_SUCCESS:
    case actions.EXPORT_PACKAGE_FAILURE:
      return {
        exportPackageData: action.data,
        exportPackageDataMessage: action.message
      }
    case actions.IMPORT_PACKAGE_SUCCESS:
    case actions.IMPORT_PACKAGE_FAILURE:
      return {
        importPackageData: action.data,
        importPackageDataMessage: action.message
      }
    case actions.VALIDATION_UNIQUE_INDENTIFIER_LIST_SUCCESS:
    case actions.VALIDATION_UNIQUE_INDENTIFIER_LIST_FAILURE:
      return {
        validationUniqueIdentifierData: action.data,
        validationUniqueIdentifierMessage: action.message
      }
    case actions.PUBLISH_UNDO_DRAFT_DATA_SUCCESS:
    case actions.PUBLISH_UNDO_DRAFT_DATA_FAILURE:
      return {
        pubLishUndoStatusMessage: action.data.message,
        pubLishUndoMessage: action.message
      }
    case actions.GET_PRODUCT_CONFIG_SLUG_LIST_SUCCESS:
    case actions.GET_PRODUCT_CONFIG_SLUG_LIST_FAILURE:
      return {
        getAllProductConfigSlugData: action.data?.data,
        getAllProductConfigSlugMessage: action.message
      }
    case actions.ADD_PACKAGE_CONFIG_SUCCESS:
    case actions.ADD_PACKAGE_CONFIG_FAILURE:
      return {
        addPackageConfigData: action.data?.data,
        addPackageConfigMessage: action.message
      }
    case actions.GET_PRODUCT_CONFIG_LIST_SUCCESS:
    case actions.GET_PRODUCT_CONFIG_LIST_FAILURE:
      return {
        getAllProductConfigData: action.data?.data,
        getAllProductConfigMessage: action.message
      }
    case actions.CREATE_ADDON_SUCCESS:
    case actions.CREATE_ADDON_FAILURE:
      return {
        createAddonData: action.data?.data,
        createAddonMessage: action.data?.message
      }
    case actions.GET_LIST_ADDONS_SUCCESS:
    case actions.GET_LIST_ADDONS_FAILURE:
      return {
        ...state,
        getListAddonsData: { ...action.data?.data, ...action.meta },
        getListAddonsMessage: action.message
      }
    case actions.GET_DETAILS_ADDON_SUCCESS:
    case actions.GET_DETAILS_ADDON_FAILURE:
      return {
        ...state,
        getDetailAddonsData: action.data?.data,
        getDetailAddonsMessage: action.message
      }
    case actions.EDIT_ADDON_SUCCESS:
    case actions.EDIT_ADDON_FAILURE:
      return {
        editAddonData: action.data?.data,
        editAddonMessage: action.message
      }
    case actions.UPDATE_PACKAGE_CONFIG_STATUS_SUCCESS:
    case actions.UPDATE_PACKAGE_CONFIG_STATUS_FAILURE:
      return {
        updatePackageConfigstatusData: action.data?.data,
        updatePackageConfigstatusMessage: action.message
      }
    default:
      return state
  }
}
