import actions from './actions'

const initialState = {
  listGroups: [],
  listUsers: [],
  addUserGroupStatus: '',
  message: '',
  removeUserStatus: ''
}

export default function umbrellaReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE:
      return {
        addUserGroupStatus: '',
        removeUserStatus: ''
      }
    case actions.LIST_GROUPS:
      return {
        ...state,
        listGroups: action.data,
        message: action.message
      }
    case actions.FAILED_REMOVE_USER_GROUPS:
      return {
        ...state,
        removeUserStatus: action.removeUserStatus
      }
    case actions.LIST_ALL_USERS:
      return {
        ...state,
        listUsers: action.data,
        message: action.message
      }
    case actions.SUCCESS_ADD_USER_GROUP:
      return {
        ...state,
        addUserGroupStatus: action.addUserGroupStatus
      }
    case actions.FAILED_ADD_USER_GROUP:
      return {
        ...state,
        addUserGroupStatus: action.addUserGroupStatus
      }
    case actions.SUCESS_REMOVE_USER:
      return {
        ...state,
        removeUserStatus: action.removeUserStatus
      }
    default:
      return state
  }
}
