import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import { clearToken } from '../../helpers/utility'
import actions from './actions'
import appActions from '../app/actions'
import callApi from '../../helpers/callApi'
import post from '../../request/methods/post'
import userUrls from '../../request/urls/user'
import Cookies from 'universal-cookie'
import { getCurrentLanguage } from '../../containers/LanguageSwitcher/config'
import { get } from 'lodash'

const cookies = new Cookies()

export function * loginRequest () {
  yield takeEvery(actions.LOGIN_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(post, { ...payload, url: userUrls.loginUser })
      if (res.status === 200) {
        const { token } = res.data
        yield cookies.set('id_token', token, { path: '/' })
        yield put({
          type: actions.LOGIN_SUCCESS,
          data: res.data
        })
        yield put({
          type: actions.CHECK_AUTHORIZATION_REQUEST,
          token
        })
      } else {
        yield put({
          type: actions.LOGIN_FAILURE,
          retriesLeft: 0,
          loginMessage: 'It seems your email or password was wrong!',
          loginData: res.data
        })
      }
    } catch (e) {
      if (e.data) {
        const { retries_left: retriesLeft, message = 'Invalid credentials' } = e.data
        yield put({
          type: actions.LOGIN_FAILURE,
          retriesLeft,
          loginMessage: message,
          loginData: e.data
        })
      } else {
        yield put({ type: actions.LOGIN_FAILURE, loginMessage: 'Error' })
      }
    }
  })
}

export function * getProfileDetail () {
  yield takeEvery(actions.GET_PROFILE_DETAIL_REQUEST, function * () {
    try {
      const response = yield call(callApi.getProfileDetail)
      if (response.status === 200) {
        const {
          user,
          permissions,
          slab,
          product,
          is_customer_service: isCustomerService,
          is_insurance_provider: isInsuranceProvider,
          is_agent_insurance_provider: isAgentInsuranceProvider,
          is_superuser: isSuperUser,
          default_2fa_option: default2FAOption,
          totp_enabled: totpEnabled
        } = response.data
        const language = getCurrentLanguage(user.user_language || 'en')
        yield cookies.set('userProfile', { ...user, isAgentInsuranceProvider }, { path: '/' })
        yield put({
          type: actions.GET_PROFILE_DETAIL_SUCCESS,
          data: {
            profile: {
              ...user,
              permissions,
              default2FAOption,
              totpEnabled
            },
            permissions,
            slab,
            product,
            isCustomerService,
            isInsuranceProvider,
            isAgentInsuranceProvider,
            isSuperUser,
            profileMessage: ''
          }
        })
        yield put({
          type: appActions.CHANGE_LANG_REQUEST,
          language
        })
      } else {
        if (get(response.data, 'reset_request_id')) {
          yield put(actions.logout())
        }
        yield put({
          type: actions.GET_PROFILE_DETAIL_FAILURE,
          data: {
            getUserProfileErrorData: response.data
          },
          profileMessage: 'Failed fetching profile, please try again later'
        })
      }
    } catch (e) {
      if (e.status === 401) {
        yield put(actions.logout())
      }
      yield put({
        type: actions.GET_PROFILE_DETAIL_FAILURE,
        data: {
          getUserProfileErrorData: e.data
        },
        profileMessage: 'Failed fetching profile, please try again later'
      })
    }
  })
}

