export function * logout () {
  yield takeEvery(actions.LOGOUT, function * () {
    yield clearToken()
    // yield put(replace('/'))
  })
}

export function * checkAuthorization () {
  yield takeEvery(actions.CHECK_AUTHORIZATION_REQUEST, function * ({ token }) {
    if (token !== undefined) {
      // TODO: Add endpoint to check token validity, add secret key to backend
      yield put({
        type: actions.CHECK_AUTHORIZATION_SUCCESS,
        token
      })
      yield put({
        type: actions.GET_PROFILE_DETAIL_REQUEST,
        token
      })
    } else {
      yield put({
        type: actions.CHECK_AUTHORIZATION_FAILURE,
        token: null
      })
    }
  })
}

export function * verifyOTP () {
  yield takeEvery(actions.VERIFY_OTP_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(post, { ...payload, url: userUrls.verifyOtp })
      if (res.status === 200) {
        const { token } = res.data
        yield cookies.set('id_token', token, { path: '/' })
        yield put({
          type: actions.VERIFY_OTP_SUCCESS
        })
        yield put({
          type: actions.CHECK_AUTHORIZATION_REQUEST,
          token
        })
      } else {
        yield put({
          type: actions.VERIFY_OTP_FAILURE,
          data: res.error || 'OTP couldn\'t be verified'
        })
      }
    } catch (e) {
      yield put({
        type: actions.VERIFY_OTP_FAILURE,
        data: e.data?.error || 'OTP couldn\'t be verified'
      })
    }
  })
}

export function * resendOTP () {
  yield takeEvery(actions.RESEND_OTP_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(post, { ...payload, url: userUrls.resendOtp })
      if (res.status === 200) {
        yield put({
          type: actions.RESEND_OTP_SUCCESS,
          data: res.data
        })
      } else {
        yield put({
          type: actions.RESEND_OTP_FAILURE,
          data: res.data
        })
      }
    } catch (e) {
      yield put({
        type: actions.RESEND_OTP_FAILURE,
        data: e.data
      })
    }
  })
}

export default function * rootSaga () {
  yield all([
    fork(getProfileDetail),
    fork(getUserDetails),
    fork(checkAuthorization),
    fork(loginRequest),
    fork(logout),
    fork(verifyOTP),
    fork(resendOTP)
  ])
}
