import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function* createDelayRequest() {
  yield takeEvery('CREATE_DELAY', function* (payload) {
    try {
      let res = yield call(callApi.createDelayPolicy, payload)
      if (res.status === 201 || res.status === 200) {
        yield put({ type: actions.CREATE_DELAY_SUCCESS, getCreateDelayStatus: 'success' })
      } else {
        yield put({ type: actions.CREATE_DELAY_FAILED, getCreateDelayStatus: 'Ooops, failed to register your request!' })
      }
    } catch (e) {
      yield put({ type: actions.CREATE_DELAY_FAILED, getCreateDelayStatus: 'Ooops, failed to register your request!' })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(createDelayRequest)
  ])
}
