import _, { get } from 'lodash'
import { all, takeEvery, call, put, fork } from 'redux-saga/effects'

import actions from './actions'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import serviceCenterUrl from '../../../request/urls/serviceCenter'

export function * getServiceCenterList () {
  yield takeEvery(actions.GET_SERVICE_CENTER_LIST_REQUEST, function * ({ payload }) {
    try {
      const query = {}
      if (payload?.source) {
        query.source = payload.source
      }
      const res = yield call(authGet, { url: serviceCenterUrl.getServiceCenterList, query })
      if (res.status === 200) {
        yield put({
          type: actions.GET_SERVICE_CENTER_LIST_SUCCESS,
          data: _.get(res, 'data.data', []),
          success: _.get(res, 'data.success', true)
        })
      } else {
        yield put({
          type: actions.GET_SERVICE_CENTER_LIST_FAILURE,
          data: _.get(res, 'data.data', []),
          message: _.get(res, 'message', 'error'),
          success: _.get(res, 'data.success', true)
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_SERVICE_CENTER_LIST_FAILURE,
        data: [],
        message: _.get(e, 'data.message', 'Error')
      })
    }
  })
}

export function * createServiceCenter () {
  yield takeEvery(actions.CREATE_SERVICE_CENTER_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPost, { url: serviceCenterUrl.createServiceCenter, body: payload })
      if (res.status === 200 || res.status === 201) {
        yield put({
          type: actions.CREATE_SERVICE_CENTER_SUCCESS,
          data: _.get(res, 'data', {}),
          message: _.get(res, 'data.message', 'Service center created')
        })
        yield put({
          type: actions.GET_SERVICE_CENTER_LIST_REQUEST
        })
      } else {
        yield put({
          type: actions.CREATE_SERVICE_CENTER_FAILURE,
          data: _.get(res, 'data.data', {}),
          message: _.get(res, 'data.message', 'There was some issue in creating service center')
        })
      }
    } catch (e) {
      yield put({
        type: actions.CREATE_SERVICE_CENTER_FAILURE,
        data: {},
        message: _.get(e, 'data.message.code', 'Error')
      })
    }
  })
}

