export function * addServicecenterUser () {
  yield takeEvery(actions.ADD_SERVICE_CENTER_USER_REQUEST, function * ({ payload }) {
    try {
      const isEdit = _.get(payload, 'isEdit', false)
      const code = _.get(payload, 'code', '')
      delete payload.isEdit
      let res = null
      if (isEdit) {
        res = yield call(authPost, { url: serviceCenterUrl.editServicecenterUser, body: payload })
      } else {
        res = yield call(authPost, { url: serviceCenterUrl.addServicecenterUser, body: payload, query: { code } })
      }

      if ([200, 201, 202].includes(res.status)) {
        yield put({
          type: actions.ADD_SERVICE_CENTER_USER_SUCCESS,
          data: _.get(res, 'data.data', {}),
          message: _.get(res, 'data.message', '')
        })

        yield put({
          type: actions.GET_SERVICE_CENTER_USER_LIST_REQUEST,
          payload: {
            code
          }
        })
      } else {
        yield put({
          type: actions.ADD_SERVICE_CENTER_USER_FAILURE
        })
      }
    } catch (e) {
      yield put({
        type: actions.ADD_SERVICE_CENTER_USER_FAILURE,
        data: _.get(e, 'data', {}),
        message: _.get(e, 'data.message', 'Error')
      })
    }
  })
}

