export function * submitServiceCenterConfig () {
  yield takeEvery(actions.SUBMIT_SERVICE_CENTER_CONFIG_REQUEST, function * ({ payload }) {
    try {
      const { servicecenter_configs: servicecenteConfigs, serviceuser_code: code, isEdit } = payload
      let res = null
      if (isEdit) {
        res = yield call(authPost, { url: serviceCenterUrl.updateServiceCenterConfig, body: { serviceuser_configs: servicecenteConfigs }, query: { serviceuser_code: code } })
      } else {
        res = yield call(authPost, { url: serviceCenterUrl.submitServiceCenterConfig, body: { servicecenter_configs: servicecenteConfigs }, query: { serviceuser_code: code } })
      }
      if ([200, 201].includes(res.status)) {
        yield put({
          type: actions.SUBMIT_SERVICE_CENTER_CONFIG_SUCCESS,
          data: _.get(res, 'data.data', []),
          message: _.get(res, 'data.message', '')
        })
        yield put({
          type: actions.GET_SERVICE_CENTER_EXISTING_CONFIG_REQUEST,
          payload: {
            serviceuser_code: code
          }
        })
      } else {
        yield put({
          type: actions.SUBMIT_SERVICE_CENTER_CONFIG_FAILURE,
          data: _.get(res, 'data.data', {}),
          message: _.get(res, 'data.message', '')
        })
      }
    } catch (e) {
      yield put({
        type: actions.SUBMIT_SERVICE_CENTER_CONFIG_FAILURE,
        data: _.get(e, 'data', {}),
        message: _.get(e, 'message', '') || _.get(e, 'data.message.error', 'Error')
      })
    }
  })
}

