export default function * rootSaga () {
  yield all([
    fork(getServiceCenterList),
    fork(createServiceCenter),
    fork(updateServiceCenter),
    fork(getServiceCenterDetail),
    fork(uploadBranchBulkDetails),
    fork(getServiceCenterBranchList),
    fork(createServiceCenterBranch),
    fork(updateServiceCenterBranch),
    fork(inactiveBulkServiceCenterBranch),
    fork(getServiceCenterBranchDetails),
    fork(downloadCurrentBranchData),
    fork(changeServicecenterUserStatus),
    fork(addServicecenterUser),
    fork(getServiceCenterUsersList),
    fork(getServiceCenterUserGroupsList),
    fork(submitServiceCenterConfig),
    fork(getServiceCenterDefaultConfig),
    fork(getExistingServiceCenterConfig),
    fork(getServiceCenterBrandList)
  ])
}
