import { all, takeEvery, call, fork, put } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function * getProductDetails () {
  yield takeEvery('GET_PRODUCT_DETAILS', function * () {
    yield put({ type: actions.CREATE_PRODUCT_RESULT, message: undefined })
    yield put({ type: actions.DELETE_PRODUCT_RESULT, message: undefined })
    let res = yield call(callApi.getProductDetails)
    if (res.status === 200) {
      yield put({ type: actions.PRODUCT_DETAILS, data: res.data.results })
    } else {
      yield put({ type: actions.PRODUCT_DETAILS, data: [] })
    }
  })
}

export function * createProduct () {
  yield takeEvery('CREATE_PRODUCT', function * (payload) {
    yield put({ type: actions.CREATE_PRODUCT_RESULT, message: undefined })
    try {
      yield call(callApi.createProduct, payload)
      yield put({ type: actions.CREATE_PRODUCT_RESULT, message: 'success' })
    } catch (e) {
      yield put({ type: actions.CREATE_PRODUCT_RESULT, message: 'error' })
    }
  })
}

export function * deleteProduct () {
  yield takeEvery('DELETE_PRODUCT', function * (payload) {
    yield put({ type: actions.DELETE_PRODUCT_RESULT, message: undefined })
    try {
      yield call(callApi.deleteProduct, payload)
      yield put({ type: actions.DELETE_PRODUCT_RESULT, message: 'success' })
    } catch (e) {
      yield put({ type: actions.DELETE_PRODUCT_RESULT, message: 'error' })
    }
  })
}

export default function * rootSaga () {
  yield all([
    fork(getProductDetails),
    fork(deleteProduct),
    fork(createProduct)

  ])
}
