const actions = {
  GET_AGENT_DATA: 'GET_AGENT_DATA',
  AGENT_DATA: 'AGENT_DATA',
  GET_REFERAL_DATA: 'GET_REFERAL_DATA',
  REFERAL_DATA: 'REFERAL_DATA',
  REFERAL_NOT_FOUND: 'REFERAL_NOT_FOUND',
  getAgentData: () => ({
    type: actions.GET_AGENT_DATA
  }),
  agentData: (payload) => ({
    type: actions.AGENT_DATA,
    payload
  }),
  getReferalData: (payload) => ({
    type: actions.GET_REFERAL_DATA,
    payload
  }),
  referralData: (payload) => ({
    type: actions.REFERAL_DATA,
    payload
  }),
  referralNotFound: (payload) => ({
    type: actions.REFERAL_NOT_FOUND,
    payload
  })
}
export default actions
