import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

export const AgentContext = createContext()

export const AgentContextProvider = ({ children }) => {
  return (
    <AgentContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {children}
    </AgentContext.Provider>
  )
}

export const useAgentContextValue = () => useContext(AgentContext)
