export function* getPartnerListRequest() {
  yield takeEvery(actions.GET_PARTNER_LIST_REQUEST, function* () {
    try {
      const res = yield call(callApi.getPartnerList)
      if (res.status === 200) {
        yield put({ type: actions.GET_PARTNER_LIST_SUCCESS, data: res.data, getDataStatus: 'success' })
      } else {
        yield put({ type: actions.GET_PARTNER_LIST_FAILURE, data: [], getDataStatus: 'Gagal mengambil data gocar simple' })
      }
    } catch (error) {
      yield put({ type: actions.GET_PARTNER_LIST_FAILURE, data: [], getDataStatus: error.message })
    }
  })
}

