export function* removePartnerProductRequest() {
  yield takeEvery('REMOVE_PARTNER_PRODUCT_REQUEST', function* (payload) {
    try {
      const { partnerId } = payload.payload
      const res = yield call(callApi.removePartnerProduct, payload)
      if (res.status === 200) {
        const payload = partnerId
        yield put({ type: actions.GET_PARTNER_DETAILS, payload })
        yield put({ type: actions.REMOVE_PARTNER_PRODUCT_SUCCESS, removePartnerProductStatus: 'success' })
      } else {
        yield put({ type: actions.REMOVE_PARTNER_PRODUCT_FAILURE, removePartnerProductStatus: exceptionsHandler(res.data) })
      }
    } catch (error) {
      yield put({ type: actions.REMOVE_PARTNER_PRODUCT_FAILURE, removePartnerProductStatus: 'Ooops, something went terribly wrong!' })
    }
  })
}

