export function* postUserGroupRequest() {
  yield takeEvery('POST_USER_GROUP', function* (payload) {
    const { partnerId } = payload.payload
    const res = yield call(callApi.postUserGroups, payload)
    if (res.status === 201) {
      const payload = partnerId
      yield put({ type: actions.GET_PARTNER_DETAILS, payload })
      yield put({ type: actions.SUCCESS_POST_NEW_USER, messageAddNewUser: 'success' })
    } else {
      const err = res.data.error
      yield put({
        type: actions.FAILED_POST_NEW_USER,
        messageAddNewUser: parseResponseError(err, 'User fail to added')
      })
    }
  })
}

