export default function* rootSaga() {
  yield all([
    fork(getPartnerListRequest),
    fork(getPartnerDetailsRequest),
    fork(removePartnerProductRequest),
    fork(getProductListRequest),
    fork(postAttachProductRequest),
    fork(activatePartnerUserRequest),
    fork(deactivatePartnerUserRequest),
    fork(getListGroupsRequest),
    fork(postUserGroupRequest),
    fork(postPartnerRequest),
    fork(addPartnerConfig),
    fork(getPartnerConfg),
    fork(getDefaultConfg),
    fork(editPartnerConfig),
    fork(postPartnerImage),
    fork(getTimezoneData),
    fork(getDomainData),
    fork(getWhiteLabelDefaultConfig),
    fork(getWhiteLabelData),
    fork(addWhiteLabelConfig),
    fork(updatePartnerDomainConfig),
    fork(updateBaseUrl),
    fork(updatePartnerUser),
    fork(addPartnerTemplateRequest),
    fork(addProductTemplateRequest),
    fork(getPartnerProductTemplateRequest),
    fork(enableDisablePackage),
    fork(generateApiSpecPackage),
    fork(getPartnerClientList),
    fork(getAllPartnerClientList),
    fork(attachPartnerClient),
    fork(detachPartnerClient)
  ])
}
