export function* getCouponProductList() {
  yield takeEvery('GET_COUPON_PRODUCT_LIST', function* (payload) {
    try {
      let res = yield call(callApi.getCouponProductList, payload)
      if (res.status === 200) {
        yield put({ type: actions.PRODUCT_LIST, data: res.data.products })
      } else {
        yield put({ type: actions.PRODUCT_LIST, data: [] })
      }
    } catch (e) {
      yield put({ type: actions.PRODUCT_LIST, data: [] })
    }
  })
}

export function* getCouponPackageList() {
  yield takeEvery(actions.GET_COUPON_PACKAGE_LIST_REQUEST, function* (payload) {
    try {
      const res = yield call(callApi.getCouponPackageList, payload)
      if (res.status === 200) {
        yield put({ type: actions.GET_COUPON_PACKAGE_LIST_SUCCESS, data: res.data, message: 'success' })
      } else {
        yield put({ type: actions.GET_COUPON_PACKAGE_LIST_FAILURE, data: [], message: 'success' })
      }
    } catch (e) {
      yield put({ type: actions.GET_COUPON_PACKAGE_LIST_FAILURE, data: [], message: e.data.message })
    }
  })
}

export function* createPromo() {
  yield takeEvery('CREATE_PROMO', function* (payload) {
    yield put({ type: actions.CREATE_PROMO_RESULT, message: undefined })
    try {
      const res = yield call(callApi.createPromo, payload)
      yield put({ type: actions.CREATE_PROMO_RESULT, message: res.data.message })
    } catch (e) {
      yield put({ type: actions.CREATE_PROMO_RESULT, message: e.data.message })
    }
  })
}

