export function* uploadCouponImages() {
  yield takeEvery('UPLOAD_IMAGE_COUPON', function* (payload) {
    try {
      let res = yield call(callApi.uploadCouponImage, payload)
      yield put({ type: actions.UPLOAD_COUPON_IMAGE_LIST, data: [], status: 'initial' })
      if (res.status === 200 || res.status === 201) {
        yield put({ type: actions.UPLOAD_COUPON_IMAGE_LIST, data: [res.data], status: 'success' })
      } else {
        yield put({ type: actions.UPLOAD_COUPON_IMAGE_LIST, data: [], status: 'failure' })
      }
    } catch (e) {
      yield put({ type: actions.UPLOAD_COUPON_IMAGE_LIST, data: [], status: 'failure' })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(getPromoDetails),
    fork(getCouponDetails),
    fork(createPromo),
    fork(updatePromo),
    fork(createCoupon),
    fork(updateCoupon),
    fork(getCouponProductList),
    fork(getCouponPackageList),
    fork(uploadCouponImages)
  ])
}
