import React from 'react'

class PermissionChecker extends React.Component {
  render () {
    const { permissionGetter, permissionSetter } = this.props
    if (permissionGetter !== undefined && permissionGetter.length > 0) {
      if (permissionGetter.indexOf(permissionSetter) > -1) {
        return this.props.children
      }
    }
    return null
  }
}

export default PermissionChecker
