const actions = {
  CHECK_AUTHORIZATION_REQUEST: 'CHECK_AUTHORIZATION_REQUEST',
  CHECK_AUTHORIZATION_SUCCESS: 'CHECK_AUTHORIZATION_SUCCESS',
  CHECK_AUTHORIZATION_FAILURE: 'CHECK_AUTHORIZATION_FAILURE',
  LOGIN_REQUEST: 'LOGIN_REQUEST',
  LOGIN_SUCCESS: 'LOGIN_SUCCESS',
  LOGIN_FAILURE: 'LOGIN_FAILURE',
  LOGOUT: 'LOGOUT',
  PROFILE_DETAIL: 'PROFILE_DETAIL',

  GET_PROFILE_DETAIL_REQUEST: 'GET_PROFILE_DETAIL_REQUEST',
  GET_PROFILE_DETAIL_SUCCESS: 'GET_PROFILE_DETAIL_SUCCESS',
  GET_PROFILE_DETAIL_FAILURE: 'GET_PROFILE_DETAIL_FAILURE',
  FAILED_GET_PROFILE_DETAIL: 'FAILED_GET_PROFILE_DETAIL',

  GET_USER_DETAIL_REQUEST: 'GET_USER_DETAIL_REQUEST',

  RESET_STATE_AUTH: 'RESET_STATE_AUTH',

  VERIFY_OTP_REQUEST: 'VERIFY_OTP_REQUEST',
  VERIFY_OTP_SUCCESS: 'VERIFY_OTP_SUCCESS',
  VERIFY_OTP_FAILURE: 'VERIFY_OTP_FAILURE',

  RESEND_OTP_REQUEST: 'RESEND_OTP_REQUEST',
  RESEND_OTP_SUCCESS: 'RESEND_OTP_SUCCESS',
  RESEND_OTP_FAILURE: 'RESEND_OTP_FAILURE',

  checkAuthorization: (token) => ({ type: actions.CHECK_AUTHORIZATION_REQUEST, token }),
  login: (payload) => ({
    type: actions.LOGIN_REQUEST,
    payload
  }),
  failed: ({ message }) => ({
    type: actions.LOGIN_FAILURE,
    message
  }),
  logout: () => ({
    type: actions.LOGOUT
  }),
  getProfileDetail: () => ({
    type: actions.GET_PROFILE_DETAIL
  }),
  profileDetail: (payload) => ({
    type: actions.PROFILE_DETAIL,
    payload
  }),
  failedGetProfileDetail: payload => ({
    type: actions.FAILED_GET_PROFILE_DETAIL,
    payload
  }),
  resetStateAuth: () => ({
    type: actions.RESET_STATE_AUTH
  }),
  verifyOtp: payload => ({
    type: actions.VERIFY_OTP_REQUEST,
    payload
  }),
  resendOtp: payload => ({
    type: actions.RESEND_OTP_REQUEST,
    payload
  })
}
export default actions
