import actions from './actions'

const initialState = {
  searchResult: [],
  searchResultMeta: {},
  searchMessage: '',
  customerData: {},
  getCustomerMessage: '',
  policyData: [],
  policyMessage: '',
  claimData: [],
  claimMessage: '',
  editCustomerMessage: '',
  editContactMessage: '',
  policyMetaData: {}
}

export default function customerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_CUSTOMER:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state,
          ...initialState
        }
      }
    case actions.SEARCH_CUSTOMER_SUCCESS:
    case actions.SEARCH_CUSTOMER_FAILURE:
      return {
        ...state,
        searchResult: action.searchResult,
        searchResultMeta: action.searchResultMeta,
        searchMessage: action.searchMessage
      }
    case actions.GET_CUSTOMER_SUCCESS:
    case actions.GET_CUSTOMER_FAILURE:
      return {
        ...state,
        customerData: action.customerData,
        getCustomerMessage: action.getCustomerMessage
      }
    case actions.GET_POLICY_CUSTOMER_SUCCESS:
    case actions.GET_POLICY_CUSTOMER_FAILURE:
      return {
        ...state,
        policyData: action.policyData,
        policyMetaData: action.policyMetaData,
        policyMessage: action.policyMessage
      }
    case actions.GET_CLAIM_CUSTOMER_SUCCESS:
    case actions.GET_CLAIM_CUSTOMER_FAILURE:
      return {
        ...state,
        claimData: action.claimData,
        claimMessage: action.claimMessage
      }
    case actions.PATCH_EDIT_CUSTOMER_SUCCESS:
    case actions.PATCH_EDIT_CUSTOMER_FAILURE:
      return {
        ...state,
        editCustomerMessage: action.editCustomerMessage
      }
    case actions.PUT_EDIT_CONTACT_SUCCESS:
    case actions.PUT_EDIT_CONTACT_FAILURE:
      return {
        ...state,
        editContactMessage: action.editContactMessage
      }
    default:
      return state
  }
}
