import actions from './actions'

const initialState = {
  referralData: {},
  agentData: []
}

export default function umbrellaReducer (state = initialState, action) {
  switch (action.type) {
    case actions.REFERAL_DATA:
      return { ...state, referralData: action.data, message: '' }
    case actions.AGENT_DATA:
      return { ...state, agentData: action.data }
    case actions.REFERAL_NOT_FOUND:
      return { ...state, message: action.message }
    default:
      return state
  }
}
