export function* getTemplatesRequest() {
  yield takeEvery('GET_TEMPLATES', function* () {
    try {
      let res = yield call(callApi.getTemplates)
      if (res.status === 200) {
        yield put({ type: actions.DATA_TEMPLATES_SUCCESS, data: res.data, getTemplatesStatus: 'success' })
      } else {
        yield put({ type: actions.DATA_TEMPLATES_FAILURE, data: [], getTemplatesStatus: '' })
      }
    } catch (error) {
      yield put({ type: actions.DATA_TEMPLATES_FAILURE, data: [], getTemplatesStatus: error.message })
    }
  })
}

