const VALIDATION_ERROR_KEYS = ['order_by', 'order_dir', 'search_by', 'non_field_errors']

function hasValidationError (data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return false
  return VALIDATION_ERROR_KEYS.some(key => key in data)
}

