import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../../state/employeeBenefit/reducer'

export const EBContext = createContext()

export const EBContextProvider = (props) => {
  return (
    <EBContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </EBContext.Provider>
  )
}

export const useEBContextValue = () => useContext(EBContext)
