import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import urls from '../../../config/urls'
import claimDashboardUrls from '../../../request/urls/claimDashboard'
import { get } from 'lodash'

const configUrl = urls.url

export function * getIrisBalanceData () {
  yield takeEvery(actions.GET_IRIS_BALANCE_REQUEST, function * () {
    try {
      const res = yield call(authGet, { url: configUrl.irisBalance })
      if (res.status === 200) {
        yield put({
          type: actions.GET_IRIS_BALANCE_SUCCESS,
          data: Number(res.data.balance)
        })
      } else {
        yield put({
          type: actions.GET_IRIS_BALANCE_FAILURE,
          data: 'Error'
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_IRIS_BALANCE_FAILURE,
        data: 'Error'
      })
    }
  })
}

