export default function * rootSaga () {
  yield all([
    fork(getIrisBalanceData),
    fork(getXenditBalanceData),
    fork(getAllOpenClaims),
    fork(getPartnerOpenClaims),
    fork(getOperationsOpenClaims),
    fork(getDayWiseOpenClaims),
    fork(getIrisPPIBalance),
    fork(getIrisAusBalance)
  ])
}
