import { all, takeEvery, call, fork, put } from 'redux-saga/effects'
import actions from './actions'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import urls from '../../../request/urls/tapinsure'

export function* addUpdateList () {
    yield takeEvery(actions.ADD_UPDATE_FINANCIAL_REPORTS_REQUEST, function* ({ payload }) {
      try {
        const res = yield call(authPost, {
          body: payload,
          url: urls.addEditFileUrl
        })
        if (res.status === 200 || res.status === 201) {
          yield put({
            type: actions.ADD_UPDATE_FINANCIAL_REPORTS_SUCCESS,
            data: res.data,
            addUpdateMessage: 'success'
          })
        } else {
          yield put({
            type: actions.ADD_UPDATE_FINANCIAL_REPORTS_FAILURE,
            data: [],
            addUpdateMessage: 'error'
          })
        }
      } catch (error) {
        yield put({
          type: actions.ADD_UPDATE_FINANCIAL_REPORTS_FAILURE,
          data: [],
          addUpdateMessage: 'error'
        })
      }
    })
  }

export function * getWorkshopList () {
    yield takeEvery(actions.GET_WORKSHOP_REPORTS_REQUEST, function * ({ payload }) {
      try {
        const res = yield call(authGet, {
          query: payload.query,
          url: urls.getWorkshopdetailsUrl
        })
        if (res.status === 200) {
          yield put({
            type: actions.GET_WORKSHOP_REPORTS_SUCCESS,
            data: res.data,
            getWorkshoplListMessage: 'success'
          })
        } else {
          yield put({
            type: actions.GET_WORKSHOP_REPORTS_FAILURE,
            data: [],
            getWorkshoplListMessage: 'error'
          })
        }
      } catch (error) {
        yield put({
          type: actions.GET_WORKSHOP_REPORTS_FAILURE,
          data: [],
          getWorkshoplListMessage: error.message
        })
      }
    })
  }

export default function * rootSaga () {
  yield all([
    fork(addUpdateList),
    fork(getWorkshopList),
  ])
}
