const actions = {
  CREATE_JD_POLICY: 'CREATE_JD_POLICY',
  CREATE_JD_SUCCESS: 'CREATE_JD_SUCCESS',
  CREATE_JD_FAILED: 'CREATE_JD_FAILED',
  RESET_REDUX_STATE_DEMO: 'RESET_REDUX_STATE_DEMO',
  CREATE_OAG_NOTIF: 'CREATE_OAG_NOTIF',
  CREATE_OAG_NOTIF_SUCCESS: 'CREATE_OAG_NOTIF_SUCCESS',
  CREATE_OAG_NOTIF_FAILED: 'CREATE_OAG_NOTIF_FAILED',
  createJDPolicy: payload => ({
    type: actions.CREATE_JD_POLICY,
    payload
  }),
  successCreateJDPolicy: payload => ({ // eslint-disable-line
    type: actions.CREATE_JD_SUCCESS,
    payload
  }),
  failedCreateJDPolicy: payload => ({ // eslint-disable-line
    type: actions.CREATE_JD_FAILED,
    payload
  }),
  resetStateDemo: () => ({
    type: actions.RESET_REDUX_STATE_DEMO
  }),
  createOAGNotif: payload => ({
    type: actions.CREATE_OAG_NOTIF,
    payload
  }),
  successCreateJDPolicy: payload => ({ // eslint-disable-line
    type: actions.CREATE_OAG_NOTIF_SUCCESS,
    payload
  }),
  failedCreateJDPolicy: payload => ({ // eslint-disable-line
    type: actions.CREATE_OAG_NOTIF_FAILED,
    payload
  })
}
export default actions
