import { MERCHANT } from './actions'

export const INITIAL_STATE = {}

const reducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case MERCHANT.ADD_MERCHANT:
    case MERCHANT.GET_MERCHANT_LIST:
    case MERCHANT.GET_STORE_LIST:
    case MERCHANT.GET_MERCHANT_DETAIL:
    case MERCHANT.GET_EMPLOYEE_LIST:
    case MERCHANT.ADD_STORE:
    case MERCHANT.ADD_EMPLOYEE:
    case MERCHANT.ACTIVATE_USER:
    case MERCHANT.DEACTIVATE_USER:
    case MERCHANT.EDIT_BANK_DETAIL:
    case MERCHANT.EDIT_EMPLOYEE_DETAIL:
    case MERCHANT.EDIT_MERCHANT_DETAIL:
    case MERCHANT.GET_STORE_ALL_LIST:
    case MERCHANT.FREE_STORE:
    case MERCHANT.MUTATE_STORE:
      return { ...state, ...payload }
    case MERCHANT.RESET_REDUX_STATE_MERCHANT:
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = INITIAL_STATE[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    default:
      return state
  }
}

export default reducer
