import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function* getListGroupRequest() {
  yield takeEvery('GET_LIST_TEAM_GROUPS', function* (payload) {
    try {
      let res = yield call(callApi.getListGroupsCall)
      if (res.status === 200) {
        yield put({ type: actions.LIST_GROUPS, data: res.data, message: payload })
      }
    } catch (error) {
      yield put({ type: actions.LIST_GROUPS, data: [] })
    }
  })
}

export function* removeUserGroupRequest() {
  yield takeEvery('REMOVE_USER_GROUPS', function* (payload) {
    try {
      let res = yield call(callApi.removeUserGroups, payload)
      if (res.status === 200) {
        yield put({ type: actions.GET_LIST_TEAM_GROUPS })
        yield put({ type: actions.SUCESS_REMOVE_USER, removeUserStatus: 'success' })
      } else {
        yield put({ type: actions.FAILED_REMOVE_USER_GROUPS, removeUserStatus: 'failed to remove user!' })
      }
    } catch (e) {
      yield put({ type: actions.FAILED_REMOVE_USER_GROUPS, removeUserStatus: 'failed to remove user!' })
    }
  })
}

export function* getAllUsersRequest() {
  yield takeEvery('GET_ALL_USERS', function* (payload) {
    try {
      let res = yield call(callApi.getAllUsers, payload)
      if (res) {
        yield put({ type: actions.LIST_ALL_USERS, data: res })
      }
    } catch (e) {
      yield put({ type: actions.LIST_ALL_USERS, data: [] })
    }
  })
}

export function* postUserGroupRequest() {
  yield takeEvery('ADD_USER_GROUP', function* (payload) {
    try {
      let res = yield call(callApi.addUserGroup, payload)
      if (res.status === 200) {
        yield put({ type: actions.GET_LIST_TEAM_GROUPS })
        yield put({ type: actions.SUCCESS_ADD_USER_GROUP, addUserGroupStatus: 'success' })
      } else {
        yield put({ type: actions.FAILED_ADD_USER_GROUP, addUserGroupStatus: 'failed to add user!' })
      }
    } catch (e) {
      yield put({ type: actions.FAILED_ADD_USER_GROUP, addUserGroupStatus: 'failed to add user!' })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(getListGroupRequest),
    fork(removeUserGroupRequest),
    fork(getAllUsersRequest),
    fork(postUserGroupRequest)
  ])
}
