import { all, takeEvery, call, fork, put } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function* getImgPrcRequest() {
  yield takeEvery('GET_IMG_PRC_LIST', function* () {
    try {
      let res = yield call(callApi.getImgProcessorList)
      if (res.status === 200) {
        yield put({ type: actions.IMG_PROCESSOR_DATA, data: res.data, getImgProcessorMessage: 'success' })
      } else {
        yield put({ type: actions.IMG_PROCESSOR_DATA, data: [], getImgProcessorMessage: 'Ooops, something went terribly wrong!' })
      }
    } catch (e) {
      yield put({ type: actions.IMG_PROCESSOR_DATA, data: [], getImgProcessorMessage: 'Ooops, something went terribly wrong!' })
    }
  })
}

export function* getImgPrcDetailRequest() {
  yield takeEvery('GET_IMG_PRC_DETAIL', function* (payload) {
    try {
      let res = yield call(callApi.getImgProcessorDetail, payload)
      if (res.status === 200) {
        yield put({ type: actions.IMG_PROCESSOR_DETAIL, data: res.data, getImgProcessorDetailMessage: 'success' })
      } else {
        yield put({ type: actions.IMG_PROCESSOR_DETAIL, data: [], getImgProcessorDetailMessage: 'Ooops, something went terribly wrong!' })
      }
    } catch (e) {
      yield put({ type: actions.IMG_PROCESSOR_DETAIL, data: [], getImgProcessorDetailMessage: 'Ooops, something went terribly wrong!' })
    }
  })
}

export function* uploadBoardingPassRequest() {
  yield takeEvery('UPLOAD_IMG_PROCESSOR', function* (payload) {
    try {
      let res = yield call(callApi.uploadImgProcessor, payload)
      if (res.status === 201) {
        yield put({ type: actions.GET_IMG_PRC_LIST })
        yield put({ type: actions.UPLOAD_IMG_PROCESSOR_STATUS, uploadImgProcessorStatus: 'success' })
      } else {
        yield put({ type: actions.UPLOAD_IMG_PROCESSOR_STATUS, uploadImgProcessorStatus: 'Please connect to internet.' })
      }
    } catch (e) {
      yield put({ type: actions.UPLOAD_IMG_PROCESSOR_STATUS, uploadImgProcessorStatus: 'Please connect to internet.' })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(getImgPrcRequest),
    fork(getImgPrcDetailRequest),
    fork(uploadBoardingPassRequest)
  ])
}
