import actions from './actions'

const initialState = {
  approvalListData: [],
  approvalListMessage: '',
  approvalListMetaData: {},
  approvalSuccess: null,
  approvalDetailData: {},
  approvalData: {}
}

export default function approvalListReducer (state = initialState, action) {
  switch (action.type) {
    case actions.GET_APPROVAL_LIST_SUCCESS:
      return {
        ...state,
        approvalListData: action.approvalListData,
        approvalListMessage: action.approvalListMessage,
        approvalListMetaData: action.approvalListMetaData,
        approvalSuccess: true
      }
    case actions.GET_APPROVAL_LIST_FAILURE:
      return {
        ...state,
        approvalListData: action.approvalListData,
        approvalListMessage: action.approvalListMessage,
        approvalListMetaData: action.approvalListMetaData,
        approvalSuccess: false
      }

    case actions.GET_APPROVAL_DETAIL_SUCCESS:
    case actions.GET_APPROVAL_DETAIL_FAILURE:
      return {
        ...state,
        approvalDetailData: action.approvalDetailData,
        approvalListMessage: action.approvalListMessage
      }

    case actions.UPDATE_QUOTATION_STATUS_SUCCESS:
      return {
        ...state,
        approvalData: action.approvalData,
        approvalListMessage: action.approvalListMessage,
        approvalSuccess: true
      }
    case actions.UPDATE_QUOTATION_STATUS_FAILURE:
      return {
        ...state,
        approvalData: action.approvalData,
        approvalListMessage: action.approvalListMessage,
        approvalSuccess: false
      }
    default:
      return state
  }
}
