import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { notification, Form, Row } from 'antd'
import { Link } from 'react-router-dom'
import { connect } from 'react-redux'
import _ from 'lodash/object'
import { get } from 'lodash'

import Input from '../../components/uielements/input'
import Button from '../../components/uielements/button'
import authAction from '../../redux/auth/actions'
import loadingActions from '../../redux/loading/actions'
import errorActions from '../../redux/error/actions'
import SignInStyleWrapper from './signin.style'

const REACT_APP_CAPTCHA_SITE_KEY = process.env.REACT_APP_CAPTCHA_SITE_KEY

const FormItem = Form.Item

const { login, resetStateAuth } = authAction
const { resetErrorRedux } = errorActions
const { resetLoadingRedux } = loadingActions

class SignIn extends Component {
  constructor (props) {
    super(props)
    this.captcha = React.createRef()
  }

  loadRecaptcha = () => {
    if (window?.grecaptcha?.render) {
      const wrapper = document.createElement('div')
      this._widgetId = window.grecaptcha.render(wrapper, {
        sitekey: REACT_APP_CAPTCHA_SITE_KEY,
        callback: this.onSubmit
      })
      this.captcha.appendChild(wrapper)
    }
  }

  componentDidMount () {
    if (window?.grecaptcha?.render) {
      this.loadRecaptcha()
    } else {
      let attempts = 3
      while (attempts) {
        setTimeout(() => {
          this._widgetId === undefined && this.loadRecaptcha()
        }, 1000 * (4 - attempts))
        attempts--
      }
    }
    this.props.resetLoadingRedux(['LOGIN'])
    this.props.resetErrorRedux(['LOGIN'])
  }

  componentDidUpdate () {
    const { loginLoading, loginError } = this.props
    if (!loginLoading && loginError) {
      window?.grecaptcha && window.grecaptcha.reset(this._widgetId)
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { isLoggedIn, loginData = {}, loginLoading, loginError, loginMessage } = nextProps
    if (loginLoading === false) {
      if (loginError) {
        notification.error({ message: loginMessage })
        if (get(loginData, 'reset_request_id')) {
          const resetRequestID = get(loginData, 'reset_request_id')
          this.props.history.push(`/reset_password/${resetRequestID}`)
        }
        this.props.form.resetFields(['captcha_response'])
      } else {
        this.props.history.push('/auth')
      }
      this.props.resetLoadingRedux(['LOGIN'])
      this.props.resetErrorRedux(['LOGIN'])
    }

    if (isLoggedIn) {
      const from = _.get(this.props, 'history.location.state.from', { pathname: '/' })
      this.props.history.push(from)
    }
  }

  handleRecaptchaRef = (elem) => {
    this.captcha = elem
  }

  onSubmit = (token) => {
    this.props.form.setFieldsValue({ captcha_response: token })
  }

  handleLogin = e => {
    e.preventDefault()
    this.props.form.validateFields((error, values) => {
      if (!error) {
        this.props.login({
          body: values
        })
      }
    })
  }

  render () {
    const {
      loginLoading,
      form
    } = this.props
    const { getFieldDecorator } = form

    return (
      <SignInStyleWrapper className='isoSignInPage'>
        <div className='isoLoginContentWrapper'>
          <div className='isoLoginContent'>
            <div className='isoLogoWrapper'>
              <Link to=''>
                Operations Panel
              </Link>
            </div>
            <Form onSubmit={this.handleLogin}>
              <FormItem>
                {getFieldDecorator('username', {
                  rules: [
                    { required: true, message: 'Email can not be empty' }
                  ]
                })(
                  <Input
                    placeholder='Email ID'
                  />
                )}
              </FormItem>
              <FormItem>
                {getFieldDecorator('password', {
                  rules: [
                    { required: true, message: 'Password can not be empty' }
                  ]
                })(
                  <Input
                    type='password'
                    placeholder='Password'
                  />
                )}
              </FormItem>
              <FormItem>
                {getFieldDecorator('captcha_response', {
                  rules: [
                    { required: true, message: 'Captcha can not be empty' }
                  ]
                })(
                  <div
                    className='g-recaptcha'
                    id='recaptcha'
                    ref={this.handleRecaptchaRef}
                    data-sitekey={REACT_APP_CAPTCHA_SITE_KEY}
                  />
                )}
              </FormItem>
              <Row type='flex' justify='space-between' align='middle'>
                <Link to='/forgot-password' className='isoForgotPass'>
                  Forgot password
                </Link>
                <Button
                  htmlType='submit'
                  type='primary'
                  loading={!!loginLoading}
                >
                  Sign in
                </Button>
              </Row>
            </Form>
          </div>
        </div>
      </SignInStyleWrapper>
    )
  }
}

SignIn.propTypes = {
  isLoggedIn: PropTypes.bool.isRequired,
  profile: PropTypes.object.isRequired
}

SignIn.defaultProps = {
  isLoggedIn: false,
  profile: {}
}

const WrappedForm = Form.create()(SignIn)

export default connect(
  state => ({
    isLoggedIn: !!state.Auth.idToken,
    profile: state.Auth.profile,
    loginMessage: state.Auth.loginMessage,
    retriesLeft: state.Auth.retriesLeft,
    loginData: state.Auth.loginData,
    loginLoading: state.Loading.LOGIN,
    loginError: state.Error.LOGIN
  }),
  {
    login,
    resetStateAuth,
    resetErrorRedux,
    resetLoadingRedux
  }
)(WrappedForm)
