import actions from './action'

const initialState = {
  webhookEventType: [],
  webhookList: [],
  createWebhookMessage: '',
  updateWebhookMessage: ''
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.GET_EVENT_TYPE_SUCCESS:
    case actions.GET_EVENT_TYPE_FAILURE:
      return {
        ...state,
        webhookEventType: action.data
      }
    case actions.GET_WEBHOOK_LIST_SUCCESS:
    case actions.GET_WEBHOOK_LIST_FAILURE:
      return {
        ...state,
        webhookList: action.data
      }
    case actions.CREATE_WEBHOOK_SUCCESS:
    case actions.CREATE_WEBHOOK_FAILURE:
      return {
        ...state,
        createWebhookMessage: action.message
      }
    case actions.UPDATE_WEBHOOK_SUCCESS:
    case actions.UPDATE_WEBHOOK_FAILURE:
      return {
        ...state,
        updateWebhookMessage: action.message
      }
    case actions.GET_FUNCTIONS_SUCCESS:
    case actions.GET_FUNCTIONS_FAILURE:
      return {
        ...state,
        webhookFunctions: action.data
      }
    case actions.GET_HEADERS_SUCCESS:
    case actions.GET_HEADERS_FAILURE:
      return {
        ...state,
        webhookHeaders: action.data
      }
    default:
      return state
  }
}
