const actions = {
  // List
  LIST_HARDCOPY_REQUEST: 'LIST_HARDCOPY_REQUEST',
  LIST_HARDCOPY_SUCCESS: 'LIST_HARDCOPY_SUCCESS',
  LIST_HARDCOPY_FAILURE: 'LIST_HARDCOPY_FAILURE',

  // Detail
  GET_HARDCOPY_REQUEST: 'GET_HARDCOPY_REQUEST',
  GET_HARDCOPY_SUCCESS: 'GET_HARDCOPY_SUCCESS',
  GET_HARDCOPY_FAILURE: 'GET_HARDCOPY_FAILURE',

  // Progress CTA
  PROGRESS_HARDCOPY_REQUEST: 'PROGRESS_HARDCOPY_REQUEST',
  PROGRESS_HARDCOPY_SUCCESS: 'PROGRESS_HARDCOPY_SUCCESS',
  PROGRESS_HARDCOPY_FAILURE: 'PROGRESS_HARDCOPY_FAILURE',

  // Reject CTA
  REJECT_HARDCOPY_REQUEST: 'REJECT_HARDCOPY_REQUEST',
  REJECT_HARDCOPY_SUCCESS: 'REJECT_HARDCOPY_SUCCESS',
  REJECT_HARDCOPY_FAILURE: 'REJECT_HARDCOPY_FAILURE',

  RESET_HARDCOPY_STATE: 'RESET_HARDCOPY_STATE',

  listHardcopy: (payload) => ({ type: actions.LIST_HARDCOPY_REQUEST, payload }),
  getHardcopy: (payload) => ({ type: actions.GET_HARDCOPY_REQUEST, payload }),
  progressHardcopy: (payload) => ({ type: actions.PROGRESS_HARDCOPY_REQUEST, payload }),
  rejectHardcopy: (payload) => ({ type: actions.REJECT_HARDCOPY_REQUEST, payload }),
  resetHardcopyState: (payload) => ({ type: actions.RESET_HARDCOPY_STATE, payload })
}

export default actions
