const actions = {
  GET_TRANSLATIONS_REQUEST: 'GET_TRANSLATIONS_REQUEST',
  GET_TRANSLATIONS_SUCCESS: 'GET_TRANSLATIONS_SUCCESS',
  GET_TRANSLATIONS_FAILURE: 'GET_TRANSLATIONS_FAILURE',
  POST_TRANSLATIONS_REQUEST: 'POST_TRANSLATIONS_REQUEST',
  POST_TRANSLATIONS_SUCCESS: 'POST_TRANSLATIONS_SUCCESS',
  POST_TRANSLATIONS_FAILURE: 'POST_TRANSLATIONS_FAILURE',
  POST_TRANSLATIONS_ENTRY_REQUEST: 'POST_TRANSLATIONS_ENTRY_REQUEST',
  POST_TRANSLATIONS_ENTRY_SUCCESS: 'POST_TRANSLATIONS_ENTRY_SUCCESS',
  POST_TRANSLATIONS_ENTRY_FAILURE: 'POST_TRANSLATIONS_ENTRY_FAILURE',
  RESET_TRANSLATIONS_REDUX: 'RESET_TRANSLATIONS_REDUX',
  getTranslations: (payload) => ({
    type: actions.GET_TRANSLATIONS_REQUEST,
    payload
  }),
  postTranslations: (payload) => ({
    type: actions.POST_TRANSLATIONS_REQUEST,
    payload
  }),
  postTranslationsEntry: (payload) => ({
    type: actions.POST_TRANSLATIONS_ENTRY_REQUEST,
    payload
  }),
  resetTranslationsRedux: (payload) => ({
    type: actions.RESET_TRANSLATIONS_REDUX,
    payload
  })
}
export default actions
