import { all, call, put, takeEvery, fork } from 'redux-saga/effects'
import actions from './actions'
import exceptionHandlerSanitizer from '../../../middleware/exceptions'
import urls from '../../../config/urls'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'

const configUrl = urls.url

export function * getApprovalListSaga () {
  yield takeEvery(actions.GET_APPROVAL_LIST_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, { query: payload, url: configUrl.getApprovalListAuto })
      if (res.status === 200) {
        const approvalListData = res.data.data
        const approvalListMessage = res.data.message
        const approvalListMetaData = res.data.pagination
        yield put({
          type: actions.GET_APPROVAL_LIST_SUCCESS,
          approvalListData,
          approvalListMessage,
          approvalListMetaData
        })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({
          type: actions.GET_APPROVAL_LIST_FAILURE,
          approvalListMessage: message
        })
      }
    } catch (error) {
      const message = exceptionHandlerSanitizer(error.data)
      yield put({
        type: actions.GET_APPROVAL_LIST_FAILURE,
        approvalListMessage: message
      })
    }
  })
}

