export function * updateQuotationStatusSaga () {
  yield takeEvery(actions.UPDATE_QUOTATION_STATUS_REQUEST, function * ({ payload }) {
    console.log('payload', payload)
    try {
      const res = yield call(authPost, { body: payload, url: configUrl.updateQuotationStatusAuto })

      if (res.status === 200) {
        const approvalData = res.data.data
        const approvalListMessage = res.data.message
        yield put({
          type: actions.UPDATE_QUOTATION_STATUS_SUCCESS,
          approvalData,
          approvalListMessage
        })
      }
    } catch (error) {
      const message = exceptionHandlerSanitizer(error.data)
      yield put({
        type: actions.UPDATE_QUOTATION_STATUS_FAILURE,
        approvalListMessage: message
      })
    }
  })
}

export default function * approvalListSaga () {
  yield all([
    fork(getApprovalListSaga),
    fork(getApprovalDetailSaga),
    fork(updateQuotationStatusSaga)
  ])
}
