const actions = {
  GET_APPROVAL_LIST_REQUEST: 'GET_APPROVAL_LIST_REQUEST',
  GET_APPROVAL_LIST_SUCCESS: 'GET_APPROVAL_LIST_SUCCESS',
  GET_APPROVAL_LIST_FAILURE: 'GET_APPROVAL_LIST_FAILURE',

  GET_APPROVAL_DETAIL_REQUEST: 'GET_APPROVAL_DETAIL_REQUEST',
  GET_APPROVAL_DETAIL_SUCCESS: 'GET_APPROVAL_DETAIL_SUCCESS',
  GET_APPROVAL_DETAIL_FAILURE: 'GET_APPROVAL_DETAIL_FAILURE',

  UPDATE_QUOTATION_STATUS_REQUEST: 'UPDATE_QUOTATION_STATUS_REQUEST',
  UPDATE_QUOTATION_STATUS_SUCCESS: 'UPDATE_QUOTATION_STATUS_SUCCESS',
  UPDATE_QUOTATION_STATUS_FAILURE: 'UPDATE_QUOTATION_STATUS_FAILURE',

  getApprovalList: payload => ({
    type: actions.GET_APPROVAL_LIST_REQUEST,
    payload
  }),

  getApprovalDetail: payload => ({
    type: actions.GET_APPROVAL_DETAIL_REQUEST,
    payload
  }),

  updateQuotationStatus: payload => ({
    type: actions.UPDATE_QUOTATION_STATUS_REQUEST,
    payload
  })
}

export default actions
