import actions from './actions'

const initialState = {
  promoDetails: [],
  couponDetails: [],
  promoMessage: undefined,
  createPromoMessage: undefined,
  couponMessage: undefined,
  productLists: undefined,
  packageLists: undefined,
  packageListsMessage: undefined,
  imageData: [],
  status: undefined
}

export default function promoReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_PROMO_DETAIL:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    case actions.PROMO_DETAILS:
      return {
        ...state,
        promoDetails: action.data
      }
    case actions.COUPON_DETAILS:
      return {
        ...state,
        couponDetails: action.data
      }
    case actions.SUCCESS_CREATE_PROMO:
      return {
        ...state,
        message: action.message
      }
    case actions.SUCCESS_CREATE_COUPON:
      return {
        ...state,
        message: action.message
      }
    case actions.FAILURE_CREATE_PROMO:
      return {
        ...state,
        message: action.message
      }
    case actions.FAILURE_CREATE_COUPON:
      return {
        ...state,
        message: action.message
      }
    case actions.CREATE_PROMO_RESULT:
      return {
        ...state,
        createPromoMessage: action.message
      }
    case actions.UPDATE_PROMO_RESULT:
      return {
        ...state,
        promoMessage: action.message
      }
    case actions.CREATE_COUPON_RESULT:
      return {
        ...state,
        couponMessage: action.message
      }
    case actions.UPDATE_COUPON_RESULT:
      return {
        ...state,
        couponMessage: action.message
      }
    case actions.PRODUCT_LIST:
      return {
        ...state,
        productLists: action.data
      }
    case actions.GET_COUPON_PACKAGE_LIST_SUCCESS:
    case actions.GET_COUPON_PACKAGE_LIST_FAILURE:
      return {
        ...state,
        packageLists: action.data,
        packageListsMessage: action.message
      }

    case actions.UPLOAD_COUPON_IMAGE_LIST:
      return {
        ...state,
        imageData: state.imageData.concat(action.data),
        status: action.status
      }
    default:
      return state
  }
}
