import React, { Component } from 'react'
import { Form, notification, Tooltip, Button } from 'antd'
import { connect } from 'react-redux'
import { Link } from 'react-router-dom'
import Input from '../../../components/uielements/input'
import ResetPasswordStyleWrapper from './resetPassword.style'
import userAction from '../../redux/user/actions'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import { clearToken } from '../../../helpers/utility'

const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions
const { resetPassword } = userAction

class ResetPassword extends Component {
  constructor (props) {
    super(props)
    this.state = {
      loading: false
    }
  }

  componentDidMount () {
    this.props.resetLoadingRedux(['RESET_PASSWORD'])
    this.props.resetErrorRedux(['RESET_PASSWORD'])
    clearToken()
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { resetPasswordLoading, resetPasswordError, resetPasswordStatus } = nextProps
    if (resetPasswordLoading === false) {
      notification[resetPasswordError ? 'error' : 'success']({ message: resetPasswordStatus })
      this.props.resetLoadingRedux(['RESET_PASSWORD'])
      this.props.resetErrorRedux(['RESET_PASSWORD'])
      if (!resetPasswordError) {
        this.signin()
      }
    }
  }

  onHandleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { password, confirm_password: confirmPassword } = values
        const { uuid } = this.props.match.params

        if (password !== confirmPassword) {
          notification.error({ message: 'Passwords do not match!' })
          return
        }
        this.props.resetPassword({ body: { password, uuid } })
      }
    })
  }

  signin = () => {
    const { history } = this.props
    history.push('/signin')
  }

  render () {
    const { resetPasswordLoading, form } = this.props
    const { getFieldDecorator } = form

    return (
      <ResetPasswordStyleWrapper className='isoResetPassPage'>
        <div className='isoFormContentWrapper'>
          <div className='isoFormContent'>
            <div className='isoLogoWrapper'>
              <Link to='/'>
                Operations Panel
              </Link>
            </div>
            <div>
              <div className='isoFormHeadText'>
                <h3>
                  Reset Password
                </h3>
                <p>
                  Enter new password and confirm it
                </p>
              </div>
              <Form onSubmit={(e) => this.onHandleSubmit(e)}>
                <Tooltip
                  placement='leftTop'
                  title={
                    <>
                      <div><b>Password Rules:</b></div>
                      <div>1. Password should be alphanumeric, containing at least an upper case character and a special symbol.</div>
                      <div>2. Password should not contain any sub-strings from the email/username of the user.</div>
                      <div>3. Last and new password should not be same.</div>
                    </>
                  }
                >
                  <Form.Item>
                    {getFieldDecorator('password', {
                      rules: [
                        { required: true, message: 'Password can not be empty.' },
                        { min: 8, message: 'Password should be minimum 8 characters.' },
                        { pattern: /(?=.*\d)(?=.*[a-z])(?=.*[A-Z])(?=.*\W)/, message: 'Password does not match minimum validation required.' }
                      ]
                    })(

                      <Input type='password' placeholder='New Password' />
                    )}
                  </Form.Item>
                </Tooltip>
                <Form.Item>
                  {getFieldDecorator('confirm_password', {
                    rules: [
                      { required: true, message: 'Password can not be empty' }
                    ]
                  })(
                    <Input type='password' placeholder='Confirm Password' />
                  )}
                </Form.Item>
                <Form.Item>
                  <Button
                    type='primary'
                    htmlType='submit'
                    loading={!!resetPasswordLoading}
                  >
                    Reset Password
                  </Button>
                </Form.Item>
              </Form>
              <div>
                <div className='password-heading'>Password Rules:</div>
                <ul>
                  <li>Password should be alphanumeric, containing at least an upper case character and a special symbol.</li>
                  <li>Password should not contain any sub-strings from the email/username of the user.</li>
                  <li>Last and new password should not be same.</li>
                </ul>
              </div>
            </div>
          </div>
        </div>
      </ResetPasswordStyleWrapper>
    )
  }
}

const WrappedForm = Form.create()(ResetPassword)

export default connect(
  state => ({
    resetPasswordLoading: state.Loading.RESET_PASSWORD,
    resetPasswordError: state.Error.RESET_PASSWORD,
    resetPasswordStatus: state.User.resetPasswordStatus
  }),
  {
    resetPassword,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedForm)
