export function * getClaimLists () {
  yield takeEvery(actions.GET_CLAIM_LISTS_REQUEST, function * (payload) {
    try {
      const res = yield call(callApi.getClaimLists, payload)
      if (res.status === 200) {
        yield put({
          type: actions.GET_CLAIM_LISTS_SUCCESS,
          data: res.data,
          getClaimListsStatus: 'success'
        })
      } else {
        const message = exceptionHandlerSanitizer(res?.data)
        yield put({
          type: actions.GET_CLAIM_LISTS_FAILURE,
          data: [],
          getClaimListsMessage: message,
          getClaimListsStatus: get(
            res.data,
            'error',
            'Ooops, something went terribly wrong!'
          )
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_CLAIM_LISTS_FAILURE,
        data: [],
        getClaimListsMessage: 'Ooops, something went wrong',
        getClaimListsStatus: statusCodes.SERVER_ERROR
      })
    }
  })
}

