export function * getDetailsClaim () {
  yield takeEvery(actions.GET_DETAILS_CLAIM_REQUEST, function * (payload) {
    try {
      const res = yield call(callApi.getDetailsClaim, payload)
      if (res.status === 200) {
        yield put({
          type: actions.GET_DETAILS_CLAIM_SUCCESS,
          detailData: res.data,
          getDetailsClaimStatus: 'success'
        })
        const claimDetails = res.data
        if (claimDetails?.internal_id) {
          yield put({
            type: insuranceActions.GET_DETAIL_INSURANCE_DATA,
            payload: claimDetails?.internal_id
          })
        }
        let forms = []
        if (Object.values(claimDetails).length > 0) {
          forms = claimDetails.forms
          const paymentForms = _.get(claimDetails, 'payment_forms')
          if (forms && forms.length > 0) {
            const checkFormInvalid =
              _collection.find(forms, { is_valid: false }) ||
              !_collection.find(paymentForms, { is_valid: true })

            if (checkFormInvalid) {
              return
            }
            if (
              claimDetails.status.status_code === 'initiated' ||
              claimDetails.status.status_code === 'reprocess'
            ) {
              yield put({
                type: actions.FINAL_SUBMIT,
                payload: { claim_id: claimDetails.claim_id }
              })
            }
          }
        }
      } else {
        yield put({
          type: actions.GET_DETAILS_CLAIM_FAILURE,
          detailData: res.data,
          getDetailsClaimStatus: 'Ooops, something went terribly wrong!'
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_DETAILS_CLAIM_FAILURE,
        detailData: {},
        getDetailsClaimStatus: 'Ooops, something went terribly wrong!'
      })
    }
  })
}

