export function * uploadGenericDocRequest () {
  yield takeEvery(actions.UPLOAD_GENERIC_CLAIM_DOC, function * ({ payload }) {
    try {
      const { filename } = payload.signedUrlData
      const requestPayload = {}
      _.set(requestPayload, 'body', { file_name: filename })
      const res = yield call(authPost, {
        ...requestPayload,
        url: fileUrl.makeURLPublic
      })

      if (res.status === 200) {
        const { form, signedUrlData = {}, attribute } = payload
        const { url: fileUrl } = signedUrlData
        const responseData = {}
        _.set(responseData, [form], { [attribute]: fileUrl })

        yield put({
          type: actions.SAVE_GENERIC_ATTRIBUTES_DOC,
          data: responseData,
          saveAttributesGenericDocStatus: 'success'
        })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({
          type: actions.SAVE_GENERIC_ATTRIBUTES_DOC,
          saveAttributesGenericDocStatus: message
        })
      }
    } catch (e) {
      yield put({
        type: actions.SAVE_GENERIC_ATTRIBUTES_DOC,
        saveAttributesGenericDocStatus: 'file not uploaded, try again'
      })
    }
  })
}

