export function * generateSignedUrlAndUpload () {
  yield takeEvery(
    actions.GENERATE_SIGNED_URL_AND_UPLOAD_REQUEST,
    function * ({ payload }) {
      try {
        const res = yield call(callApi.generateSignedURL, payload)
        if (res.status === 200) {
          const responseData = yield res.data
          yield put({
            type: actions.UPLOAD_FILE_BY_SIGNED_URL_REQUEST,
            payload: {
              apiData: payload,
              signedUrlData: responseData
            }
          })
          yield put({
            type: actions.GENERATE_SIGNED_URL_AND_UPLOAD_SUCCESS
          })
          return
        }
      } catch (e) {
        // fall through to failure
      }
      yield put({
        type: actions.UPLOAD_COMMON_CLAIM_FILE_FAILURE,
        data: {},
        message: 'Gagal unggah file'
      })
      yield put({
        type: actions.GENERATE_SIGNED_URL_AND_UPLOAD_FAILURE,
        attribute: payload.attribute,
        form: payload.form
      })
    }
  )
}

export function * uploadFileUsingSignedUrl () {
  yield takeEvery(
    actions.UPLOAD_FILE_BY_SIGNED_URL_REQUEST,
    function * ({ payload }) {
      const { apiData, signedUrlData } = payload
      const { attribute, form, ismultiValue } = apiData
      const body = {
        file: apiData.file,
        signedUrlData: signedUrlData
      }
      try {
        const res = yield call(callApi.fileUploadUsingSignedUrl, body)
        if ([200, 201].includes(res.status)) {
          const responseData = {}
          _.set(responseData, [form], {
            [attribute]: signedUrlData.get_signed_url
          })
          const filename = {
            identifier: attribute,
            value: ismultiValue
              ? [signedUrlData.filename]
              : signedUrlData.filename
          }
          yield put({
            type: actions.SAVE_GENERIC_ATTRIBUTES_DOC,
            data: responseData,
            filename,
            saveAttributesGenericDocStatus: 'success'
          })
          yield put({
            type: actions.UPLOAD_FILE_BY_SIGNED_URL_SUCCESS
          })
          return
        }
      } catch (e) {
        // fall through to failure
      }
      yield put({
        type: actions.UPLOAD_COMMON_CLAIM_FILE_FAILURE,
        data: {},
        message: 'Gagal unggah file'
      })
      yield put({
        type: actions.UPLOAD_FILE_BY_SIGNED_URL_FAILURE,
        attribute: apiData.attribute,
        form: apiData.form
      })
    }
  )
}

