import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Layout, Input, Select } from 'antd'
import appActions from '../../redux/app/actions'
import TopbarUser from './topbarUser'
import TopbarWrapper from './topbar.style'
import themes from '../../settings/themes'
import { themeConfig } from '../../settings'
import PermissionChecker from '../../components/permissionChecker'
import { getUser } from '../../helpers/utility'
import EnvBadge from '../EnvBadge'

const { Header } = Layout
const { toggleCollapsed } = appActions
const customizedTheme = themes[themeConfig.theme]
const Search = Input.Search
const Option = Select.Option

const optionArray = [
  { text: 'Name', value: 'name' },
  { text: 'Email', value: 'email' },
  { text: 'Phone Number', value: 'mobileNo' },
  { text: 'Policy Number', value: 'insurancePolicyNo' },
  { text: 'Application Number', value: 'applicationNo' },
  { text: 'Claim Number', value: 'claim_number' },
  { text: 'Order Id', value: 'order_id' }
]

class Topbar extends Component {
  constructor (props) {
    super(props)
    this.state = {
      searchSelect: 'name'
    }
    this.initState = this.state
  }

  handleChange = (value) => {
    this.setState({
      searchSelect: value
    })
  }

  handleSubmitSearch = (value) => {
    const { history } = this.props
    const { searchSelect } = this.state
    history.push({
      pathname: '/customer',
      search: '?message=' + value + '&select=' + searchSelect
    })
  }

  render () {
    const {
      toggleCollapsed,
      collapsed,
      openDrawer,
      permissions,
      location,
      env
    } = this.props
    const collapsedHeader = collapsed && !openDrawer
    const styling = {
      background: customizedTheme.backgroundColor,
      position: 'fixed',
      width: '100%',
      height: 70
    }

    return (
      <TopbarWrapper>
        <Header
          style={styling}
          className={
            collapsedHeader ? 'isomorphicTopbar collapsed' : 'isomorphicTopbar'
          }
        >
          <div className='isoLeft'>
            <button
              className={
                collapsedHeader
                  ? 'triggerBtn menuCollapsed'
                  : 'triggerBtn menuOpen'
              }
              style={{ color: customizedTheme.textColor }}
              onClick={toggleCollapsed}
            />
            {location.pathname !== '/customer' && (
              <PermissionChecker
                permissionSetter='ops.claim_top_search_view'
                permissionGetter={permissions}
              >
                <Select
                  defaultValue='name'
                  style={{ width: 120, marginRight: 20 }}
                  onChange={this.handleChange}
                >
                  {optionArray.map((option, index) => (
                    <Option key={index} value={option.value}>
                      {option.text}
                    </Option>
                  ))}
                </Select>
                <Search
                  placeholder='Input search text'
                  onSearch={this.handleSubmitSearch}
                  style={{ width: 300 }}
                />
              </PermissionChecker>
            )}
          </div>

          <div className='isoRight'>
            <EnvBadge env={env} />
            <ul className='user-profile'>
              <li
                onClick={() => this.setState({ selectedItem: 'user' })}
                className='isoUser'
              >
                <TopbarUser user={getUser() || {}} {...this.props} />
              </li>
            </ul>
          </div>
        </Header>
      </TopbarWrapper>
    )
  }
}

export default connect(
  state => ({
    ...state.App,
    isCustomerService: state.Auth.isCustomerService,
    isSuperUser: state.Auth.isSuperUser
  }),
  { toggleCollapsed }
)(Topbar)
