import actions from './actions'

const initState = {
  idToken: null,
  profile: {},
  loginMessage: '',
  loginData: {},
  verifyOtpStatus: ''
}

export default function authReducer (state = initState, action) {
  switch (action.type) {
    case actions.RESET_STATE_AUTH:
      return {
        ...state,
        loginMessage: '',
        loginData: {}
      }
    case actions.CHECK_AUTHORIZATION_SUCCESS:
      return {
        ...state,
        idToken: action.token,
        retriesLeft: action.retriesLeft,
        loginMessage: action.loginMessage
      }
    case actions.LOGIN_FAILURE:
      return {
        ...state,
        retriesLeft: action.retriesLeft,
        loginMessage: action.loginMessage,
        loginData: action.loginData
      }
    case actions.GET_PROFILE_DETAIL_SUCCESS:
    case actions.GET_PROFILE_DETAIL_FAILURE:
      return {
        ...state,
        ...action.data
      }
    case actions.LOGIN_SUCCESS:
      return {
        ...state,
        loginData: action.data
      }
    case actions.RESEND_OTP_SUCCESS:
    case actions.RESEND_OTP_FAILURE:
      return {
        ...state,
        resendOtpData: action.data
      }
    case actions.VERIFY_OTP_FAILURE:
      return {
        ...state,
        verifyOtpStatus: action.data
      }
    case actions.LOGOUT:
      return initState
    default:
      return state
  }
}
