import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function* createJDPolicyRequest() {
  yield takeEvery('CREATE_JD_POLICY', function* (payload) {
    try {
      let res = yield call(callApi.postCreateJD, payload)
      if (res.status === 201 || res.status === 200) {
        yield put({ type: actions.CREATE_JD_SUCCESS, getCreateJDStatus: 'success' })
      } else {
        yield put({ type: actions.CREATE_JD_FAILED, getCreateJDStatus: 'Ooops, failed to register your request!' })
      }
    } catch (e) {
      yield put({ type: actions.CREATE_JD_FAILED, getCreateJDStatus: 'Ooops, failed to register your request!' })
    }
  })
}

export function* createOAGPolicyRequest() {
  yield takeEvery('CREATE_OAG_NOTIF', function* (payload) {
    try {
      let res = yield call(callApi.postCreateOAG, payload)
      if (res.status === 201 || res.status === 200) {
        yield put({ type: actions.CREATE_OAG_NOTIF_SUCCESS, getCreateOAGStatus: 'success' })
      } else {
        yield put({ type: actions.CREATE_OAG_NOTIF_FAILED, getCreateOAGStatus: 'Ooops, failed to register your request!' })
      }
    } catch (e) {
      yield put({ type: actions.CREATE_OAG_NOTIF_FAILED, getCreateOAGStatus: 'Ooops, failed to register your request!' })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(createJDPolicyRequest),
    fork(createOAGPolicyRequest)
  ])
}
