import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'
import errorMessageHandler from '../../../middleware/error_message'

export function * postSearch () {
  yield takeEvery(actions.SEARCH_CUSTOMER_REQUEST, function * (payload) {
    try {
      let res = yield call(callApi.searchCustomer, payload)
      if (res.status === 201 || res.status === 200) {
        yield put({
          type: actions.SEARCH_CUSTOMER_SUCCESS,
          searchResult: res.data,
          searchResultMeta: res.data.meta,
          searchMessage: 'Success'
        })
      } else {
        yield put({
          type: actions.SEARCH_CUSTOMER_FAILURE,
          searchResult: [],
          searchResultMeta: {},
          searchMessage: res.data.message
        })
      }
    } catch (e) {
      yield put({
        type: actions.SEARCH_CUSTOMER_FAILURE,
        searchResult: [],
        searchResultMeta: {},
        searchMessage: e.message
      })
    }
  })
}

export function * getCustomer () {
  yield takeEvery(actions.GET_CUSTOMER_REQUEST, function * (payload) {
    try {
      let res = yield call(callApi.getCustomer, payload)
      if (res.status === 200) {
        yield put({
          type: actions.GET_CUSTOMER_SUCCESS,
          customerData: res.data,
          getCustomerMessage: 'Success'
        })
      } else {
        yield put({
          type: actions.GET_CUSTOMER_FAILURE,
          customerData: {},
          getCustomerMessage: res.data.message
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_CUSTOMER_FAILURE,
        customerData: {},
        getCustomerMessage: e.message
      })
    }
  })
}

