export function * patchEditCustomer () {
  yield takeEvery(actions.PATCH_EDIT_CUSTOMER_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.patchEditCustomer, payload)
      if (res.status === 200) {
        yield put({
          type: actions.GET_CUSTOMER_REQUEST,
          payload: payload.userid
        })
        yield put({
          type: actions.PATCH_EDIT_CUSTOMER_SUCCESS,
          editCustomerMessage: 'Successfully edited'
        })
      } else {
        yield put({
          type: actions.PATCH_EDIT_CUSTOMER_FAILURE,
          editCustomerMessage: errorMessageHandler(res.data)
        })
      }
    } catch (e) {
      yield put({
        type: actions.PATCH_EDIT_CUSTOMER_FAILURE,
        editCustomerMessage: e.message
      })
    }
  })
}

