export default function * rootSaga () {
  yield all([
    fork(postSearch),
    fork(getCustomer),
    fork(getPolicyByCustomer),
    fork(getClaimByCustomer),
    fork(patchEditCustomer),
    fork(putEditContact)
  ])
}
