import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import { get } from 'lodash'

import actions from './action'
import ILUrl from '../../../request/urls/il'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'

export function * getEventType () {
  yield takeEvery(actions.GET_EVENT_TYPE_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, { ...payload, url: ILUrl.getEventType })
      if (res.status === 200) {
        yield put({
          type: actions.GET_EVENT_TYPE_SUCCESS,
          data: res.data
        })
      } else {
        yield put({
          type: actions.GET_EVENT_TYPE_FAILURE,
          data: []
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_EVENT_TYPE_FAILURE,
        data: []
      })
    }
  })
}

