export function * createWebhook () {
  yield takeEvery(actions.CREATE_WEBHOOK_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPost, { ...payload, url: ILUrl.createWebhook })
      if (res.status === 200) {
        yield put({
          type: actions.CREATE_WEBHOOK_SUCCESS,
          message: get(res.data, 'message', 'Webhook created successfully!')
        })
      } else {
        yield put({
          type: actions.CREATE_WEBHOOK_FAILURE,
          message: get(res.data, 'error', 'Something went wrong!')
        })
      }
    } catch (e) {
      yield put({
        type: actions.CREATE_WEBHOOK_FAILURE,
        message: get(e.data, 'error', 'Something went wrong!')
      })
    }
  })
}

