import { mapArrayElementsKeysToObjectKeys } from '../../../helpers/utility'
import actions from './actions'

const INITIAL_STATE = {}

const teleSalesReducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case actions.RESET_TELESALES_TEAM: {
      const stateToBeReset = mapArrayElementsKeysToObjectKeys(payload)
      return { ...state, ...stateToBeReset }
    }
    case actions.PROVINCE_LIST:
      return { ...state, ...payload }
    case actions.CITY_LIST:
      return { ...state, ...payload }
    case actions.BIRTH_PLACE:
      return { ...state, ...payload }
    case actions.BUKALAPAK_QUOTE:
      return { ...state, ...payload }
    default:
      return state
  }
}
export { INITIAL_STATE }
export default teleSalesReducer
