const actions = {
  RESET_REPORTING_CONFIG: 'RESET_REPORTING_CONFIG',

  GET_REPORTING_LIST_REQUEST: 'GET_REPORTING_LIST_REQUEST',
  GET_REPORTING_LIST_SUCCESS: 'GET_REPORTING_LIST_SUCCESS',
  GET_REPORTING_LIST_FAILURE: 'GET_REPORTING_LIST_FAILURE',

  GET_REPORTING_CONFIG_DETAILS_REQUEST: 'GET_REPORTING_CONFIG_DETAILS_REQUEST',
  GET_REPORTING_CONFIG_DETAILS_SUCCESS: 'GET_REPORTING_CONFIG_DETAILS_SUCCESS',
  GET_REPORTING_CONFIG_DETAILS_FAILURE: 'GET_REPORTING_CONFIG_DETAILS_FAILURE',

  CREATE_REPORTING_CONFIG_DETAILS_REQUEST:
    'CREATE_REPORTING_CONFIG_DETAILS_REQUEST',
  CREATE_REPORTING_CONFIG_DETAILS_SUCCESS:
    'CREATE_REPORTING_CONFIG_DETAILS_SUCCESS',
  CREATE_REPORTING_CONFIG_DETAILS_FAILURE:
    'CREATE_REPORTING_CONFIG_DETAILS_FAILURE',

  GET_REPORTING_CONFIG_STATUS_REQUEST: 'GET_REPORTING_CONFIG_STATUS_REQUEST',
  GET_REPORTING_CONFIG_STATUS_SUCCESS: 'GET_REPORTING_CONFIG_STATUS_SUCCESS',
  GET_REPORTING_CONFIG_STATUS_FAILURE: 'GET_REPORTING_CONFIG_STATUS_FAILURE',

  UPDATE_REPORTING_CONFIG_DETAILS_REQUEST:
    'UPDATE_REPORTING_CONFIG_DETAILS_REQUEST',
  UPDATE_REPORTING_CONFIG_DETAILS_SUCCESS:
    'UPDATE_REPORTING_CONFIG_DETAILS_SUCCESS',
  UPDATE_REPORTING_CONFIG_DETAILS_FAILURE:
    'UPDATE_REPORTING_CONFIG_DETAILS_FAILURE',

  GET_REPORT_LOG_REQUEST: 'GET_REPORT_LOG_REQUEST',
  GET_REPORT_LOG_SUCCESS: 'GET_REPORT_LOG_SUCCESS',
  GET_REPORT_LOG_FAILURE: 'GET_REPORT_LOG_FAILURE',

  UPDATE_REPORT_LOG_REQUEST: 'UPDATE_REPORT_LOG_REQUEST',
  UPDATE_REPORT_LOG_SUCCESS: 'UPDATE_REPORT_LOG_SUCCESS',
  UPDATE_REPORT_LOG_FAILURE: 'UPDATE_REPORT_LOG_FAILURE',

  GET_UPDATE_LOG_REQUEST: 'GET_UPDATE_LOG_REQUEST',
  GET_UPDATE_LOG_SUCCESS: 'GET_UPDATE_LOG_SUCCESS',
  GET_UPDATE_LOG_FAILURE: 'GET_UPDATE_LOG_FAILURE',

  resetReportingConfigRedux: (payload) => ({
    type: actions.RESET_REPORTING_CONFIG,
    payload
  }),
  getReportingList: (query = {}) => ({
    type: actions.GET_REPORTING_LIST_REQUEST,
    payload: { query }
  }),
  getReportingConfigDetails: (query = {}) => ({
    type: actions.GET_REPORTING_CONFIG_DETAILS_REQUEST,
    payload: { query }
  }),
  changeReportingConfigStatus: (query = {}) => ({
    type: actions.GET_REPORTING_CONFIG_STATUS_REQUEST,
    payload: { query }
  }),
  createReportingConfig: (query = {}) => ({
    type: actions.CREATE_REPORTING_CONFIG_DETAILS_REQUEST,
    payload: { query }
  }),
  updateReportingConfig: (query = {}) => ({
    type: actions.UPDATE_REPORTING_CONFIG_DETAILS_REQUEST,
    payload: { query }
  }),
  getReportLogs: (payload) => ({
    type: actions.GET_REPORT_LOG_REQUEST,
    payload
  }),
  updateReportLogs: (payload) => ({
    type: actions.UPDATE_REPORT_LOG_REQUEST,
    payload
  }),
  getUpdateLogs: (payload) => ({
    type: actions.GET_UPDATE_LOG_REQUEST,
    payload
  })
}
export default actions
