import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import { saveAs } from 'file-saver'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function * getTranslationsRequest () {
  yield takeEvery(actions.GET_TRANSLATIONS_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.getTranslations, payload)
      if (res.status === 200) {
        const language = ((((payload || {}).payload || {}).params || {}).source) || 'translations'
        yield saveAs(res.data, `${language}.xlsx`)
        yield put({ type: actions.GET_TRANSLATIONS_SUCCESS, message: res.data.message || 'success' })
      } else {
        yield put({ type: actions.GET_TRANSLATIONS_FAILURE, message: res.data.message || 'failure' })
      }
    } catch (e) {
      yield put({ type: actions.GET_TRANSLATIONS_FAILURE, message: 'failure' })
    }
  })
}

export function * getPostTranslationsRequest () {
  yield takeEvery(actions.POST_TRANSLATIONS_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.postTranslations, payload)
      if (res.status === 200) {
        yield put({ type: actions.POST_TRANSLATIONS_SUCCESS, message: res.data.message || 'success' })
      } else {
        yield put({ type: actions.POST_TRANSLATIONS_FAILURE, message: res.data.message || 'failure' })
      }
    } catch (e) {
      yield put({ type: actions.POST_TRANSLATIONS_FAILURE, message: 'failure' })
    }
  })
}

export function * getPostTranslationsEntryRequest () {
  yield takeEvery(actions.POST_TRANSLATIONS_ENTRY_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.postTranslationsEntry, payload)
      if (res.status === 200) {
        yield put({ type: actions.POST_TRANSLATIONS_ENTRY_SUCCESS, message: res.data.message || 'success' })
      } else {
        yield put({ type: actions.POST_TRANSLATIONS_ENTRY_FAILURE, message: res.data.message || 'failure' })
      }
    } catch (e) {
      yield put({ type: actions.POST_TRANSLATIONS_ENTRY_FAILURE, message: 'failure' })
    }
  })
}

export default function * rootSaga () {
  yield all([
    fork(getTranslationsRequest),
    fork(getPostTranslationsRequest),
    fork(getPostTranslationsEntryRequest)
  ])
}
