import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import _, { get } from 'lodash'
import actions from './actions'
import callApi from '../../../helpers/callApi'
import exceptionHandlerSanitizer from '../../../middleware/exceptions'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import noAuthpost from '../../../request/methods/post'
import userUrls from '../../../request/urls/user'
import parseResponseError from '../../../helpers/parseResponseError'
import authActions from '../../../redux/auth/actions'

export function* getForgotPasswordRequest() {
  yield takeEvery('FORGOT_PASSWORD', function* (payload) {
    try {
      const res = yield call(callApi.forgotPassword, payload)
      if (res.status === 200) {
        yield put({ type: actions.FORGOT_PASSWORD_STATUS, data: res.data })
      }
    } catch (e) {
      yield put({ type: actions.FORGOT_PASSWORD_STATUS, data: 'Error' })
    }
  })
}

export function* resetPasswordRequest() {
  yield takeEvery(actions.RESET_PASSWORD_REQUEST, function* ({ payload }) {
    try {
      const res = yield call(noAuthpost, { ...payload, url: userUrls.resetPassword })
      if (res.status === 200) {
        yield put({
          type: actions.RESET_PASSWORD_SUCCESS,
          message: _.get(res.data, 'message', 'Success')
        })
      } else {
        yield put({
          type: actions.RESET_PASSWORD_FAILURE,
          message: _.get(res.data, 'error', 'Error')
        })
      }
    } catch (e) {
      yield put({
        type: actions.RESET_PASSWORD_FAILURE,
        message: get(e.data, 'password') ? parseResponseError(e.data, 'Password not valid') : _.get(e.data, 'error', 'Error')
      })
    }
  })
}

export function* getInternalUsersRequest() {
  yield takeEvery(actions.GET_INTERNAL_USERS_REQUEST, function* () {
    try {
      const res = yield call(authGet, { url: userUrls.getInternalUsers })
      if (res.status === 200) {
        const internalUsers = res.data
        yield put({ type: actions.GET_INTERNAL_USERS_SUCCESS, internalUsers })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({ type: actions.GET_INTERNAL_USERS_FAILURE, internalUsers: [], message })
      }
    } catch (e) {
      yield put({ type: actions.GET_INTERNAL_USERS_FAILURE, message: 'Error while getting internal users list' })
    }
  })
}

