export default function* rootSaga() {
  yield all([
    fork(getForgotPasswordRequest),
    fork(resetPasswordRequest),
    fork(getInternalUsersRequest),
    fork(sendSMSOTP),
    fork(verifyAndAddPhone),
    fork(resendUserOTP),
    fork(getTOTPSharedSecret),
    fork(verifyTOTP),
    fork(update2FAMethod),
    fork(verifyUserOTP)
  ])
}
