const getPolicyListDashboard = async ({ payload }) => {
  const {
    startDate,
    endDate,
    productKey,
    partner,
    excludeProductKeys,
    excludePartnerKeys,
    dashboardView
  } = payload
  let subUrl = `?createdat_start=${startDate}&createdat_end=${endDate}`
  if (excludeProductKeys) {
    subUrl = subUrl.concat(`&exclude_product_keys=${excludeProductKeys}`)
  }
  if (productKey) {
    subUrl = subUrl.concat(`&product_key=${productKey}`)
  }
  if (partner) {
    subUrl = subUrl.concat(`&partner=${partner}`)
  }
  if (excludePartnerKeys) {
    subUrl = subUrl.concat(`&exclude_partner_codes=${excludePartnerKeys}`)
  }
  if (dashboardView) {
    subUrl = subUrl.concat(`&dashboard_view=${dashboardView}`)
  }
  try {
    const response = await axios.get(
      `${configUrl.getPolicyListDashboard}${subUrl}`,
      { headers: getHeader() }
    )
    return response
  } catch (error) {
    return error.response
  }
}

