const sendReportPolicy = async ({ payload }) => {
  try {
    const {
      email,
      purpose,
      product_key: productKey,
      filter,
      txn_start_date: txnStartDate,
      txn_end_date: txnEndDate,
      policyState
    } = payload
    const uri = configUrl.sendReportPolicy
    let url = `${uri}?er=1&timezone=Asia/Jakarta`

    for (const key in filter) {
      url += `&${key}=${filter[key]}`
    }
    const response = await axios.post(
      url,
      {
        email,
        product_key: productKey,
        purpose,
        txn_start_date: txnStartDate,
        txn_end_date: txnEndDate,
        policyState
      },
      { headers: getHeader() }
    )
    return response
  } catch (error) {
    return error.response
  }
}

