const getListQuestion = async (payload) => {
  const { payload: p } = payload
  const queryString =
    '?' +
    Object.entries(p)
      .map(
        ([key, value]) =>
          `${encodeURIComponent(key)}=${encodeURIComponent(value)}`
      )
      .join('&')
  try {
    const response = await axios.get(configUrl.getListQuestion + queryString, {
      headers: getHeader()
    })
    return response
  } catch (error) {
    return error.message
  }
}

