import actions from './actions'

const initialState = {
  partnerListStatus: '',
  partnerListData: [],
  partnerDetailStatus: '',
  partnerDetailData: {},
  // data: [],
  // status: '',
  products: [],
  revokeMessage: '',
  reinstateMessage: '',
  removeStatus: '',
  messageAttachProduct: '',
  messageAddNewUser: '',
  removePartnerProductStatus: '',
  statusAddNewPartner: '',
  dataAddPartner: [],
  statusConfig: '',
  partnerConfig: [],
  statusAddNewPartnerConfig: '',
  statusEditNewPartner: '',
  partnerImage: '',
  partnerImageStatus: '',
  timezones: [],
  domainConfig: [],
  domainConfigMessage: '',
  defaultDomainConfig: [],
  defaultDomainConfigMessage: '',
  partnerDomainConfig: [],
  partnerDomainConfigMessage: '',

  addpartnerDomainConfig: [],
  addpartnerDomainConfigMessage: '',

  updatepartnerDomainConfig: [],
  updatepartnerDomainConfigMessage: '',

  updatewhitelabelurlMessage: '',

  getPartnerProductTemplateData: [],
  getPartnerProductTemplateMessage: '',

  addNotificationTemplateProductMessage: '',
  addNotificationTemplatePartnerMessage: '',
  enableDisbaleProductMessage: '',
  genrateApiSpecData: {},
  generateApiSpecDataMessage: '',
  partnerConfigStatus: '',

  partnerClientList: [],
  allPartnerClientList: [],
  partnerClientStatus: '',
  partnerClientMessage: '',
  attachClientMessage: '',
  detachClientMessage: ''
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_PARTNER_DATA: {
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state,
          ...initialState
        }
      }
    }
    case actions.RESET_REDUX_STATE:
      return {
        ...state,
        ...initialState
      }
    case actions.GET_PARTNER_LIST_SUCCESS:
    case actions.GET_PARTNER_LIST_FAILURE:
      return {
        ...state,
        partnerListStatus: action.getDataStatus,
        partnerListData: action.data
      }
    case actions.GET_PARTNER_DETAILS_SUCCESS:
    case actions.GET_PARTNER_DETAILS_FAILURE:
      return {
        ...state,
        partnerDetailStatus: action.getDataStatus,
        partnerDetailData: action.data
      }
    case actions.REMOVE_PARTNER_PRODUCT_SUCCESS:
    case actions.REMOVE_PARTNER_PRODUCT_FAILURE:
      return {
        ...state,
        removePartnerProductStatus: action.removePartnerProductStatus
      }
    case actions.PRODUCT_LIST:
      return {
        ...state,
        status: action.getDataStatus,
        products: action.products
      }
    case actions.FAILED_ATTACH_PRODUCT:
    case actions.SUCCESS_ATTACH_PRODUCT:
      return {
        ...state,
        messageAttachProduct: action.messageAttachProduct
      }
    case actions.SUCCESS_POST_NEW_USER:
      return {
        ...state,
        messageAddNewUser: action.messageAddNewUser
      }
    case actions.FAILED_POST_NEW_USER:
      return {
        ...state,
        messageAddNewUser: action.messageAddNewUser
      }
    case actions.SUCCESS_REVOKE_USER:
      return {
        ...state,
        revokeMessage: action.revokeMessage
      }
    case actions.FAILED_REVOKE_USER:
      return {
        ...state,
        revokeMessage: action.revokeMessage
      }
    case actions.SUCCESS_REINSTATE_USER:
      return {
        ...state,
        reinstateMessage: action.reinstateMessage
      }
    case actions.FAILED_REINSTATE_USER:
      return {
        ...state,
        reinstateMessage: action.reinstateMessage
      }
    case actions.SUCCESS_ADD_PARTNER:
      return {
        ...state,
        dataAddPartner: action.dataAddPartner,
        statusAddNewPartner: action.statusAddNewPartner
      }
    case actions.FAILED_ADD_PARTNER:
      return {
        ...state,
        statusAddNewPartner: action.statusAddNewPartner
      }
    case actions.GET_PARTNER_CONFIG_FAILURE:
    case actions.GET_PARTNER_CONFIG_SUCCESS:
      return {
        ...state,
        partnerConfigStatus: action.message,
        partnerConfig: action.data
      }
    case actions.DEFAULT_CONFIG:
      return {
        ...state,
        statusConfig: action.getDataStatus,
        defaultConfig: action.data
      }
    case actions.ADD_PARTNER_CONFIG_STATUS:
      return {
        ...state,
        statusAddNewPartnerConfig: action.statusAddNewPartnerConfig
      }
    case actions.EDIT_PARTNER_CONFIG_STATUS:
      return {
        ...state,
        statusEditNewPartner: action.statusEditNewPartner
      }
    case actions.POST_PARTNER_IMAGE_SUCCESS:
    case actions.POST_PARTNER_IMAGE_FAILURE:
      return {
        ...state,
        partnerImage: action.data,
        partnerImageStatus: action.message
      }
    case actions.GET_TIMEZONE_DATA_SUCCESS:
    case actions.GET_TIMEZONE_DATA_FAILED:
      return {
        ...state,
        timezones: [...action.data]
      }
    case actions.GET_WHITELABLE_DATA_SUCCESS:
    case actions.GET_WHITELABLE_DATA_FAILURE:
      return {
        ...state,
        partnerDomainConfig: [...action.data],
        partnerDomainConfigMessage: action.message
      }
    case actions.GET_DOMAIN_CONFIG_SUCCESS:
    case actions.GET_DOMAIN_CONFIG_FAILURE:
      return {
        ...state,
        domainConfig: [...action.data],
        domainConfigMessage: action.message
      }
    case actions.ADD_WHITELABLE_CONFIG_SUCCESS:
    case actions.ADD_WHITELABLE_CONFIG_FAILURE:
      return {
        ...state,
        addpartnerDomainConfigMessage: action.message
      }
    case actions.UPDATE_DOMAIN_CONFIG_SUCCESS:
    case actions.UPDATE_DOMAIN_CONFIG_FAILURE:
      return {
        ...state,
        updatepartnerDomainConfigMessage: action.message
      }
    case actions.UPDATE_BASE_URL_DATA_SUCCESS:
    case actions.UPDATE_BASE_URL_DATA_FAILURE:
      return {
        ...state,
        updatewhitelabelurlMessage: action.message
      }
    case actions.GET_WHITELABLE_DEFAULT_CONFIG_SUCCESS:
    case actions.GET_WHITELABLE_DEFAULT_CONFIG_FAILURE:
      return {
        ...state,
        defaultDomainConfig: action.data,
        defaultDomainConfigMessage: action.message
      }
    case actions.UPDATE_USER_SUCCESS:
    case actions.UPDATE_USER_FAILURE:
      return {
        ...state,
        updateUserMessage: action.message
      }
    case actions.GET_TEMPLATE_PARTNERPRODUCT_DATA_SUCCESS:
    case actions.GET_TEMPLATE_PARTNERPRODUCT_DATA_FAILURE:
      return {
        ...state,
        getPartnerProductTemplateData: action.data,
        getPartnerProductTemplateMessage: action.message
      }
    case actions.ADD_NOTIFICATION_TEMPLATE_PRODUCT_SUCCESS:
    case actions.ADD_NOTIFICATION_TEMPLATE_PRODUCT_FAILURE:
      return {
        ...state,
        addNotificationTemplateProductMessage: action.message
      }
    case actions.ADD_NOTIFICATION_TEMPLATE_PARTNER_SUCCESS:
    case actions.ADD_NOTIFICATION_TEMPLATE_PARTNER_FAILURE:
      return {
        ...state,
        addNotificationTemplatePartnerMessage: action.message
      }
    case actions.ADD_ENABLE_DISABLE_PACKAGE_SUCCESS:
    case actions.ADD_ENABLE_DISABLE_PACKAGE_FAILURE:
      return {
        ...state,
        enableDisbaleProductMessage: action.message
      }
    case actions.GENERATE_API_SPEC_SUCCESS:
    case actions.GENERATE_API_SPEC_FAILURE:
      return {
        ...state,
        generateApiSpecData: action.data,
        genrateApiSpecStatus: action.status,
        generateApiSpecDataMessage: action.message
      }
    case actions.GET_PARTNER_CLIENT_LIST_SUCCESS:
    case actions.GET_PARTNER_CLIENT_LIST_FAILURE:
      return {
        ...state,
        partnerClientList: action.data,
        partnerClientStatus: action.status,
        partnerClientMessage: action.message
      }
    case actions.GET_ALL_PARTNER_CLIENT_LIST_SUCCESS:
    case actions.GET_ALL_PARTNER_CLIENT_LIST_FAILURE:
      return {
        ...state,
        allPartnerClientList: action.data
      }
    case actions.ATTACT_PARTNER_CLIENT_SUCCESS:
    case actions.ATTACT_PARTNER_CLIENT_FAILURE:
      return {
        ...state,
        attachClientMessage: action.message
      }
    case actions.DETACH_PARTNER_CLIENT_SUCCESS:
    case actions.DETACH_PARTNER_CLIENT_FAILURE:
      return {
        ...state,
        detachClientMessage: action.message
      }
    default:
      return state
  }
}
