import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'
import exceptionHandlerSanitizer from '../../../middleware/exceptions'
import errorMessageHandler from '../../../middleware/error_message'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import providerUrls from '../../../request/urls/provider'
import get from 'lodash/get'

export function* getProviderUserData() {
  yield takeEvery(actions.GET_PROVIDER_USER_DATA_REQUEST, function* () {
    try {
      const res = yield call(callApi.getProviderUserList)
      if (res.status === 200) {
        yield put({ type: actions.GET_PROVIDER_USER_DATA_SUCCESS, providerUserList: res.data, providerMessage: 'Success' })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({ type: actions.GET_PROVIDER_USER_DATA_FAILURE, providerUserList: [], providerMessage: message })
      }
    } catch (e) {
      yield put({ type: actions.GET_PROVIDER_USER_DATA_FAILURE, providerUserList: [], providerMessage: 'Error' })
    }
  })
}

