export function* postProviderUser() {
  yield takeEvery(actions.POST_PROVIDER_USER_REQUEST, function* (payload) {
    try {
      const res = yield call(callApi.postProviderUser, payload)
      yield put({ type: actions.GET_PROVIDER_USER_DATA_REQUEST })
      yield put({ type: actions.POST_PROVIDER_USER_SUCCESS, userResult: res.data, providerUserMessage: 'Success' })
    } catch (e) {
      yield put({ type: actions.POST_PROVIDER_USER_FAILURE, userResult: {}, providerUserMessage: errorMessageHandler(e.data) })
    }
  })
}

export function* getProviderConfig() {
  yield takeEvery(actions.GET_PROVIDER_CONFIG_REQUEST, function* ({ payload }) {
    try {
      const res = yield call(authGet, { ...payload, url: providerUrls.getProviderConfig })
      if (res.status === 200) {
        yield put({
          type: actions.GET_PROVIDER_CONFIG_SUCCESS,
          data: res.data,
          message: get(res.data, 'message', 'Success')
        })
      } else {
        yield put({
          type: actions.GET_PROVIDER_CONFIG_FAILURE,
          data: [],
          message: get(res.data, 'message', 'Error')
        })
        yield put({
          type: actions.GET_DEFAULT_CONFIG_REQUEST
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_PROVIDER_CONFIG_FAILURE,
        data: [],
        message: get(e.data, 'message', 'Error')
      })
      yield put({
        type: actions.GET_DEFAULT_CONFIG_REQUEST
      })
    }
  })
}

