export default function* rootSaga() {
  yield all([
    fork(getProviderUserData),
    fork(getProviderList),
    // fork(getAgentProviderList),
    fork(postProviderUser),
    fork(getProviderConfig),
    fork(getProviderUser),
    fork(getDefaultConfig),
    fork(addProviderConfig),
    fork(updateProviderConfig),
    fork(getGroupList),
    fork(addProviderUser),
    fork(updateProviderUser),
    fork(updateProviderUserStatus),
    fork(addProvider),
    fork(getProviderDetails)
  ])
}
