import actions from './actions'

const initialState = {
  vehicleBrandList: [],
  vehicleModelList: [],
  vehicleModelDetails: [],
  vehicleVariantList: [],
  vehicleVariantDetail: [],
  vehicleSourceModelSimasList: [],
  vehicleSourceModelSamsatList: [],
  vehicleSourceModelDetails: [],
  modelWithDetails: '',
  error: '',
  success: ''
}

export default function vehicleModelManagerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.BRAND_LIST:
      return { ...state, vehicleBrandList: action.data }
    case actions.MODEL_LIST:
      return { ...state, vehicleModelList: action.data }
    case actions.MODEL_DETAILS:
      return { ...state, vehicleModelDetails: action.data }
    case actions.VARIANT_LIST:
      return { ...state, vehicleVariantList: action.data }
    case actions.VARIANT_DETAIL:
      return { ...state, vehicleVariantList: action.data }
    case actions.SOURCE_MODEL_SIMAS_LIST:
      return { ...state, vehicleSourceModelSimasList: action.data }
    case actions.SOURCE_MODEL_SAMSAT_LIST:
      return { ...state, vehicleSourceModelSamsatList: action.data }
    case actions.SOURCE_MODEL_DETAILS:
      return { ...state, vehicleModelDetails: action.data }
    case actions.MODEL_WITH_DETAILS:
      return { ...state, vehicleModelDetails: action.data }
    case actions.HANDLE_ERROR:
      return { ...state, error: action.data }
    case actions.HANDLE_SUCCESS:
      return { ...state, success: action.data }
    case actions.RESET_REDUX:
      return { ...initialState }
    default:
      return state
  }
}
