export function* approveShippingClaimRequest() {
  yield takeEvery('APPROVE_SHIPPING_CLAIM', function* (payload) {
    try {
      let claimId = payload.payload.claimId
      let res = yield call(callApi.approveShippingClaim, payload)
      if (res.status === 200) {
        yield put({ type: actions.ACTIVE_CLAIM_DETAIL, payload: { claimId } })
        yield put({ type: actions.APPROVE_SHIPPING_CLAIM_STATUS, approveShippingClaimStatus: 'success' })
      } else {
        yield put({ type: actions.APPROVE_SHIPPING_CLAIM_STATUS, approveShippingClaimStatus: res.data.error })
      }
    } catch (e) {
      yield put({ type: actions.APPROVE_SHIPPING_CLAIM_STATUS, approveShippingClaimStatus: 'Error' })
    }
  })
}

