import actions from './actions'

const initialState = {
    addUpdateMessage: '',
    addUpdateData: undefined,
    workshopList: [],
    workshoplListMessage: ''
}

export default function tapInsureReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_TAP_INSURE_CONFIG: {
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    }
    case actions.ADD_UPDATE_FINANCIAL_REPORTS_SUCCESS:
    case actions.ADD_UPDATE_FINANCIAL_REPORTS_FAILURE:
        return {
            ...state,
            addUpdateData: action.data,
            addUpdateMessage: action.addUpdateMessage
        }
    case actions.GET_WORKSHOP_REPORTS_SUCCESS:
    case actions.GET_WORKSHOP_REPORTS_FAILURE:
        return {
            ...state,
            workshopList: action.data,
            workshoplListMessage: action.getWorkshoplListMessage
        }
    default:
      return state
  }
}
