import actions from './actions'

const initialState = {
}

export default function umbrellaReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_MASTERDATA:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    case actions.GET_MASTER_DATA_SUCCESS:
    case actions.GET_MASTER_DATA_FAILURE:
      return {
        ...state,
        ...action.target,
        getMasterDataMessage: action.message
      }
    default:
      return state
  }
}
