export function * getAgentQuestionnaireDetailSaga () {
  yield takeEvery(actions.GET_AGENT_QUESTIONNAIRE_DETAIL_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, { url: configUrl.getAgentQuestionnaireApi(payload) })
      if (res.status === 200) {
        yield put({
          type: actions.GET_AGENT_QUESTIONNAIRE_DETAIL_SUCCESS,
          data: res.data,
          message: 'success'
        })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({
          type: actions.GET_AGENT_QUESTIONNAIRE_DETAIL_FAILURE,
          data: {},
          message
        })
      }
    } catch (res) {
      const message = exceptionHandlerSanitizer(res.data)
      yield put({
        type: actions.GET_AGENT_QUESTIONNAIRE_DETAIL_FAILURE,
        data: {},
        message
      })
    }
  })
}

export function * uploadDocument () {
  yield takeEvery(actions.UPLOAD_DOCUMENT_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPostFormData, { ...payload, url: configUrl.uploadDocumentUrl })
      if ([201, 200].includes(res.status)) {
        yield put({
          type: actions.UPLOAD_DOCUMENT_SUCCESS,
          uploadDocumentMessage: 'Success'
        })
        yield put({ payload: payload.params, type: actions.GET_AGENT_DETAIL_REQUEST })
      } else {
        yield put({ type: actions.UPLOAD_DOCUMENT_FAILURE, uploadDocumentMessage: 'Failed uploading' })
        yield put({ payload: payload.params, type: actions.GET_AGENT_DETAIL_REQUEST })
      }
    } catch (error) {
      yield put({ type: actions.UPLOAD_DOCUMENT_FAILURE, uploadDocumentMessage: error.message })
      yield put({ payload: payload.params, type: actions.GET_AGENT_DETAIL_REQUEST })
    }
  })
}

