export function * getAgentInsuranceList () {
  yield takeEvery(actions.GET_AGENT_INSURANCE_LIST_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, { query: payload, url: configUrl.getAgentInsuranceList })
      if (res.status === 200) {
        const policyList = res.data || []
        const metadata = res.data.meta_data || {}
        const metadataCore = res.data.core_svc_data.metadata || {}
        yield put({ type: actions.GET_AGENT_INSURANCE_LIST_SUCCESS, agentPolicyList: policyList, metadata, metadataCore, policyMessage: 'success' })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({ type: actions.GET_AGENT_INSURANCE_LIST_FAILURE, policyMessage: message })
      }
    } catch (res) {
      const message = exceptionHandlerSanitizer(res.data)
      yield put({ type: actions.GET_AGENT_INSURANCE_LIST_FAILURE, policyMessage: message })
    }
  })
}

