export function * updateInstallmentPayment () {
  yield takeEvery(actions.UPDATE_INSTALLMENT_PAYMENT_REQUEST, function * ({ payload }) {
    const { policyId, onSuccess, ...body } = payload
    try {
      const res = yield call(authPut, { url: installmentPaymentApi(policyId), body })
      if (res.status === 200) {
        yield put({ type: actions.UPDATE_INSTALLMENT_PAYMENT_SUCCESS })
        if (onSuccess) onSuccess()
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({ type: actions.UPDATE_INSTALLMENT_PAYMENT_FAILURE, message })
      }
    } catch (res) {
      const message = exceptionHandlerSanitizer(res.data)
      yield put({ type: actions.UPDATE_INSTALLMENT_PAYMENT_FAILURE, message })
    }
  })
}

export function * activateAgentPolicy () {
  yield takeEvery(actions.ACTIVATE_AGENT_POLICY_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPost, { body: payload, url: configUrl.acceptAgentPolicy(payload.policyId) })
      if (res.status === 200) {
        yield put({ type: actions.ACTIVATE_AGENT_POLICY_SUCCESS, agentPolicy: res.data, policyMessage: 'success' })
        yield put({ payload: payload, type: actions.GET_AGENT_INSURANCE_DATA_REQUEST })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({ type: actions.ACTIVATE_AGENT_POLICY_FAILURE, policyMessage: message })
      }
    } catch (res) {
      const message = exceptionHandlerSanitizer(res.data)
      yield put({ type: actions.ACTIVATE_AGENT_POLICY_FAILURE, policyMessage: message })
    }
  })
}

