export function * rejectAgent () {
  yield takeEvery(actions.REJECT_AGENT_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPost, {
        url: configUrl.rejectAgent,
        params: { agent_ref: payload.agentRef },
        body: { rejected_reason: payload.rejectedReason, user_id: '' }
      })
      if (res.status === 200) {
        yield put({
          type: actions.REJECT_AGENT_SUCCESS,
          rejectAgentMsg: 'success'
        })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({
          type: actions.REJECT_AGENT_FAILURE,
          rejectAgentMsg: message
        })
      }
    } catch (res) {
      const message = exceptionHandlerSanitizer(res.data)
      yield put({
        type: actions.REJECT_AGENT_FAILURE,
        rejectAgentMsg: message
      })
    }
  })
}

