export function * createDependentAgentSaga () {
  yield takeEvery(actions.CREATE_DEPENDENT_AGENT_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPost, {
        body: payload,
        url: configUrl.addDependentAgent
      })
      if (res.status === 200 || res.status === 201) {
        yield put({
          type: actions.CREATE_DEPENDENT_AGENT_SUCCESS,
          data: res.data || {},
          message: 'success'
        })
      } else {
        const message = res.data || exceptionHandlerSanitizer(res.data)
        yield put({
          type: actions.CREATE_DEPENDENT_AGENT_FAILURE,
          data: {},
          message
        })
      }
    } catch (res) {
      yield put({
        type: actions.CREATE_DEPENDENT_AGENT_FAILURE,
        data: res.data,
        message: res.status === 409 ? (res.data?.detail || res.status) : exceptionHandlerSanitizer(res.data)
      })
    }
  })
}

