export function * claimValidate () {
  yield takeEvery(actions.AGENT_CLAIM_VALIDATE_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, { query: payload, url: configUrl.validateAgentClaim })
      if (res.status === 200) {
        yield put({
          type: actions.AGENT_CLAIM_VALIDATE_SUCCESS,
          dataValidate: res.data,
          claimValidateStatus: 'success'
        })
      }
    } catch (err) {
      if (err.data) {
        yield put({
          type: actions.AGENT_CLAIM_VALIDATE_FAILURE,
          dataValidate: {},
          claimValidateStatus: err.data.error,
          claimValidateStatusCode: err.data.code
        })
      } else {
        yield put({
          type: actions.AGENT_CLAIM_VALIDATE_FAILURE,
          dataValidate: {},
          claimValidateStatus: 'Failed while validating claim',
          claimValidateStatusCode: ''
        })
      }
    }
  })
}

export function * createClaimRequest () {
  yield takeEvery(actions.CREATE_AGENT_CLAIM_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPost, { body: payload, url: configUrl.createAgentClaim })
      if (res.status === 201) {
        const { claim_id } = res.data // eslint-disable-line
        yield put({
          type: actions.CREATE_AGENT_CLAIM_SUCCESS,
          claimId: claim_id,
          createClaimStatus: 'success'
        })
      }
    } catch (err) {
      if (err.data) {
        const errMessage = err.data.error || 'Ooops, something went terribly wrong!'
        yield put({
          type: actions.CREATE_AGENT_CLAIM_FAILURE,
          createClaimStatus: errMessage
        })
      } else {
        yield put({
          type: actions.CREATE_AGENT_CLAIM_FAILURE,
          createClaimStatus: 'Error during claim creation'
        })
      }
    }
  })
}

