export function * validatePolicyRequest () {
  yield takeEvery(actions.VALIDATE_POLICY_DATA_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authPost, { body: payload, url: configUrl.validatePolicyData })
      if (res.status === 200) {
        yield put({ type: actions.VALIDATE_POLICY_DATA_SUCCESS, validatePolicy: { ...res.data }, validatePolicyStatus: 'success' })
      } else {
        const message = exceptionHandlerSanitizer(res.data)
        yield put({ type: actions.VALIDATE_POLICY_DATA_FAILURE, validatePolicyError: message })
      }
    } catch (res) {
      const message = exceptionHandlerSanitizer(res.data)
      yield put({ type: actions.VALIDATE_POLICY_DATA_FAILURE, validatePolicyError: message })
    }
  })
}

