export function * getVehicleValidYearsSaga () {
  yield takeEvery(actions.GET_VEHICLE_VALID_YEARS_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, {
        url: configUrl.getVehicleValidYears(payload)
      })
      if (res.status === 200) {
        // Extract only the years from the response array
        const years = Array.isArray(res.data)
          ? res.data.map(item => item.year).filter(year => year !== undefined && year !== null)
          : []
        yield put({
          type: actions.GET_VEHICLE_VALID_YEARS_SUCCESS,
          vehicleValidYears: years,
          vehicleValidYearsMessage: 'success'
        })
      } else {
        yield put({
          type: actions.GET_VEHICLE_VALID_YEARS_FAILURE,
          vehicleValidYears: [],
          vehicleValidYearsMessage: res.data && res.data.error
        })
      }
    } catch (res) {
      yield put({
        type: actions.GET_VEHICLE_VALID_YEARS_FAILURE,
        vehicleValidYears: [],
        vehicleValidYearsMessage: res.data && res.data.error
      })
    }
  })
}

