const actions = {
  GET_LIST_GROUPS: 'GET_LIST_GROUPS',
  LIST_GROUPS: 'LIST_GROUPS',
  FAILED_GET_LIST_GROUPS: 'FAILED_GET_LIST_GROUPS',
  getListGroups: payload => ({
    type: actions.GET_LIST_GROUPS,
    payload
  }),
  listGroups: payload => ({
    type: actions.LIST_GROUPS,
    payload
  }),
  failedGetListGroups: payload => ({
    type: actions.FAILED_GET_LIST_GROUPS,
    payload
  })
}
export default actions
