import React, { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { Avatar, Divider, Popover } from 'antd'
import authAction from '../../redux/auth/actions'
import appAction from '../../redux/app/actions'
import UserActions from '../../PasarApp/redux/user/actions'
import { TopbarUserStyle, TopbarPopupStyle } from './topbarUser.style'

const { logout } = authAction
const { closeAll } = appAction
const { updateTopbarActiveModal } = UserActions

class TopbarUser extends Component {
  constructor (props) {
    super(props)
    this.state = {
      visible: false,
      user: {}
    }
  }

  hide = () => {
    this.setState({ visible: false })
  }

  handleVisibleChange = () => {
    this.setState({ visible: !this.state.visible })
  }

  handleProfileClick = () => {
    this.setState({ visible: false })
    this.props.history.push('/profile')
  }

  handleSecurityClick = () => {
    this.setState({ visible: false })
    this.props.history.push('/profile')
  }

  render () {
    const { user = {} } = this.props
    const { visible } = this.state

    const upperCaseLetter = get(user, 'email', '')
    const content = (
      <TopbarUserStyle>
        <div className='user-email'>
          {get(user, 'email', '')}
        </div>
        <Divider />
        <div className='link' onClick={this.handleProfileClick}>
          Profile
        </div>
        <div className='link' onClick={this.handleSecurityClick}>
          Security
        </div>
        <Divider />
        <div
          className='logout link'
          onClick={() => {
            this.props.logout()
            this.props.closeAll()
          }}
        >
          Logout
        </div>
      </TopbarUserStyle>
    )

    return (
      <div>
        <Popover
          content={content}
          trigger='click'
          visible={visible}
          onVisibleChange={this.handleVisibleChange}
          arrowPointAtCenter
          placement='bottomLeft'
        >
          <TopbarPopupStyle>
            <div className='isoImgWrapper'>
              <Avatar className='avatar' size='large'>
                {upperCaseLetter ? upperCaseLetter[0].toUpperCase() : 'U'}
              </Avatar>
              <span className='userActivity online' />
            </div>
          </TopbarPopupStyle>
        </Popover>
      </div>
    )
  }
}

export default connect(state => ({
  user: state.Auth.profile
}), {
  logout,
  closeAll,
  updateTopbarActiveModal
})(TopbarUser)
