import actions from './action'

const initialState = {
  avaChat: []
}

export default function avaReducer (state = initialState, action) {
  switch (action.type) {
    case actions.GET_AVA_CHAT_SUCCESS:
    case actions.GET_AVA_CHAT_FAILURE:
      return {
        ...state,
        avaChat: action.data
      }
    default:
      return state
  }
}
