import actions from './actions'

const initialState = {
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.LIST_GROUPS:
      return {
        ...state,
        groupLists: action.groupLists,
        messageGroupList: action.messageGroupList
      }
    default:
      return state
  }
}
