/* eslint no-loop-func: 0 */
/* eslint-env es6 */
const parseResponseError = (err, initialError) => {
  let errString = ''
  if (err !== undefined) {
    if (typeof err === 'string') {
      return err
    }
    if (Object.keys(err).length > 0) {
      for (let key in err) {
        /* no-loop-func */
        err[key].forEach(val => {
          errString += `${val},`
        })
      }
      errString = errString.slice(0, -1)
    }
  }
  if (errString !== '') {
    return errString
  } else {
    return initialError
  }
}

export default parseResponseError
