import actions from './actions'

const initialState = {
  data: [],
  getNotficationsListStatus: '',
  retriggerNotificationStatus: '',
  dataTemplates: [],
  masterData: {},
  dataTrigger: [],
  dataFilteredTrigger: undefined,
  getTemplatesStatus: '',
  getMasterDataStatus: '',
  updateTemplateStatus: '',
  getTemplateDetailStatus: '',
  getFilteredTriggerDataStatus: '',
  getTriggerDataStatus: '',
  addTemplateStatus: '',
  addLanguageTemplateStatus: '',
  filterTemplateStatus: '',
  dataFilteredTemplate: [],
  getActionGroupStatus: '',
  addTriggerStatus: '',
  updateTriggerStatus: '',
  getTriggerByIdStatus: '',
  dataTriggerById: {},
  gePublishedTriggerStatus: '',
  publishStatus: '',
  getPublishTemplateStatus: '',
  publishTemplateStatus: '',
  getProductsByPartnerCodeStatus: undefined,
  addDefaultTriggerStatus: '',
  addActionGroupStatus: '',
  addTriggerTypeStatus: '',
  exportNotificationTemplatesSuccess: undefined,
  exportNotificationTemplatesFailure: undefined,
  exportNotificationTemplates: undefined,
  exportNotificationTriggerFailure: undefined,
  exportNotificationTriggerSuccess: undefined,
  exportNotificationTriggers: undefined,
  importNotificationTemplatesSuccess: undefined,
  importNotificationTemplatesFailure: undefined,
  importNotificationTemplates: undefined,
  importNotificationTriggersSuccess: undefined,
  importNotificationTriggersFailure: undefined,
  importNotificationTriggers: undefined,
  templateUploadURl: '',
  templateUploadURlMessage: '',
  getTemplateData: '',
  getTemplateMessage: '',
  updateTemplateMessage: '',
  topLevelAttributes: '',
  topLevelAttributesMessage: '',
  eventTypeData: '',
  eventTypeMessage: '',
  getNewTriggerData: '',
  getNewTriggerDataMessage: '',
  getNewActionGroup: '',
  getNewActionGroupMessage: '',
  addNewActionGroupData: '',
  addNewActionGroupDataMessage: '',
  addNewEventTypestatusMessage: '',
  getNewTemplateListData: '',
  getNewTemplateListDataMessage: undefined,
  publishTriggerstatusMessage: undefined,
  unPublishTriggerstatusMessage: undefined,
  exportTriggerdata: [],
  exportTriggerMessage: undefined,
  importTriggerMessage: undefined,
  deleteTriggerStatusMessage: undefined,
  templateDetailBodyData: '',
  templateDetailBodyDataMessage: undefined,
  addNewTriggerStatusMessage: '',
  triggerDetailData: [],
  triggerDetailMessage: '',
  editDetailTriggerMessage: '',
  thirdPartyTemplate: [],
  templatesPaginatedData: {},
  templatesPaginatedStatus: undefined
}

export default function partnerReducer(state = initialState, action) {
  const { payload } = action
  switch (action.type) {
    case actions.RESET_NOTIFICATIONS_REDUX_STATE:
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    case actions.RESET_NOTIFICATION_CORE:
      return {
        ...state,
        updateTemplateStatus: '',
        getTemplateDetailStatus: '',
        addTemplateStatus: '',
        filterTemplateStatus: '',
        getActionGroupStatus: '',
        addTriggerStatus: '',
        dataFilteredTrigger: undefined,
        getMasterDataStatus: '',
        updateTriggerStatus: '',
        getTriggerByIdStatus: '',
        gePublishedTriggerStatus: '',
        publishStatus: '',
        getPublishTemplateStatus: '',
        publishTemplateStatus: '',
        getProductsByPartnerCodeStatus: '',
        addDefaultTriggerStatus: '',
        addActionGroupStatus: '',
        addTriggerTypeStatus: '',
        addLanguageTemplateStatus: '',
        exportNotificationTemplatesSuccess: undefined,
        exportNotificationTemplatesFailure: undefined,
        exportNotificationTemplates: undefined,
        exportNotificationTriggerFailure: undefined,
        exportNotificationTriggerSuccess: undefined,
        exportNotificationTriggers: undefined,
        importNotificationTemplatesSuccess: undefined,
        importNotificationTemplatesFailure: undefined,
        importNotificationTemplates: undefined,
        importNotificationTriggersSuccess: undefined,
        importNotificationTriggersFailure: undefined,
        importNotificationTriggers: undefined,
        eventTypeMessage: '',
        getNewTriggerDataMessage: '',
        getNewActionGroupMessage: '',
        addNewActionGroupDataMessage: '',
        addNewEventTypestatusMessage: '',
        getNewTemplateListDataMessage: undefined,
        publishTriggerstatusMessage: undefined,
        unPublishTriggerstatusMessage: undefined,
        exportTriggerMessage: undefined,
        importTriggerMessage: undefined,
        templateDetailBodyDataMessage: undefined,
        addNewTriggerStatusMessage: ''
      }
    case actions.DATA_TEMPLATES_SUCCESS:
    case actions.DATA_TEMPLATES_FAILURE:
      return {
        ...state,
        dataTemplates: action.data,
        getTemplatesStatus: action.getTemplatesStatus
      }
    case actions.MASTER_DATA:
      return {
        ...state,
        masterData: action.data,
        getMasterDataStatus: action.getMasterDataStatus
      }
    case actions.GET_NOTIFICATIONS_LIST_SUCCESS:
    case actions.GET_NOTIFICATIONS_LIST_FAILURE:
      return {
        ...state,
        data: action.data,
        getNotficationsListStatus: action.getNotficationsListStatus
      }
    case actions.SUCCESS_RETRIGGER_NOTIFICATION:
      return {
        ...state,
        retriggerNotificationStatus: action.retriggerNotificationStatus
      }
    case actions.FAILED_RETRIGGER_NOTIFICATION:
      return {
        ...state,
        retriggerNotificationStatus: action.retriggerNotificationStatus
      }
    case actions.UPDATE_TEMPLATE_STATUS:
      return {
        ...state,
        updateTemplateStatus: action.updateTemplateStatus
      }
    case actions.GET_TEMPLATE_DETAIL_STATUS:
      return {
        ...state,
        dataDetailTemplate: action.data,
        getTemplateDetailStatus: action.getTemplateDetailStatus
      }
    case actions.GET_FILTERED_TRIGGER_DATA_STATUS:
      return {
        ...state,
        dataFilteredTrigger: action.data,
        getFilteredTriggerDataStatus: action.getFilteredTriggerDataStatus
      }
    case actions.GET_TRIGGERED_DATA_SUCCESS:
    case actions.GET_TRIGGERED_DATA_FAILURE:
      return {
        ...state,
        dataTrigger: action.data,
        getTriggerDataStatus: action.getTriggerDataStatus
      }
    case actions.CLOSE_VIEW_BODY_HTML:
      return {
        ...state,
        getTemplateDetailStatus: '',
        dataDetailTemplate: undefined
      }
    case actions.ADD_TEMPLATE_STATUS:
      return {
        ...state,
        addTemplateStatus: action.addTemplateStatus
      }
    case actions.ADD_LANGUAGE_TEMPLATE_STATUS:
      return {
        ...state,
        addLanguageTemplateStatus: action.addLanguageTemplateStatus
      }
    case actions.FILTER_TEMPLATE_DATA:
      return {
        ...state,
        dataFilteredTemplate: action.data,
        filterTemplateStatus: action.filterTemplateStatus
      }
    case actions.GET_ACTIONS_GROUP_DATA:
      return {
        ...state,
        dataActionGroup: action.data,
        getActionGroupStatus: action.getActionGroupStatus
      }
    case actions.ADD_TRIGGER_STATUS:
      return {
        ...state,
        addTriggerStatus: action.addTriggerStatus
      }
    case actions.RESET_FILTERED_DATA_TRIGGER:
      return {
        ...state,
        dataFilteredTrigger: undefined,
        getFilteredTriggerDataStatus: ''
      }
    case actions.UPDATE_TRIGGER_STATUS:
      return {
        ...state,
        updateTriggerStatus: action.updateTriggerStatus
      }
    case actions.GET_TRIGGER_BY_ID_SUCCESS:
    case actions.GET_TRIGGER_BY_ID_FAILURE:
      return {
        ...state,
        dataTriggerById: action.data,
        getTriggerByIdStatus: action.getTriggerByIdStatus
      }
    case actions.GET_PUBLISHED_TRIGGER_STATUS:
      return {
        ...state,
        dataPublishedTrigger: action.data,
        gePublishedTriggerStatus: action.gePublishedTriggerStatus
      }
    case actions.PUBLISH_STATUS:
      return {
        ...state,
        publishStatus: action.publishStatus
      }
    case actions.GET_PUBLISH_TEMPLATE_STATUS:
      return {
        ...state,
        dataPublishedTemplate: action.data,
        getPublishTemplateStatus: action.getPublishTemplateStatus
      }
    case actions.PUBLISH_TEMPLATE_STATUS:
      return {
        ...state,
        publishTemplateStatus: action.publishTemplateStatus
      }
    case actions.GET_PRODUCTS_BY_PARTNER_CODE_STATUS:
      return {
        ...state,
        dataProducts: action.data,
        getProductsByPartnerCodeStatus: action.getProductsByPartnerCodeStatus
      }
    case actions.ADD_DEFAULT_TRIGGER_STATUS:
      return {
        ...state,
        addDefaultTriggerStatus: action.addDefaultTriggerStatus
      }
    case actions.ADD_ACTION_GROUP_STATUS:
      return {
        ...state,
        addActionGroupStatus: action.addActionGroupStatus
      }
    case actions.ADD_TRIGGER_TYPE_STATUS:
      return {
        ...state,
        addTriggerTypeStatus: action.addTriggerTypeStatus
      }
    case actions.EXPORT_NOTIFICATION_TEMPLATES_SUCCESS:
      return {
        ...state,
        exportNotificationTemplates: action.data,
        exportNotificationTemplatesSuccess: action.exportNotificationTemplatesSuccess
      }
    case actions.EXPORT_NOTIFICATION_TEMPLATES_FAILURE:
      return {
        ...state,
        exportNotificationTemplates: action.data,
        exportNotificationTemplatesFailure: action.exportNotificationTemplatesFailure
      }
    case actions.EXPORT_NOTIFICATION_TRIGGER_SUCCESS:
      return {
        ...state,
        exportNotificationsTriggers: action.data,
        exportNotificationTriggerSuccess: action.exportNotificationTriggerSuccess
      }
    case actions.EXPORT_NOTIFICATION_TRIGGER_FAILURE:
      return {
        ...state,
        exportNotificationsTriggers: action.data,
        exportNotificationTriggerFailure: action.exportNotificationTriggerFailure
      }
    case actions.IMPORT_NOTIFICATION_TEMPLATES_SUCCESS:
      return {
        ...state,
        importNotificationTemplates: action.data,
        importNotificationTemplatesSuccess: action.importNotificationTemplatesSuccess
      }
    case actions.IMPORT_NOTIFICATION_TEMPLATES_FAILURE:
      return {
        ...state,
        importNotificationTemplates: action.data,
        importNotificationTemplatesFailure: action.importNotificationTemplatesFailure
      }
    case actions.IMPORT_NOTIFICATION_TRIGGERS_SUCCESS:
      return {
        ...state,
        importNotificationTriggers: action.data,
        importNotificationTriggersSuccess: action.importNotificationTriggersSuccess
      }
    case actions.IMPORT_NOTIFICATION_TRIGGERS_FAILURE:
      return {
        ...state,
        importNotificationTriggers: action.data,
        importNotificationTriggersFailure: action.importNotificationTriggersFailure
      }
    case actions.CLEAR_VIEW_NOTIFICATION_LIST:
      return {
        ...state,
        exportNotificationsTriggers: undefined,
        exportNotificationTemplates: undefined
      }
    case actions.CLEAR_TRIGGER_MESSAGES:
      return {
        ...state,
        importNotificationTriggersFailure: undefined,
        importNotificationTriggersSuccess: undefined,
        exportNotificationTriggerFailure: undefined,
        exportNotificationTriggerSuccess: undefined
      }
    case actions.CLEAR_TEMPLATES_MESSAGES:
      return {
        ...state,
        importNotificationTemplatesFailure: undefined,
        exportNotificationTemplatesSuccess: undefined,
        exportNotificationTemplatesFailure: undefined,
        importNotificationTemplatesSuccess: undefined
      }
    case actions.GET_NOTIFICATIONS_MASTER_DATA_SUCCESS:
    case actions.GET_NOTIFICATIONS_MASTER_DATA_FAILURE:
      return {
        ...state,
        masterData: action.data,
        notificationsMasterDataMsg: action.message
      }
    case actions.POST_UPLOAD_BULK_NOTIFICATIONS_SUCCESS:
    case actions.POST_UPLOAD_BULK_NOTIFICATIONS_FAILURE:
      return {
        ...state,
        postUploadBulkNotificationsMsg: action.message
      }
    case actions.GET_BULK_NOTIFICATIONS_FILES_SUCCESS:
    case actions.GET_BULK_NOTIFICATIONS_FILES_FAILURE:
      return {
        ...state,
        bulkNotificationsFiles: action.data,
        bulkNotificationsFilesMsg: action.message
      }
    case actions.GET_NOTIFICATIONS_TRACE_SUCCESS:
    case actions.GET_NOTIFICATIONS_TRACE_FAILURE:
      return {
        ...state,
        notificationsTrace: action.data,
        notificationsTraceMsg: action.message
      }
    case actions.UPLOAD_NOTIFICATIONS_TEMPLATE_ATTRIBUTE_SUCCESS:
    case actions.UPLOAD_NOTIFICATIONS_TEMPLATE_ATTRIBUTE_FAILURE:
      return {
        ...state,
        templateUploadURl: action.url,
        templateUploadURlMessage: action.sendUploadMessage
      }
    case actions.GET_NOTIFICATION_SAMPLE_TEMPLATE_SUCCESS:
    case actions.GET_NOTIFICATION_SAMPLE_TEMPLATE_FAILURE:
      return {
        ...state,
        getTemplateData: action.data,
        getTemplateMessage: action.message
      }
    case actions.UPLOAD_NOTIFICATION_SAMPLE_TEMPLATE_SUCCESS:
    case actions.UPLOAD_NOTIFICATION_SAMPLE_TEMPLATE_FAILURE:
      return {
        ...state,
        updateTemplateMessage: action.message
      }
    case actions.GET_TOP_LEVEL_ATTRIBUTES_SUCCESS:
    case actions.GET_TOP_LEVEL_ATTRIBUTES_FAILURE:
      return {
        ...state,
        topLevelAttributes: action.attributes,
        topLevelAttributesMessage: action.attributesMessage
      }
    case actions.GET_EVENT_TYPES_SUCCESS:
    case actions.GET_EVENT_TYPES_FAILURE:
      return {
        ...state,
        eventTypeData: action.data,
        eventTypeMessage: action.eventListStatus
      }
    case actions.GET_ACTION_GROUP_SUCCESS:
    case actions.GET_ACTION_GROUP_FAILURE:
      return {
        ...state,
        getNewActionGroup: action.data,
        getNewActionGroupMessage: action.getNewActionGroupStatus
      }
    case actions.GET_TRIGGER_DATA_NEW_SUCCESS:
    case actions.GET_TRIGGER_DATA_NEW_FAILURE:
      return {
        ...state,
        getNewTriggerData: action.data,
        getNewTriggerDataMessage: action.getTriggerDataStatusNew
      }
    case actions.ADD_ACTION_GROUP_SUCCESS:
    case actions.ADD_ACTION_GROUP_FAILURE:
      return {
        ...state,
        addNewActionGroupData: action.data,
        addNewActionGroupDataMessage: action.addNewActionGroupstatus
      }
    case actions.ADD_EVENT_TYPE_SUCCESS:
    case actions.ADD_EVENT_TYPE_FAILURE:
      return {
        ...state,
        addNewEventTypestatusMessage: action.addNewEventTypestatus
      }
    case actions.GET_NEW_TEMPLATE_LIST_SUCCESS:
    case actions.GET_NEW_TEMPLATE_LIST_FAILURE:
      return {
        ...state,
        getNewTemplateListData: action.data,
        getNewTemplateListDataMessage: action.templateListStatus
      }
    case actions.PUBLISH_TRIGGER_DATA_SUCCESS:
    case actions.PUBLISH_TRIGGER_DATA_FAILURE:
      return {
        ...state,
        publishTriggerstatusMessage: action.publishTriggerStatus
      }
    case actions.UNPUBLISH_TRIGGER_DATA_SUCCESS:
    case actions.UNPUBLISH_TRIGGER_DATA_FAILURE:
      return {
        ...state,
        unPublishTriggerstatusMessage: action.unPublishTriggerStatus
      }
    case actions.IMPORT_TRIGGER_DATA_SUCCESS:
    case actions.IMPORT_TRIGGER_DATA_FAILURE:
      return {
        ...state,
        importTriggerMessage: action.importTriggerstatus
      }
    case actions.EXPORT_TRIGGER_DATA_SUCCESS:
    case actions.EXPORT_TRIGGER_DATA_FAILURE:
      return {
        ...state,
        exportTriggerdata: action.data,
        exportTriggerMessage: action.exportTriggerstatus
      }
    case actions.DELETE_TRIGGER_SUCCESS:
    case actions.DELETE_TRIGGER_FAILURE:
      return {
        ...state,
        deleteTriggerStatusMessage: action.deleteTriggerStatus
      }
    case actions.GET_NEW_TEMPLATE_DETAIL_SUCCESS:
    case actions.GET_NEW_TEMPLATE_DETAIL_FAILURE:
      return {
        ...state,
        templateDetailBodyData: action.data,
        templateDetailBodyDataMessage: action.templateDetailstatus
      }
    case actions.ADD_NEW_TRIGGER_SUCCESS:
    case actions.ADD_NEW_TRIGGER_FAILURE:
      return {
        ...state,
        addNewTriggerStatusMessage: action.addNewTriggerStatus
      }
    case actions.GET_TRIGGER_DETAIL_NEW_SUCCESS:
    case actions.GET_TRIGGER_DETAIL_NEW_FAILURE:
      return {
        ...state,
        triggerDetailData: action.data,
        triggerDetailMessage: action.triggerdetailRequestCall
      }
    case actions.EDIT_TRIGGER_SUCCESS:
    case actions.EDIT_TRIGGER_FAILURE:
      return {
        ...state,
        editDetailTriggerMessage: action.editTriggerStatus
      }
    case actions.GET_THIRD_PARTY_TEMPLATE_REQUEST:

      return {
        ...state,
      }
    case actions.GET_THIRD_PARTY_TEMPLATE_SUCCESS:

      return {
        ...state,
      }
    case actions.GET_THIRD_PARTY_TEMPLATE_FAILURE:
      return {
        ...state,
      }
    case actions.GET_TEMPLATES_PAGINATED_SUCCESS:
    case actions.GET_TEMPLATES_PAGINATED_FAILURE:
      return {
        ...state,
        templatesPaginatedData: action.data,
        templatesPaginatedStatus: action.templatesPaginatedStatus
      }
    default:
      return state
  }
}
