import { all, takeEvery, call, put, fork } from 'redux-saga/effects'

import actions from './action'
import AvaUrl from '../../../request/urls/ava'
import authGet from '../../../request/methods/authGet'

export function * getAvaMessages () {
  yield takeEvery(actions.GET_AVA_CHAT_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, { ...payload, url: AvaUrl.getAvaMessages })
      if (res.status === 200) {
        yield put({
          type: actions.GET_AVA_CHAT_SUCCESS,
          data: res.data
        })
      } else {
        yield put({
          type: actions.GET_AVA_CHAT_FAILURE,
          data: []
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_AVA_CHAT_FAILURE,
        data: []
      })
    }
  })
}

export default function * rootSaga () {
  yield all([
    fork(getAvaMessages)
  ])
}
