export function* getRevenueShareMeta() {
  yield takeEvery('GET_REVENUE_SHARE_META', function* (payload) {
    try {
      const res = yield call(callApi.getRevenueShareMeta, payload)
      if (res.status === 200) {
        yield put({ type: policyActions.GET_PARTNERS_REQUEST })
        yield put({ type: policyActions.GET_PRODUCTS_REQUEST })
        yield put({ type: actions.REVENUE_SHARE_META_DATA, data: res.data.data, getRevenueShareMetaStatus: 'success' })
      } else {
        yield put({ type: actions.REVENUE_SHARE_META_DATA, data: [], getRevenueShareMetaStatus: _.get(res, 'data.message') })
      }
    } catch (e) {
      yield put({ type: actions.REVENUE_SHARE_META_DATA, data: [], getRevenueShareMetaStatus: 'Error' })
    }
  })
}

