export function* getReconList() {
  yield takeEvery(actions.GET_AUTO_RECON_LIST_REQUEST, function* ({ payload = {} }) {
    try {
      const res = yield call(authGet, { ...payload, url: reconUrls.getAutoReconListUrl })
      const responseData = res.data
      if (res.status === 200 && responseData) {
        const {
          recon_requests: data = [],
          metadata = {}
        } = responseData
        // yield put({ type: policyActions.GET_PARTNERS_REQUEST })
        // yield put({ type: policyActions.GET_PRODUCTS_REQUEST })
        yield put({ type: actions.GET_AUTO_RECON_LIST_SUCCESS, data, metadata, message: 'success' })
      } else {
        yield put({ type: actions.GET_AUTO_RECON_LIST_FAILURE, data: [], message: _.get(res, 'data.message') })
      }
    } catch (e) {
      yield put({ type: actions.GET_AUTO_RECON_LIST_FAILURE, data: [], message: _.get(e, 'data.error', 'Failed') })
    }
  })
}

