export function* postreconFeedbackResolverRequest() {
  yield takeEvery(actions.POST_RECON_FEEDBACK_REQUEST, function* ({ payload }) {
    try {
      let res = yield call(authPost, { ...payload, url: reconUrls.reconPostFeedback })
      if (res.status === 200 || res.status === 201) {
        const paramId = _.get(res, 'data.request_id', '')
        const params = [
          {
            query: {
              limit: 10,
              state: 'missing_in_pp',
              id: paramId
            }
          },
          {
            query: {
              limit: 10,
              state: 'missing_in_partner',
              id: paramId
            }
          },
          {
            query: {
              limit: 10,
              state: 'premium_mismatch',
              id: paramId
            }
          }
        ]
        const responses = yield params.map(p => {
          return { ...call(authGet, { ...p, url: reconUrls.reconResolverDetail }) }
        })
        const listView = new Set(responses.map(item => _.get(item, 'data.meta.total')))
        if (listView.size === 1) {
          const payload = {
            id: paramId
          }
          yield call(callApi.reconFeedbackResolverSubmitRequestcall, payload)
        }
        res = {
          ...res,
          data: {
            ...res.data,
            page: listView.size === 1 ? 'list' : 'detail-page'
          }
        }
        yield put({
          type: actions.POST_RECON_FEEDBACK_SUCCESS,
          data: _.get(res, 'data', {}),
          message: _.get(res.data, 'message', 'Success')
        })
      } else {
        yield put({
          type: actions.POST_RECON_FEEDBACK_FAILURE,
          data: _.get(res, 'data', {}),
          message: _.get(res.data, 'status', 'Error')
        })
      }
    } catch (e) {
      yield put({
        type: actions.POST_RECON_FEEDBACK_FAILURE,
        data: {},
        message: _.get(e.data, 'status', 'Error')
      })
    }
  })
}

export function* reconFeedbackResolverSubmitRequest() {
  yield takeEvery(actions.POST_RECON_SUBMIT_FEEDBACK_REQUEST, function* ({ payload }) {
    try {
      const res = yield call(callApi.reconFeedbackResolverSubmitRequestcall, payload)
      if (res.status === 200) {
        yield put({
          type: actions.POST_RECON_SUBMIT_FEEDBACK_SUCCESS,
          data: _.get(res, 'data', {}),
          message: _.get(res.data, 'message', 'Success')
        })
      } else {
        yield put({
          type: actions.POST_RECON_SUBMIT_FEEDBACK_FAILURE,
          data: _.get(res, 'data', {}),
          message: _.get(res.data, 'error', 'Error')
        })
      }
    } catch (e) {
      yield put({
        type: actions.POST_RECON_SUBMIT_FEEDBACK_FAILURE,
        data: {},
        message: _.get(e.data, 'error', 'Error')
      })
    }
  })
}

