import actions from './actions'

const initialState = {
  data: [],
  reconId: '',
  fileRows: [],
  fileDetails: {},
  reconList: [],
  reconDetails: [],
  reconFiles: [],
  reconRemarks: []
}

export default function goRideReconReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_LOADING_STATES:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    case actions.GET_CURRENT_RECON_SUCCESS:
    case actions.GET_CURRENT_RECON_FAILURE:
    case actions.POST_NEW_RECON_SUCCESS:
    case actions.POST_NEW_RECON_FAILURE:
      return {
        ...state,
        reconId: action.reconId
      }
    case actions.GET_RECON_STATUS_SUCCESS:
    case actions.GET_RECON_STATUS_FAILURE:
      return {
        ...state,
        currentStep: action.currentStep,
        currentState: action.currentState,
        eventCode: action.eventCode,
        steps: action.steps,
        fileId: action.fileId
      }
    case actions.POST_EVENT_TRIGGER_SUCCESS:
    case actions.POST_EVENT_TRIGGER_FAILURE:
      return {
        ...state,
        triggerEventMessage: action.message
      }
    case actions.GET_RECON_FILE_DETAILS_SUCCESS:
    case actions.GET_RECON_FILE_DETAILS_FAILURE:
      return {
        ...state,
        fileDetails: action.fileDetails
      }
    case actions.GET_RECON_FILE_ROW_SUCCESS:
    case actions.GET_RECON_FILE_ROW_FAILURE:
      return {
        ...state,
        fileRows: action.fileRows
      }
    case actions.GET_RECON_LIST_SUCCESS:
    case actions.GET_RECON_LIST_FAILURE:
      return {
        ...state,
        reconList: action.reconList
      }
    case actions.GET_RECON_DETAILS_SUCCESS:
    case actions.GET_RECON_DETAILS_FAILURE:
      return {
        ...state,
        reconDetails: action.reconDetails
      }
    case actions.GET_RECON_FILES_SUCCESS:
    case actions.GET_RECON_FILES_FAILURE:
      return {
        ...state,
        reconFiles: action.reconFiles
      }
    case actions.GET_RECON_REMARKS_SUCCESS:
    case actions.GET_RECON_REMARKS_FAILURE:
      return {
        ...state,
        reconRemarks: action.reconRemarks
      }
    default:
      return state
  }
}
