import styled from 'styled-components'
import { palette } from 'styled-theme'

const env = process.env.REACT_APP_ENV?.toLowerCase()
let colorIndex = 0

if (env === 'testing') {
  colorIndex = 1
} else if (env === 'staging' || env === 'beta') {
  colorIndex = 2
}

const HeaderWrapper = styled.div`
  .badge {
    display: flex;
    justify-content: center;
    align-items: center;
    width: fit-content;
    height: 40px;
    padding: 12px;
    background: ${palette('envBasedColor', colorIndex)};
    color: white;
    border-radius: 20px;
  }
`

export default HeaderWrapper
