const actions = {
  GET_LIST_TEAM_GROUPS: 'GET_LIST_TEAM_GROUPS',
  LIST_GROUPS: 'LIST_GROUPS',
  REMOVE_USER_GROUPS: 'REMOVE_USER_GROUPS',
  GET_ALL_USERS: 'GET_ALL_USERS',
  LIST_ALL_USERS: 'LIST_ALL_USERS',
  ADD_USER_GROUP: 'ADD_USER_GROUP',
  DONT_HAVE_PERMISSION: 'DONT_HAVE_PERMISSION',
  SUCCESS_ADD_USER_GROUP: 'SUCCESS_ADD_USER_GROUP',
  FAILED_ADD_USER_GROUP: 'FAILED_ADD_USER_GROUP',
  SUCESS_REMOVE_USER: 'SUCESS_REMOVE_USER',
  FAILED_REMOVE_USER_GROUPS: 'FAILED_REMOVE_USER_GROUPS',
  RESET_REDUX_STATE: 'RESET_REDUX_STATE',
  getListGroups: () => ({
    type: actions.GET_LIST_TEAM_GROUPS
  }),
  listGroups: payload => ({
    type: actions.LIST_GROUPS,
    payload
  }),
  removeUserGroups: payload => ({
    type: actions.REMOVE_USER_GROUPS,
    payload
  }),
  successRemoveUser: payload => ({
    type: actions.SUCESS_REMOVE_USER,
    payload
  }),
  failedRemoveUserGroups: (payload) => ({
    type: actions.FAILED_REMOVE_USER_GROUPS,
    payload
  }),
  getAllUsers: () => ({
    type: actions.GET_ALL_USERS
  }),
  listAllUsers: payload => ({
    type: actions.LIST_ALL_USERS,
    payload
  }),
  addUserGroup: payload => ({
    type: actions.ADD_USER_GROUP,
    payload
  }),
  successAddUserGroup: payload => ({
    type: actions.SUCCESS_ADD_USER_GROUP,
    payload
  }),
  failedAddUserGroup: payload => ({
    type: actions.FAILED_ADD_USER_GROUP,
    payload
  }),
  resetReduxState: () => ({
    type: actions.RESET_REDUX_STATE
  })
}
export default actions
