const actions = {
  GET_IMG_PRC_LIST: 'GET_IMG_PRC_LIST',
  GET_IMG_PRC_DETAIL: 'GET_IMG_PRC_DETAIL',
  IMG_PROCESSOR_DATA: 'IMG_PROCESSOR_DATA',
  IMG_PROCESSOR_DETAIL: 'IMG_PROCESSOR_DETAIL',
  RESET_REDUX_STATE_IMG_PROCESSOR: 'RESET_REDUX_STATE_IMG_PROCESSOR',
  UPLOAD_IMG_PROCESSOR: 'UPLOAD_IMG_PROCESSOR',
  UPLOAD_IMG_PROCESSOR_STATUS: 'UPLOAD_IMG_PROCESSOR_STATUS',
  getImgProcessorLists: () => ({
    type: actions.GET_IMG_PRC_LIST
  }),
  imgProcessorData: payload => ({
    type: actions.IMG_PROCESSOR_DATA,
    payload
  }),
  getImgProcessorDetail: payload => ({
    type: actions.GET_IMG_PRC_DETAIL,
    payload
  }),
  imgProcessorDetail: payload => ({
    type: actions.IMG_PROCESSOR_DETAIL,
    payload
  }),
  uploadImgProcessor: payload => ({
    type: actions.UPLOAD_IMG_PROCESSOR,
    payload
  }),
  uploadImgProcessorStatus: payload => ({
    type: actions.UPLOAD_IMG_PROCESSOR_STATUS,
    payload
  }),
  resetReduxImgProcessor: () => ({
    type: actions.RESET_REDUX_STATE_IMG_PROCESSOR
  })
}
export default actions
