import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'
import _ from 'lodash/object'

export function * getCurrentRecon () {
  yield takeEvery(actions.GET_CURRENT_RECON_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.getCurrentRecon)
      if (res.status === 200) {
        const {
          recon_id: reconId
        } = res.data
        yield put({ type: actions.GET_CURRENT_RECON_SUCCESS, reconId })
      } else {
        yield put({ type: actions.GET_CURRENT_RECON_FAILURE, getCurrentReconStatus: 'Failed getting current recon' })
      }
    } catch (error) {
      yield put({ type: actions.GET_CURRENT_RECON_FAILURE, getCurrentReconStatus: _.get(error, 'message') })
    }
  })
}

export function * getNewReconRequest () {
  yield takeEvery(actions.POST_NEW_RECON_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.postNewRecon)
      if (res.status === 201) {
        const {
          recon_id: reconId
        } = res.data
        yield put({ type: actions.POST_NEW_RECON_SUCCESS, reconId })
      } else {
        yield put({ type: actions.POST_NEW_RECON_FAILURE, reconId: '', getCurrentReconStatus: 'Failed getting current recon' })
      }
    } catch (error) {
      yield put({ type: actions.POST_NEW_RECON_FAILURE, reconId: '', getCurrentReconStatus: _.get(error, 'message') })
    }
  })
}

export function * getReconStatusRequest () {
  yield takeEvery(actions.GET_RECON_STATUS_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.getReconStatus, payload)
      // const { params } = payload
      // const { reconId } = params
      if (res.status === 200) {
        const {
          current_step: currentStep,
          current_state: currentState,
          event_code: eventCode,
          steps,
          file_id: fileId
        } = res.data
        yield put({
          type: actions.GET_RECON_STATUS_SUCCESS,
          currentStep,
          currentState,
          eventCode,
          steps,
          fileId,
          getDataStatus: 'Success'
        })
      } else {
        yield put({ type: actions.GET_RECON_STATUS_FAILURE, reconId: '', getDataStatus: 'Failed getting recon data' })
      }
    } catch (error) {
      yield put({ type: actions.GET_RECON_STATUS_FAILURE, reconId: '', getDataStatus: _.get(error, 'message') })
    }
  })
}

export function * getTriggerEventRequest () {
  yield takeEvery(actions.POST_EVENT_TRIGGER_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.postTriggerEvent, payload)
      if (res.status === 200) {
        yield put({ type: actions.POST_EVENT_TRIGGER_SUCCESS, message: 'Success' })
        yield put({ type: actions.GET_RECON_STATUS_REQUEST, payload })
      } else {
        yield put({ type: actions.POST_EVENT_TRIGGER_FAILURE, message: 'Failed getting recon data' })
      }
    } catch (error) {
      yield put({ type: actions.POST_EVENT_TRIGGER_FAILURE, message: _.get(error, 'message') })
    }
  })
}

