export default function * rootSaga () {
  yield all([
    fork(getCurrentRecon),
    fork(getNewReconRequest),
    fork(getReconStatusRequest),
    fork(getTriggerEventRequest),
    fork(getFileDetailsRequest),
    fork(getFileRowRequest),
    fork(getReconListRequest),
    fork(getReconDetailsRequest),
    fork(getReconFilesRequest),
    fork(getReconRemarksRequest)
  ])
}
