import actions from './actions'

const initialState = {
  productDetails: [],
  message: '',
  deleteMessage: ''
}

export default function promoReducer (state = initialState, action) {
  switch (action.type) {
    case actions.PRODUCT_DETAILS:
      return {
        ...state,
        productDetails: action.data
      }
    case actions.CREATE_PRODUCT_RESULT:
      return {
        ...state,
        message: action.message
      }
    case actions.DELETE_PRODUCT_RESULT:
      return {
        ...state,
        deleteMessage: action.message
      }
    default:
      return state
  }
}
