import actions from './actions'

const initialState = {
  data: {},
  policyListDashboardStatus: ''
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.GET_POLICY_LIST_DASHBOARD_SUCCESS:
    case actions.POLICY_LIST_DASHBOARD:
      return {
        ...state,
        policyListDashboardStatus: action.policyListDashboardStatus,
        data: action.data
      }
    case actions.GET_POLICY_LIST_DASHBOARD_FAILURE:
      return {
        ...state,
        policyListDashboardStatus: action.policyListDashboardStatus,
        data: action.data
      }
    default:
      return state
  }
}
