import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../../state/teleSalesTeam/reducer'

export const TeleSalesContext = createContext()

export const TeleSalesContextProvider = (props) => {
  return (
    <TeleSalesContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </TeleSalesContext.Provider>
  )
}

export const useTeleSalesContextValue = () => useContext(TeleSalesContext)
