import React from 'react'
import { Link } from 'react-router-dom'
import { BASE_IMG_URL_S3 } from '../../helpers/constant'

const ppibrokerLogos = {
  short: `${BASE_IMG_URL_S3}/favicon.png`,
  long: `${BASE_IMG_URL_S3}/ppib_assets/common/ppib-pasarpolis.png`
}
const pasarpolisLogos = {
  short: `${BASE_IMG_URL_S3}/favicon.png`,
  long: `${BASE_IMG_URL_S3}/website/pp-logo-white-yellow-cap.png`
}

const logos = (() => {
  if (window.location.hostname.includes('ppibroker')) return ppibrokerLogos
  return pasarpolisLogos
})()

const logo = ({ collapsed }) => {
  return (
    <div className='isoLogoWrapper'>
      {collapsed
        ? (
          <div>
            <h3>
              <Link to='/'>
                <img src={logos.short} alt='' height='30px' />
              </Link>
            </h3>
          </div>
          )
        : (
          <h3>
            <Link to='/'><img src={logos.long} alt='' height='30px' /></Link>
          </h3>
          )}
    </div>
  )
}

export default logo
