import actions from './actions'

const initialState = {
  getClaimDashboardStatus: '',
  dataClaimDashboard: {},
  irisBalance: 0,
  xenditBalance: 0,
  partnerOpenClaims: [],
  operationOpenClaims: [],
  irisPPIBalance: 0,
  irisAusBalance: 0
}

export default function ClaimDashboardReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_CLAIM_DASHBOARD_STATUS:
      return {
        ...initialState
      }
    case actions.GET_CLAIM_DASHBOARD_SUCCESS:
    case actions.GET_CLAIM_DASHBOARD_FAILURE:
      return {
        ...state,
        dataClaimDashboard: action.dataClaimDashboard,
        getClaimDashboardStatus: action.getClaimDashboardStatus
      }
    case actions.GET_IRIS_BALANCE_SUCCESS:
    case actions.GET_IRIS_BALANCE_FAILURE:
      return {
        ...state,
        irisBalance: action.data
      }
    case actions.GET_IRIS_PPI_BALANCE_SUCCESS:
    case actions.GET_IRIS_PPI_BALANCE_FAILURE:
      return {
        ...state,
        irisPPIBalance: action.data
      }
    case actions.GET_XENDIT_BALANCE_SUCCESS:
    case actions.GET_XENDIT_BALANCE_FAILURE:
      return {
        ...state,
        xenditBalance: action.data
      }
    case actions.GET_IRIS_AUS_BALANCE_SUCCESS:
    case actions.GET_IRIS_AUS_BALANCE_FAILURE:
      return {
        ...state,
        irisAusBalance: action.data
      }
    case actions.GET_ALL_OPEN_CLAIMS_SUCCESS:
    case actions.GET_ALL_OPEN_CLAIMS_FAILURE:
      return {
        ...state,
        allOpenClaims: action.data
      }
    case actions.GET_PARTNER_OPEN_CLAIMS_SUCCESS:
    case actions.GET_PARTNER_OPEN_CLAIMS_FAILURE:
      return {
        ...state,
        partnerOpenClaimsMetaData: action.metaData,
        partnerOpenClaims: action.seeMore ? [...state.partnerOpenClaims, ...action.data] : action.data
      }
    case actions.GET_OPERATION_OPEN_CLAIMS_SUCCESS:
    case actions.GET_OPERATION_OPEN_CLAIMS_FAILURE:
      return {
        ...state,
        operationOpenClaimsMetaData: action.metaData,
        operationOpenClaims: action.seeMore ? [...state.operationOpenClaims, ...action.data] : action.data
      }
    case actions.GET_DAY_WISE_OPEN_CLAIMS_SUCCESS:
    case actions.GET_DAY_WISE_OPEN_CLAIMS_FAILURE:
      return {
        ...state,
        dayWiseOpenClaims: action.data
      }
    default:
      return state
  }
}
