import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function* getBrandListRequest() {
  yield takeEvery('GET_BRAND_LIST', function* (payload) {
    try {
      let res = yield call(callApi.getVehicleBrandList, payload)
      if (res) {
        yield put({ type: actions.BRAND_LIST, data: res })
      }
    } catch (e) {
      yield put({ type: actions.BRAND_LIST, data: [] })
    }
  })
}

