export function* getPostModelWithDetailsRequest() {
  yield takeEvery(actions.POST_MODEL_WITH_DETAILS, function* ({ payload }) {
    try {
      let { gocar, details, vehicleBrand, vehicleCategory, vehicleModel } = payload
      let remappedPayload = {}
      if (gocar) {
        remappedPayload = {
          type: 'gocar',
          brand_id: vehicleBrand,
          model_name: vehicleModel,
          category: vehicleCategory,
          details
        }
      } else {
        remappedPayload = {
          type: 'master',
          simas_model_id: vehicleModel,
          details
        }
      }
      let res = yield call(callApi.postModelWithDetails, remappedPayload)
      if (res === 'failed') {
        yield put({ type: actions.HANDLE_ERROR, data: 'Error creating variant' })
      } else {
        yield put({ type: actions.HANDLE_SUCCESS, data: 'Success creating variant' })
      }
    } catch (e) {
      yield put({ type: actions.HANDLE_ERROR, data: 'Error creating variant' })
    }
  })
}

export function* getUpdateModelDetailsRequest() {
  yield takeEvery(actions.UPDATE_MODEL_DETAILS, function* ({ payload }) {
    let { details, vehicleModel } = payload
    let remappedPayload = {
      details
    }
    try {
      yield call(callApi.updateModelDetails, {}, remappedPayload, { model_id: vehicleModel })
      yield put({ type: actions.HANDLE_SUCCESS, data: 'Success updating variant' })
    } catch (error) {
      let { response } = error
      if (response === undefined) yield put({ type: actions.HANDLE_ERROR, data: error.message })
      let { data } = response
      if (response === undefined) yield put({ type: actions.HANDLE_ERROR, data: error.message })
      let { message } = data
      yield put({ type: actions.HANDLE_ERROR, data: message })
    }
  })
}

export function* getResetStatusRequest() {
  yield takeEvery('RESET_STATUS', function* ({ payload }) {
    // to reset status message so it won't pop up after triggering a state update
    try {
      if (typeof payload !== 'string') return
      let statusResetTarget = actions[`HANDLE_${payload.toUpperCase()}`]
      if (statusResetTarget === undefined) return
      yield put({ type: statusResetTarget, data: '' })
    } catch (e) {
      let statusResetTarget = actions[`HANDLE_${payload.toUpperCase()}`]
      yield put({ type: statusResetTarget, data: '' })
    }
  })
}

export function* getResetRedux() {
  yield takeEvery(actions.RESET_REDUX_REQUEST, function* ({ payload }) {
    // to reset status message so it won't pop up after triggering a state update
    yield put({ type: actions.RESET_REDUX })
  })
}

export default function* rootSaga() {
  yield all([
    fork(getBrandListRequest),
    fork(getVehicleModelRequest),
    fork(getVehicleModelDetailsRequest),
    fork(getVehicleVariantRequest),
    fork(getSourceVehicleModelRequest),
    fork(getSourceVehicleModelDetailsRequest),
    fork(getVehicleVariantDetailRequest),
    fork(getPostModelWithDetailsRequest),
    fork(getUpdateModelDetailsRequest),
    fork(getResetStatusRequest),
    fork(getResetRedux)
  ])
}
