import actions from './actions'

const initialState = {
  getImgProcessorMessage: '',
  data: [],
  getImgProcessorDetailMessage: '',
  uploadImgProcessorStatus: ''
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_IMG_PROCESSOR:
      return {
        ...state,
        getImgProcessorMessage: '',
        getImgProcessorDetailMessage: '',
        uploadImgProcessorStatus: ''
      }
    case actions.IMG_PROCESSOR_DATA:
      return {
        ...state,
        data: action.data,
        getImgProcessorMessage: action.getImgProcessorMessage
      }
    case actions.IMG_PROCESSOR_DETAIL:
      return {
        ...state,
        data: action.data,
        getImgProcessorDetailMessage: action.getImgProcessorDetailMessage
      }
    case actions.UPLOAD_IMG_PROCESSOR_STATUS:
      return {
        ...state,
        uploadImgProcessorStatus: action.uploadImgProcessorStatus
      }
    default:
      return state
  }
}
