import { Result, Button } from 'antd'
import React, { Component } from 'react'
import LayoutContent from '../utility/layoutContent'
import LayoutContentWrapper from '../utility/layoutWrapper'

class ErrorBoundary extends Component {
  constructor (props) {
    super(props)
    this.state = {
      hasError: false
    }
  }

  componentDidCatch () {
    this.setState({ hasError: true })
  }

  render () {
    if (this.state.hasError) {
      return (
        <LayoutContentWrapper>
          <LayoutContent>
            {/* <h1>Whooops, We have a trouble in the system</h1> */}
            <Result
              status='500'
              title='Oops!'
              subTitle='Sorry, something went wrong. Try reloading the page, if problem persists come back again later.'
              extra={<Button type='primary' onClick={() => window.location.reload()}>Reload</Button>}
            />
          </LayoutContent>
        </LayoutContentWrapper>
      )
    }
    return this.props.children
  }
}

export default ErrorBoundary
