import { Suspense } from 'react'
import { BrowserRouter as Router, Route, Redirect, Switch } from 'react-router-dom'
import { connect } from 'react-redux'
import { ThemeProvider } from 'styled-components'

import Signin from './containers/Page/signin'
import ForgotPassword from './PasarApp/containers/ForgotPassword/forgotPassword'
import ResetPassword from './PasarApp/containers/ResetPassword/resetPassword'
import UserAuth from './PasarApp/containers/UserAuth'

import App from './containers/App/App'
import { COLORS } from './constants/colors'

import {
  ErrorContextProvider, LoaderContextProvider, GlobalContextProvider,
  ServiceContextProvider
} from '@pasarpolis/common-react-hooks'
import { ErrorContextProvider as OldErrorContextProvider } from './globalContextProvider/ErrorContext'
import { LoaderContextProvider as OldLoaderContextProvider } from './globalContextProvider/LoaderContext'
import { EBContextProvider } from './PasarApp/context/EBContext'
import { TeleSalesContextProvider } from './PasarApp/context/TeleSalesContext'
import { getHeader, getGlobalErrorMessage } from './helpers/utility'

const RestrictedRoute = ({ component: Component, isLoggedIn, ...rest }) => {
  return (
    <Route
      {...rest}
      render={props => (
        isLoggedIn
          ? (
            <Component {...props} />
            )
          : (
            <Redirect
              to={{
                pathname: '/signin',
                state: { from: props.location }
              }}
            />
            )
      )}
    />
  )
}

const PublicRoutes = ({ isLoggedIn }) => {
  return (
    <Router>
      <GlobalContextProvider>
        <LoaderContextProvider>
          <ErrorContextProvider>
            <ServiceContextProvider
              headers={getHeader()}
              getGlobalErrorMessages={(status, error) => getGlobalErrorMessage(status, error && error.error_code)}
            >
              <TeleSalesContextProvider>
                <EBContextProvider>
                  <OldLoaderContextProvider>
                    <OldErrorContextProvider>
                      <Suspense fallback={<div />}>
                        <ThemeProvider theme={COLORS}>
                          <Switch>
                            <Route
                              exact
                              path='/signin'
                              component={Signin}
                            />
                            <Route
                              exact
                              path='/forgot-password'
                              component={ForgotPassword}
                            />
                            <Route
                              exact
                              path='/reset_password/:uuid'
                              component={ResetPassword}
                            />
                            <Route
                              exact
                              path='/auth'
                              component={UserAuth}
                            />
                            <RestrictedRoute
                              path='/'
                              component={App}
                              isLoggedIn={isLoggedIn}
                            />
                          </Switch>
                        </ThemeProvider>
                      </Suspense>
                    </OldErrorContextProvider>
                  </OldLoaderContextProvider>
                </EBContextProvider>
              </TeleSalesContextProvider>
            </ServiceContextProvider>
          </ErrorContextProvider>
        </LoaderContextProvider>
      </GlobalContextProvider>
    </Router>
  )
}

export default connect(state => ({
  isLoggedIn: !!state.Auth.idToken
}))(PublicRoutes)
