import teleSalesTeam from '../../../request/urls/teleSales'

const actions = {
  RESET_TELESALES_TEAM: 'RESET_TELESALES_TEAM',
  PROVINCE_LIST_REQUEST: 'PROVINCE_LIST_REQUEST',
  PROVINCE_LIST: 'PROVINCE_LIST',
  BIRTH_PLACE_REQUEST: 'BIRTH_PLACE_REQUEST',
  BIRTH_PLACE: 'BIRTH_PLACE',
  CITY_LIST_REQUEST: 'CITY_LIST_REQUEST',
  CITY_LIST: 'CITY_LIST',
  BUKALAPAK_QUOTE_REQUEST: 'BUKALAPAK_QUOTE_REQUEST',
  BUKALAPAK_QUOTE: 'BUKALAPAK_QUOTE',
  resetState: (fields = []) => ({
    type: actions.RESET_TELESALES_TEAM,
    payload: fields
  }),
  getProvinceList: () => {
    return {
      type: actions.PROVINCE_LIST_REQUEST,
      payload: {
        method: 'authGet',
        url: teleSalesTeam.provinceList
      }
    }
  },
  getCityList: (payload) => ({
    type: actions.CITY_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'authGet',
      url: teleSalesTeam.cityList
    }
  }),
  birthCityList: () => ({
    type: actions.BIRTH_PLACE_REQUEST,
    payload: {
      method: 'authGet',
      url: teleSalesTeam.birthCityList
    }
  }),
  createQuote: (payload) => ({
    type: actions.BUKALAPAK_QUOTE_REQUEST,
    payload: {
      ...payload,
      method: 'authPost',
      url: teleSalesTeam.createQuote
    }
  })
}
export default actions
