import React from 'react'
import HeaderWrapper from './style'

const EnvBadge = ({ env, colorCode }) => {
  if (env === 'production' || !env) {
    return null
  }

  return (
    <HeaderWrapper colorCode={colorCode}>
      <div className='badge'>
        <b>{env?.toUpperCase()}</b>
      </div>
    </HeaderWrapper>
  )
}

export default EnvBadge
