import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const MerchantContext = createContext()

export const MerchantContextProvider = (props) => {
  return (
    <MerchantContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </MerchantContext.Provider>
  )
}

export const useMerchantContextValue = () => useContext(MerchantContext)
