import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import _ from 'lodash/object'
import callApi from '../../../helpers/callApi'

export function * listMessages () {
  yield takeEvery(actions.WHATSAPP_LIST_DATA_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(callApi.listMessages, {
        query: _.get(payload, 'query', ''),
        page: _.get(payload, 'page', 1),
        per_page: 50
      })
      if (res.status === 201 || res.status === 200) {
        yield put({
          type: actions.WHATSAPP_LIST_DATA_SUCCESS,
          listDataDetail: res.data,
          isIntervalUpdate: _.get(payload, 'isIntervalUpdate', false),
          listMessage: 'success'
        })
      } else {
        yield put({ type: actions.WHATSAPP_LIST_DATA_FAILURE, listDataDetail: [], listMessage: 'error' })
      }
    } catch (e) {
      yield put({ type: actions.WHATSAPP_LIST_DATA_FAILURE, listDataDetail: [], listMessage: e.message })
    }
  })
}

export function * IndividualDetailMessage () {
  yield takeEvery(actions.WHATSAPP_DETAIL_MESSAGE_REQUEST, function * (payload) {
    try {
      let res = yield call(callApi.individualMessage, payload)
      if (res.status === 201 || res.status === 200) {
        yield put({ type: actions.WHATSAPP_DETAIL_MESSAGE_SUCCESS, individualDataDetail: res.data, individualMessage: 'success' })
      } else {
        yield put({ type: actions.WHATSAPP_DETAIL_MESSAGE_FAILURE, individualDataDetail: [], individualMessage: 'error' })
      }
    } catch (e) {
      yield put({ type: actions.WHATSAPP_DETAIL_MESSAGE_FAILURE, individualDataDetail: [], individualMessage: e.message })
    }
  })
}

