export function * uploadfiles () {
  yield takeEvery(actions.UPLOAD_FILES_REQUEST, function * (payload) {
    try {
      let res = yield call(callApi.sendDocsToUser, payload)
      if (res.status === 201 || res.status === 200) {
        yield put({ type: actions.UPLOAD_FILES_SUCCESS, url: res.data.url, sendUploadMessage: 'success' })
      } else {
        yield put({ type: actions.UPLOAD_FILES_FAILURE, url: [], sendUploadMessage: 'error' })
      }
    } catch (e) {
      yield put({ type: actions.UPLOAD_FILES_FAILURE, url: [], sendUploadMessage: e.message })
    }
  })
}
export default function * rootSaga () {
  yield all([
    fork(listMessages),
    fork(IndividualDetailMessage),
    fork(readWhatsappStatus),
    fork(sendWhatsappMessage),
    fork(uploadfiles)
  ])
}
