import React, { Component } from 'react'
import { connect } from 'react-redux'
import clone from 'clone'
import { Link } from 'react-router-dom'
import { Layout } from 'antd'
import Scrollbars from '../../components/utility/customScrollBar'
import Menu from '../../components/uielements/menu'
import SidebarWrapper from './sidebar.style'
import appActions from '../../redux/app/actions'
import Logo from '../../components/utility/logo'
import themes from '../../settings/themes'
import { themeConfig } from '../../settings'
import authActions from '../../redux/auth/actions'
import { routes } from '../App/AppRouter'
import Cookies from 'universal-cookie'

const { getProfileDetail } = authActions

const { Sider } = Layout
const SubMenu = Menu.SubMenu

const {
  toggleOpenDrawer,
  changeOpenKeys,
  changeCurrent,
  toggleCollapsed
} = appActions

const stripTrailingSlash = str => {
  if (str.substr(-1) === '/') {
    return str.substr(0, str.length - 1)
  }
  return str
}

const cookies = new Cookies()

class Sidebar extends Component {
  constructor (props) {
    super(props)
    this.handleClick = this.handleClick.bind(this)
    this.handleOnOpenChange = this.handleOnOpenChange.bind(this)
    this.state = {
      selectedMenu: ''
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { location } = nextProps
    const { pathname } = location
    if (pathname) {
      this.setState({
        selectedMenu: pathname ? pathname.split('/')[1] : ''
      })
    }
  }

  handleClick (e) {
    this.props.changeCurrent([e.key])
    if (this.props.app.view === 'MobileView') {
      setTimeout(() => {
        this.props.toggleCollapsed()
        this.props.toggleOpenDrawer()
      }, 100)
    }
  }

  handleOnOpenChange (newOpenKeys) {
    const { app, changeOpenKeys } = this.props
    const latestOpenKey = newOpenKeys.find(
      key => !(app.openKeys.indexOf(key) > -1)
    )
    const latestCloseKey = app.openKeys.find(
      key => !(newOpenKeys.indexOf(key) > -1)
    )
    let nextOpenKeys = []
    if (latestOpenKey) {
      nextOpenKeys = this.getAncestorKeys(latestOpenKey).concat(latestOpenKey)
    }
    if (latestCloseKey) {
      nextOpenKeys = this.getAncestorKeys(latestCloseKey)
    }
    changeOpenKeys(nextOpenKeys)
  }

  getAncestorKeys = key => {
    const map = {
      sub3: ['sub2']
    }
    return map[key] || []
  };

  onChangeMenu (key) {
    cookies.set('menu', key.split('/')[0], { path: '/' })
    cookies.remove('querySearch')
    cookies.remove('querySearchUploadDetail')
    this.setState({ selectedMenu: key })
  }

  render () {
    const { app, toggleOpenDrawer, permissions } = this.props
    const { selectedMenu } = this.state
    const collapsed = clone(app.collapsed) && !clone(app.openDrawer)
    const { openDrawer } = app
    const mode = collapsed === true ? 'vertical' : 'inline'
    const onMouseEnter = event => {
      if (openDrawer === false) {
        toggleOpenDrawer()
      }
    }
    const onMouseLeave = () => {
      if (openDrawer === true) {
        toggleOpenDrawer()
      }
    }
    const customizedTheme = themes[themeConfig.theme]
    const submenuColor = {
      color: customizedTheme.textColor
    }
    const submenuStyle = {
      backgroundColor: 'rgba(0,0,0,0.3)',
      color: customizedTheme.textColor
    }
    const url = stripTrailingSlash(this.props.url)
    let selectedMenuDefault = []
    if (cookies.get('menu') !== undefined) {
      const test = /gocar/g.test(cookies.get('menu'))
      if (test) {
        selectedMenuDefault = ['Gocar']
      } else {
        selectedMenuDefault = [cookies.get('menu')]
      }
    }
    return (
      <SidebarWrapper>
        <Sider
          trigger={null}
          collapsible
          collapsed={collapsed}
          width={240}
          className='isomorphicSidebar'
          onMouseEnter={onMouseEnter}
          onMouseLeave={onMouseLeave}
        >
          <Logo collapsed={collapsed} />
          <Scrollbars style={{ height: 'calc(100vh - 70px)' }}>
            <Menu
              onClick={this.handleClick}
              theme='dark'
              className='isoDashboardMenu'
              mode={mode}
              selectedKeys={[selectedMenu]}
              defaultOpenKeys={selectedMenuDefault}
              onOpenChange={this.handleOnOpenChange}
            >
              {
                routes.map(route => {
                  const { title, path, permission, component, icon, subPaths } = route
                  if ((path === '' && !title) || (permission !== undefined && !permissions.includes(permission))) return ('')
                  if (component) {
                    return (
                      <Menu.Item key={path} onClick={() => this.onChangeMenu(path)}>
                        <Link to={`${url}/${path}`}>
                          <span className='isoMenuHolder' style={submenuColor}>
                            <i className={`${icon}`} />
                            <span className='nav-text'>
                              {title}
                            </span>
                          </span>
                        </Link>
                      </Menu.Item>
                    )
                  } else {
                    return (
                      <SubMenu
                        key={title}
                        title={
                          <span className='isoMenuHolder'>
                            <i className={`${icon}`} />
                            <span className='nav-text'>
                              {title}
                            </span>
                          </span>
                        }
                        style={{ color: 'rgba(255, 255, 255, 0.65)' }}
                      >
                        {subPaths.map(subPath => {
                          const { title, path, permission, subMenu } = subPath
                          if (subMenu && permissions.includes(permission)) {
                            return (
                              <Menu.Item style={submenuStyle} key={`${route.path}${path}`} onClick={() => this.onChangeMenu(`${route.path}${path}`)}>
                                <Link to={`${url}/${route.path}${path}`}>{title}</Link>
                              </Menu.Item>
                            )
                          } else {
                            return ''
                          }
                        })}
                      </SubMenu>
                    )
                  }
                })
              }
            </Menu>
          </Scrollbars>
        </Sider>
      </SidebarWrapper>
    )
  }
}

export default connect(
  state => ({
    groupLists: state.Team,
    app: state.App,
    height: state.App.height,
    dataProfile: state.Auth.profile
  }),
  { toggleOpenDrawer, changeOpenKeys, changeCurrent, toggleCollapsed, getProfileDetail }
)(Sidebar)
