import { getHeaderUploadFile } from '../../../../../helpers/utility'
import {
  addonsListApi, addonsPremiumCalcApi, applicationFilterApi, getAgentProviderListApi, getProductAddonsApi,
  uploadPolicyFileApi, agentPackageListApi
} from '../../config/urls'

export const AGENT_ACTIONS = {
  GET_PRODUCT_ADDONS_REQUEST: 'GET_PRODUCT_ADDONS_REQUEST',
  GET_PRODUCT_ADDONS: 'GET_PRODUCT_ADDONS',

  GET_ADDONS_REQUEST: 'GET_ADDONS_REQUEST',
  GET_ADDONS: 'GET_ADDONS',

  GET_ADDONS_PREMIUM_REQUEST: 'GET_ADDONS_PREMIUM_REQUEST',
  GET_ADDONS_PREMIUM: 'GET_ADDONS_PREMIUM',

  UPLOAD_FILE_REQUEST: 'UPLOAD_FILE_REQUEST',
  UPLOAD_FILE: 'UPLOAD_FILE',

  GET_PROVIDER_LIST_REQUEST: 'GET_PROVIDER_LIST_REQUEST',
  GET_PROVIDER_LIST: 'GET_PROVIDER_LIST',

  GET_AGENT_PACKAGE_LIST_REQUEST: 'GET_AGENT_PACKAGE_LIST_REQUEST',
  GET_AGENT_PACKAGE_LIST: 'GET_AGENT_PACKAGE_LIST',

  GET_APPLICATION_FILTER_REQUEST: 'GET_APPLICATION_FILTER_REQUEST',
  GET_APPLICATION_FILTER: 'GET_APPLICATION_FILTER',

  RESET_AGENT_STORE: 'RESET_AGENT_STORE'
}

export const updateAgentStore = (payload) => ({
  type: AGENT_ACTIONS.RESET_AGENT_STORE,
  payload
})

export const getProductAddons = (payload) => ({
  type: AGENT_ACTIONS.GET_PRODUCT_ADDONS_REQUEST,
  payload: {
    url: getProductAddonsApi(payload.productCode),
    method: 'GET'
  }
})

export const getApplicationFilter = () => ({
  type: AGENT_ACTIONS.GET_APPLICATION_FILTER_REQUEST,
  payload: {
    url: applicationFilterApi,
    method: 'GET'
  }
})

export const getAddonsList = (payload) => ({
  type: AGENT_ACTIONS.GET_ADDONS_REQUEST,
  payload: {
    ...payload,
    url: addonsListApi(payload.productCode),
    method: 'POST'
  }
})

export const getAddonPremium = (payload) => ({
  type: AGENT_ACTIONS.GET_ADDONS_PREMIUM_REQUEST,
  payload: {
    ...payload,
    url: addonsPremiumCalcApi(payload.productCode),
    method: 'POST'
  }
})

export const uploadFile = (payload) => ({
  type: AGENT_ACTIONS.UPLOAD_FILE_REQUEST,
  payload: {
    ...payload,
    headers: getHeaderUploadFile(),
    url: uploadPolicyFileApi,
    method: 'POST'
  }
})

export const getProviderList = (payload) => ({
  type: AGENT_ACTIONS.GET_PROVIDER_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: getAgentProviderListApi
  }
})

export const getPackageList = (payload) => ({
  type: AGENT_ACTIONS.GET_AGENT_PACKAGE_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: agentPackageListApi
  }
})
