import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function * getListGroupsRequest () {
  yield takeEvery('GET_LIST_GROUPS', function * (payload) {
    try {
      let res = yield call(callApi.getListGroups, payload)
      if (res.status === 200) {
        yield put({ type: actions.LIST_GROUPS, groupLists: res.data, messageGroupList: 'success' })
      } else {
        yield put({ type: actions.FAILED_GET_LIST_GROUPS, messageGroupList: 'Gagal mengambil data group' })
      }
    } catch (error) {
      yield put({ type: actions.FAILED_GET_LIST_GROUPS, messageGroupList: error.message })
    }
  })
}

export default function * rootSaga () {
  yield all([
    fork(getListGroupsRequest)
  ])
}
