const actions = {
  GET_POLICY_LIST_DASHBOARD_REQUEST: 'GET_POLICY_LIST_DASHBOARD_REQUEST',
  GET_POLICY_LIST_DASHBOARD_SUCCESS: 'GET_POLICY_LIST_DASHBOARD_SUCCESS',
  GET_POLICY_LIST_DASHBOARD_FAILURE: 'GET_POLICY_LIST_DASHBOARD_FAILURE',
  POLICY_LIST_DASHBOARD: 'POLICY_LIST_DASHBOARD',
  FAILED_FETCH_POLICY_LIST_DASHBOARD: 'FAILED_FETCH_POLICY_LIST_DASHBOARD',
  getPolicyListDashboard: payload => ({
    type: actions.GET_POLICY_LIST_DASHBOARD_REQUEST,
    payload
  }),
  policyListDashboard: payload => ({
    type: actions.POLICY_LIST_DASHBOARD,
    payload
  }),
  failedFetchPolicyListDashboard: payload => ({
    type: actions.GET_POLICY_LIST_DASHBOARD_FAILURE,
    payload
  })
}
export default actions
