const exceptionsHandler = (e = {}) => {
  let data = ''
  switch (true) {
    case e.response !== undefined:
      data = e.response
      break
    case e.message !== undefined:
      data = e.message
      break
    case e.error !== undefined:
      data = e.error
      break
    case e.detail !== undefined:
      data = e.detail
      break
    default:
      data = 'Ooops, something went terribly wrong!'
      break
  }
  if (typeof data === 'string' && data.includes('<!DOCTYPE html>')) {
    data = 'Something went wrong! Please try again'
  } else if (Array.isArray(data) && !!data[0]) {
    data = data.toString()
  }
  return data
}

export default exceptionsHandler
