const routes = [
  {
    path: '',
    component: lazy(() => retry(() => import('../../PasarApp/containers/DefaultPage'))),
    icon: '',
    permission: '',
    subPaths: []
  },
  ...DashboardRouter,
  {
    path: 'profile',
    component: lazy(() => retry(() => import('../../PasarApp/containers/ProfilePage'))),
    icon: '',
    permission: '',
    subPaths: []
  },
  ...PolicyListRouter,
  ...ClaimDashboard,
  ...ClaimRouter,
  ...AgentRouter,
  ...(process.env.REACT_APP_VIETNAM === 'true' ? AgentVietRouter : []),
  ...TapInsureRouter,
  ...EBRouter,
  ...GocarRouter,
  ...Recon,
  ...CustomerSupport,
  ...CustomerRouter,
  ...FeedbackRouter,
  ...TeleSalesTeam,
  // ...Shipping,
  // ...TransactionRouter,
  ...UmbrellaRouter,
  ...ProfileRouter,
  // ...VehicleRouter,
  ...PartnerRouter,
  ...ReportingConfigRouter,
  ...ProductConfig,
  ...ProviderRouter,
  ...PresetRouter,
  ...Webhook,
  ...TeamRouter,
  ...PartnerFileTemplateRouter,
  // ...ProductList,
  // ...ImageProcessor,
  ...Notifications,
  ...DocumentService,
  ...Merchant,
  ...Campaign,
  ...Translations,
  ...FlightDelay,
  ...DemoRouter,
  ...StaticOtp,
  ...AuditLog,
  ...Deposit,
  ...DataCollections,
  ...Ava,
  ...DataCatalog,
  // ...GoRideRouter,
  // ...ExperimentalRouter
  ...ServiceCenter,
  ...HardcopyRouter
]

class AppRouter extends Component {
  constructor (props) {
    super(props)
    this.state = {
      defaultRoute: '/'
    }
  }

  componentDidMount () {
    const { permissions } = this.props
    const { defaultRoute: currentDefaultRoute } = this.state
    let defaultRoute = ''
    if (permissions.includes('ops.view_dashboard')) {
      defaultRoute = '/dashboard'
    } else {
      defaultRoute = '/profile'
    }

    if (defaultRoute !== currentDefaultRoute) {
      this.setState({
        defaultRoute: defaultRoute
      })
    }
  }

  renderTheChildren = (permission, component, props, defaultRoute) => {
    const { permissions } = this.props
    if (permissions.includes(permission)) {
      return React.createElement(component, { ...props, permissions })
    } else if (permission === '') {
      return React.createElement(component, { ...props, permissions, defaultRoute })
    } else {
      return <Redirect to='/' />
    }
  }

  render () {
    const { url, style, permissions } = this.props
    const { defaultRoute } = this.state
    return (
      <ProgressBarComponent>
        <ErrorBoundary>
          <div style={style}>
            <Switch>
              {routes.map(singleRoute => {
                const { path, exact, permission, component, subPaths, context: ContextProvider } = singleRoute
                const route = component
                  ? (
                    <Route
                      exact={exact !== false}
                      key={path}
                      path={`${url}${path}`}
                      render={(props) => {
                        if (permission !== '' && permissions.includes(permission)) {
                          if (!component) {
                            let defaultSubPath = subPaths.find(x => permissions.includes(x.permission))
                            // if user has no access to any subpaths, redirect to '/' path
                            defaultSubPath = defaultSubPath === undefined ? '/' : `${path}${defaultSubPath.path}`
                            return <Redirect to={defaultSubPath} />
                          } else {
                            return React.createElement(component, { ...props, permissions })
                          }
                        } else if (permission === '') {
                          return React.createElement(component, { ...props, permissions, defaultRoute })
                        } else {
                          return <Redirect to='/' />
                        }
                      }}
                    />
                    )
                  : []
                const subRoutes = subPaths.map(subRoute => {
                  const { path, exact, permission, component } = subRoute
                  return (
                    <Route
                      exact={exact !== false}
                      key={path}
                      path={`${url}${singleRoute.path}${path}`}
                      render={(props) => {
                        if (ContextProvider) {
                          return (
                            <ContextProvider>
                              {this.renderTheChildren(permission, component, props, defaultRoute)}
                            </ContextProvider>
                          )
                        }
                        return this.renderTheChildren(permission, component, props, defaultRoute)
                      }}
                    />
                  )
                })
                return [route, subRoutes]
              })}
              <Route component={NotFound} />
            </Switch>
          </div>
        </ErrorBoundary>
      </ProgressBarComponent>
    )
  }
}
export { routes }
export default AppRouter
