import actions from './actions'

const initialState = {
  getCreateDelayStatus: ''
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_DELAY:
      return {
        ...state,
        getCreateDelayStatus: ''
      }
    case actions.CREATE_DELAY_SUCCESS:
      return {
        ...state,
        getCreateDelayStatus: action.getCreateDelayStatus
      }
    case actions.CREATE_DELAY_FAILED:
      return {
        ...state,
        getCreateDelayStatus: action.getCreateDelayStatus
      }
    default:
      return state
  }
}
