import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import { saveAs } from 'file-saver'

import actions from './actions'
import callApi from '../../../helpers/callApi'
import authPostFormData from '../../../request/methods/authPostFormData'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import authGetBlob from '../../../request/methods/authGetBlob'
import authPostBlob from '../../../request/methods/authPostBlob'
import gocarUrls from '../../../request/urls/gocar'
import urls from '../../../config/urls'

const configUrl = urls.url

export function* getGocarDataRequest() {
  yield takeEvery(actions.GET_GOCAR_SIMPLE_DATA_REQUEST, function* ({ payload }) {
    try {
      const res = yield call(callApi.getGocarSimpleData, payload)
      if (res.status === 200) {
        yield put({ type: actions.GET_GOCAR_SIMPLE_DATA_SUCCESS, data: res.data, getDataStatus: '' })
      } else {
        yield put({ type: actions.GET_GOCAR_SIMPLE_DATA_FAILURE, getDataStatus: 'Gagal mengambil data gocar simple' })
      }
    } catch (error) {
      yield put({ type: actions.GET_GOCAR_SIMPLE_DATA_FAILURE, getDataStatus: error.message })
    }
  })
}

