export function* updatePolicyRequest() {
  yield takeEvery('UPDATE_POLICY_NUMBER', function* (payload) {
    try {
      const res = yield call(callApi.updatePolicyNumber, payload)
      if (res.status === 200) {
        if (payload.payload.identifier === 'simple') {
          yield put({ type: actions.GET_GOCAR_SIMPLE_DATA_REQUEST })
        } else {
          yield put({ type: actions.GET_GOCAR_KOMPLIT_DATA })
        }
      } else {
        yield put({ type: actions.FAILED_UPDATE_POLICY_NUMBER, updatePolicyStatus: 'failed' })
      }
    } catch (error) {
      yield put({ type: actions.FAILED_UPDATE_POLICY_NUMBER, updatePolicyStatus: error.message })
    }
  })
}

