export function* getGocarTemplateRequest() {
  yield takeEvery(actions.GET_GOCAR_TEMPLATE_SAMPLE_REQUEST, function* ({ payload = { params: {} } }) {
    try {
      const res = yield call(authGetBlob, { ...payload, url: gocarUrls.downloadTemplate })
      const { params } = payload
      const { templateId } = params
      if (res.status === 200) {
        yield saveAs(res.data, `${templateId}.xlsx`)
        yield put({ type: actions.GET_GOCAR_TEMPLATE_SAMPLE_SUCCESS, message: res.data.message || 'success' })
      } else {
        yield put({ type: actions.GET_GOCAR_TEMPLATE_SAMPLE_FAILURE, message: (res.data || {}).message || 'error' })
      }
    } catch (e) {
      yield put({ type: actions.GET_GOCAR_TEMPLATE_SAMPLE_FAILURE, message: (e.data || {}).message || 'error' })
    }
  })
}

export function* downloadRows() {
  yield takeEvery(actions.DOWNLOAD_ROWS_REQUEST, function* ({ payload }) {
    try {
      const res = yield call(authPostBlob, { ...payload, url: gocarUrls.downloadRows })
      const { params, body } = payload
      const { templateId } = params
      if (res.status === 200) {
        yield saveAs(res.data, `${templateId}-${body.type}.xlsx`)
        yield put({ type: actions.DOWNLOAD_ROWS_SUCCESS, message: res.data.message || 'success' })
      } else {
        yield put({ type: actions.DOWNLOAD_ROWS_FAILURE, message: (res.data || {}).message || 'error' })
      }
    } catch (e) {
      yield put({ type: actions.DOWNLOAD_ROWS_FAILURE, message: (e.data || {}).message || 'error' })
    }
  })
}

