export default function* rootSaga() {
  yield all([
    fork(getGocarDataRequest),
    fork(getGocarKomplitDataRequest),
    fork(updatePolicyRequest),
    fork(uploadFileUpdatePolicy),
    fork(uploadFileUpdatePayment),
    fork(getUploadList),
    fork(getUploadListDetail),
    fork(getGocarDetails),
    fork(getPaymentDetails),
    fork(postCancelPolicyDetails),
    fork(postTerminatePolicy),
    fork(getTransactionList),
    fork(getSuspendedList),
    fork(sendReportRequest),
    fork(getGocarFileTemplates),
    fork(uploadGocarBulkExcel),
    fork(getGocarTemplateRequest),
    fork(downloadRows),
    fork(checkMissingPayment),
    fork(addPayment),
    fork(sendGocarReport)
  ])
}
