import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import exceptionHandlerSanitizer from '../../../middleware/exceptions'
import authGet from '../../../request/methods/authGet'
import masterDataUrls from '../../../request/urls/masterdata'
import _ from 'lodash/object'

export function * getMasterData () {
  yield takeEvery(actions.GET_MASTER_DATA_REQUEST, function * ({ payload }) {
    let key = _.get(payload, 'extra.key', 'data')
    try {
      let res = yield call(authGet, { ...payload, url: masterDataUrls.getMasterDataUrl })
      if (res.status === 200) {
        // if payload has extra attribute with key defined, use that key to store data, else default to 'data'
        yield put({
          type: actions.GET_MASTER_DATA_SUCCESS,
          target: { [key]: res.data },
          message: 'Success getting master data'
        })
      } else {
        let message = exceptionHandlerSanitizer(res.data)
        yield put({ type: actions.GET_MASTER_DATA_FAILURE, target: { [key]: undefined }, message })
      }
    } catch (e) {
      yield put({ type: actions.GET_MASTER_DATA_FAILURE, message: 'Error while getting master data' })
    }
  })
}

export default function * rootSaga () {
  yield all([
    fork(getMasterData)
  ])
}
