import actions from './actions'

const initialState = {
  data: [],
  dataDetailRevenue: [],
  dataRevenueShareContract: [],
  dataRevenueShareMetaFrequency: [],
  getRevenueShareMetaStatus: '',
  getDetailRevenueShareMetaStatus: '',
  getRevenueShareContractStatus: '',
  getRevenueShareMetaFrequencyStatus: '',
  addRevenueShareMetaStatus: '',
  addRevenueShareContractStatus: '',
  addFrequencyTriggerStatus: '',
  dataReports: [],
  reportRevenueMetadata: {},
  getReportRevenueStatus: '',
  dataDetailReports: [],
  getReportDetailStatus: '',
  generateManualReportStatus: '',
  editRevenueShareMetaStatus: '',
  editRevenueShareContractStatus: '',
  editFrequencyTriggerStatus: '',
  getTimezonesStatus: '',
  getAutoReconListMessage: '',
  postStartReconMessage: '',
  signedUrl: [],
  reconStatus: {},
  reconResolverListData: {},
  reconResolverListDataMessage: undefined,
  reconResolverDetail: {},
  reconResolverDetailMessage: undefined,
  reconResolverUpdateData: {},
  reconResolverUpdateDataMessage: undefined,
  reconresolverfeedbackSubmitMessage: undefined,
  reconResolverPostFeedbackSubmitMessage: undefined,
  reconResolverPostFeedbackSubmit: {},
  searchReconData: [],
  searchReconMessage: undefined
}

export default function reconReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_RECON:

      if (action.payload && Array.isArray(action.payload)) {
        const stateToBeReset = {}
        action.payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    case actions.REVENUE_SHARE_META_DATA:
      return {
        ...state,
        data: action.data,
        getRevenueShareMetaStatus: action.getRevenueShareMetaStatus
      }
    case actions.DETAIL_REVENUE_SHARE_META_DATA:
      return {
        ...state,
        dataDetailRevenue: action.data,
        getDetailRevenueShareMetaStatus: action.getDetailRevenueShareMetaStatus
      }
    case actions.REVENUE_SHARE_CONTRACT:
      return {
        ...state,
        dataRevenueShareContract: action.data,
        getRevenueShareContractStatus: action.getRevenueShareContractStatus
      }
    case actions.REVENUE_SHARE_META_FREQUENCY:
      return {
        ...state,
        dataRevenueShareMetaFrequency: action.data,
        getRevenueShareMetaFrequencyStatus: action.getRevenueShareMetaFrequencyStatus
      }
    case actions.ADD_REVENUE_SHARE_META_STATUS:
      return {
        ...state,
        addRevenueShareMetaStatus: action.addRevenueShareMetaStatus
      }
    case actions.ADD_REVENUE_SHARE_CONTRACT_STATUS:
      return {
        ...state,
        addRevenueShareContractStatus: action.addRevenueShareContractStatus
      }
    case actions.ADD_FREQUENCY_TRIGGER_STATUS:
      return {
        ...state,
        addFrequencyTriggerStatus: action.addFrequencyTriggerStatus
      }
    case actions.GET_REPORTS_REVENUE_SUCCESS:
    case actions.GET_REPORTS_REVENUE_FAILURE:
      return {
        ...state,
        dataReports: action.data,
        reportRevenueMetadata: action.reportRevenueMetadata,
        getReportRevenueStatus: action.getReportRevenueStatus
      }
    case actions.GET_REPORT_DETAIL_STATUS:
      return {
        ...state,
        dataDetailReports: action.data,
        getReportDetailStatus: action.getReportDetailStatus
      }
    case actions.GENERATE_MANUAL_REPORT_STATUS:
      return {
        ...state,
        generateManualReportStatus: action.generateManualReportStatus
      }
    case actions.EDIT_REVENUE_SHARE_META_STATUS:
      return {
        ...state,
        editRevenueShareMetaStatus: action.editRevenueShareMetaStatus
      }
    case actions.EDIT_REVENUE_SHARE_CONTRACT_STATUS:
      return {
        ...state,
        editRevenueShareContractStatus: action.editRevenueShareContractStatus
      }
    case actions.EDIT_FREQUENCY_TRIGGER_STATUS:
      return {
        ...state,
        editFrequencyTriggerStatus: action.editFrequencyTriggerStatus
      }
    case actions.GET_TIMEZONES_STATUS:
      return {
        ...state,
        dataTimezones: action.data,
        getTimezonesStatus: action.getTimezonesStatus
      }
    case actions.GET_AUTO_RECON_LIST_SUCCESS:
    case actions.GET_AUTO_RECON_LIST_FAILURE:
      return {
        ...state,
        data: action.data,
        reconMetadata: action.metadata,
        gerAutoReconListMessage: action.message
      }
    case actions.GET_AUTO_RECON_DETAILS_SUCCESS:
    case actions.GET_AUTO_RECON_DETAILS_FAILURE:
      return {
        ...state,
        reconDetails: action.data,
        getAutoReconDetailsMessage: action.message
      }
    case actions.POST_CREATE_RECON_SUCCESS:
    case actions.POST_CREATE_RECON_FAILURE:
      return {
        ...state,
        createRecon: action.data,
        postCreateReconMessage: action.message
      }
    case actions.POST_START_RECON_SUCCESS:
    case actions.POST_START_RECON_FAILURE:
      return {
        ...state,
        postStartReconMessage: action.message
      }
    case actions.UPLOAD_RECON_FILES_SUCCESS:
    case actions.UPLOAD_RECON_FILES_FAILURE:
      return {
        ...state,
        uploadReconUrl: action.url,
        uploadReconName: action.name,
        uploadReconMessage: action.sendUploadMessage
      }
    case actions.GENERATE_SIGNED_URL_SUCCESS:
    case actions.GENERATE_SIGNED_URL_FAILURE:
      return {
        ...state,
        signedUrlStatus: action.message,
        signedUrl: action.data
      }
    case actions.RECON_FILE_UPLOAD_FAILURE:
    case actions.RECON_FILE_UPLOAD_SUCCESS:
      return {
        ...state,
        failedFileData: action.fileData
      }
    case actions.GET_FILE_TEMPLATES_SUCCESS:
    case actions.GET_FILE_TEMPLATES_FAILURE:
      return {
        ...state,
        fileTemplates: action.data
      }
    case actions.GET_RECON_DETAIL_STATUS_SUCCESS:
    case actions.GET_RECON_DETAIL_STATUS_FAILURE:
      return {
        ...state,
        reconStatus: action.data
      }
    case actions.DOWNLOAD_REPORT_SUCCESS:
    case actions.DOWNLOAD_REPORT_FAILURE:
      return {
        ...state,
        downloadReport: action.data
      }
    case actions.RERUN_RECON_SUCCESS:
    case actions.RERUN_RECON_FAILURE:
      return {
        ...state,
        rerunReconStatus: action.message
      }
    case actions.RECON_RESOLVER_LIST_SUCCESS:
    case actions.RECON_RESOLVER_LIST_FAILURE:
      return {
        ...state,
        reconResolverListData: action.data,
        reconResolverListDataMessage: action.message
      }
    case actions.RECON_RESOLVER_DETAIL_FAILURE:
    case actions.RECON_RESOLVER_DETAIL_SUCCESS:
      return {
        ...state,
        reconResolverDetailData: action.data,
        reconResolverDetailDataMessage: action.message
      }
    case actions.RECON_RESOLVER_UPDATE_SUCCESS:
    case actions.RECON_RESOLVER_UPDATE_FAILURE:
      return {
        ...state,
        reconResolverUpdateData: action.data,
        reconResolverUpdateDataMessage: action.message
      }
    case actions.RECON_RESOLVER_UPDATE_ALL_SUCCESS:
    case actions.RECON_RESOLVER_UPDATE_ALL_FAILURE:
      return {
        ...state,
        reconResolverUpdateAllData: action.data,
        reconResolverUpdateAllDataMessage: action.message,
        reconResolverUpdateAllDataStatus: action.status
      }
    case actions.POST_RECON_SUBMIT_FEEDBACK_SUCCESS:
    case actions.POST_RECON_SUBMIT_FEEDBACK_FAILURE:
      return {
        ...state,
        reconresolverfeedbackSubmitMessage: action.message
      }
    case actions.POST_RECON_FEEDBACK_SUCCESS:
    case actions.POST_RECON_FEEDBACK_FAILURE:
      return {
        ...state,
        reconResolverPostFeedbackSubmit: action.data,
        reconResolverPostFeedbackSubmitMessage: action.message
      }
    case actions.SEARCH_RECON_SUCCESS:
    case actions.SEARCH_RECON_FAILURE:
      return {
        ...state,
        searchReconData: action.data,
        searchReconMessage: action.message
      }
    default:
      return state
  }
}
