import actions from './actions'

const initialState = {
  feedbackDashboardData: {},
  feedbackDashboardMessage: '',
  feedbackTableData: {},
  feedbackTableMessage: '',
  productData: [],
  productMessage: '',
  feedbackFormData: {},
  feedbackFormMessage: '',
  postFeedbackFormMessage: ''
}

export default function customerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_FEEDBACK:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state,
          ...initialState
        }
      }
    case actions.GET_FEEDBACK_DASHBOARD_SUCCESS:
    case actions.GET_FEEDBACK_DASHBOARD_FAILURE:
      return {
        ...state,
        feedbackDashboardData: action.feedbackDashboardData,
        feedbackDashboardMessage: action.feedbackDashboardMessage
      }
    case actions.GET_FEEDBACK_TABLE_SUCCESS:
    case actions.GET_FEEDBACK_TABLE_FAILURE:
      return {
        ...state,
        feedbackTableData: action.feedbackTableData,
        feedbackTableMessage: action.feedbackTableMessage
      }
    case actions.GET_PRODUCT_SUCCESS:
    case actions.GET_PRODUCT_FAILURE:
      return {
        ...state,
        productData: action.productData,
        productMessage: action.productMessage
      }
    case actions.GET_FEEDBACK_FORM_SUCCESS:
    case actions.GET_FEEDBACK_FORM_FAILURE:
      return {
        ...state,
        feedbackFormData: action.feedbackFormData,
        feedbackFormMessage: action.feedbackFormMessage
      }
    case actions.POST_EDIT_FEEDBACK_FORM_SUCCESS:
    case actions.POST_EDIT_FEEDBACK_FORM_FAILURE:
      return {
        ...state,
        postFeedbackFormMessage: action.postFeedbackFormMessage
      }
    case actions.DOWNLOAD_FEEDBACK_REPORT_SUCCESS:
    case actions.DOWNLOAD_FEEDBACK_REPORT_FAILURE:
      return {
        ...state,
        downloadFeedbackMessage: action.message
      }
    default:
      return state
  }
}
