const actions = {
  GET_PRODUCT_DETAILS: 'GET_PRODUCT_DETAILS',
  PRODUCT_DETAILS: 'PRODUCT_DETAILS',
  CREATE_PRODUCT: 'CREATE_PRODUCT',
  CREATE_PRODUCT_RESULT: 'CREATE_PRODUCT_RESULT',
  DELETE_PRODUCT_RESULT: 'DELETE_PRODUCT_RESULT',
  DELETE_PRODUCT: 'DELETE_PRODUCT',
  getProductDetails: () => ({
    type: actions.GET_PRODUCT_DETAILS
  }),
  createProduct: payload => ({
    type: actions.CREATE_PRODUCT,
    payload
  }),
  createProductResult: payload => ({
    type: actions.CREATE_PRODUCT_RESULT,
    payload
  }),
  deleteProductResult: payload => ({
    type: actions.DELETE_PRODUCT_RESULT,
    payload
  }),
  deleteProduct: payload => ({
    type: actions.DELETE_PRODUCT,
    payload
  })
}
export default actions
