const actions = {
  CREATE_DELAY: 'CREATE_DELAY',
  CREATE_DELAY_SUCCESS: 'CREATE_DELAY_SUCCESS',
  CREATE_DELAY_FAILED: 'CREATE_DELAY_FAILED',
  RESET_REDUX_STATE_DELAY: 'RESET_REDUX_STATE_DELAY',
  createDelay: payload => ({
    type: actions.CREATE_DELAY,
    payload
  }),
  successDelay: payload => ({ // eslint-disable-line
    type: actions.CREATE_DELAY_SUCCESS,
    payload
  }),
  failedDelay: payload => ({ // eslint-disable-line
    type: actions.CREATE_DELAY_FAILED,
    payload
  }),
  resetStateDelay: () => ({
    type: actions.RESET_REDUX_STATE_DELAY
  })
}
export default actions
