import actions from './actions'
import _ from 'lodash/object'

const initialState = {
  listDataDetail: [],
  listDataMessageDisplay: '',

  individualDetailMessage: [],
  individualMessage: '',

  uploadUrl: '',
  uploadMessage: '',

  contanctData: '',

  sendSuccessMessage: '',
  imageSelected: ''
}

export default function customerSupportReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_WHATSAPP_REQUEST:
      return {
        ...state,
        uploadMessage: '',
        individualMessage: ''
      }
    case actions.IMAGE_BLANK:
      return {
        imageSelected: ''
      }

    case actions.PREVIEW_SELECTED_IMAGE:
      return {
        ...state,
        imageSelected: action.payload
      }
    case actions.SHOW_CONTACT_DATA:
      return {
        ...state,
        contanctData: action.payload
      }
    case actions.WHATSAPP_LIST_DATA_SUCCESS:
    case actions.WHATSAPP_LIST_DATA_FAILURE:
      return {
        ...state,
        listDataDetail: _.get(action, 'listDataDetail.chats', '') || _.get(action, 'listDataDetail.contacts', ''),
        chatMetaData: _.get(action, 'listDataDetail.meta_data', ''),
        isIntervalUpdate: action.isIntervalUpdate,
        listDataMessageDisplay: action.listMessage
      }
    case actions.WHATSAPP_DETAIL_MESSAGE_SUCCESS:
    case actions.WHATSAPP_DETAIL_MESSAGE_FAILURE:
      return {
        ...state,
        individualDetailMessage: [action.individualDataDetail],
        individualMessage: action.individualMessage
      }
    case actions.SEND_WHATSAPP_MESSAGE_SUCCESS:
    case actions.SEND_WHATSAPP_MESSAGE_FAILURE:
      return {
        ...state,
        sendSuccessMessage: action.sendMessage
      }
    case actions.UPLOAD_FILES_SUCCESS:
    case actions.UPLOAD_FILES_FAILURE:
      return {
        ...state,
        uploadUrl: action.url,
        uploadMessage: action.sendUploadMessage
      }

    default:
      return state
  }
}
