import actions from './actions'

const initialState = {
  fileTemplates: [],
  columnTypes: [],
  fileTemplatesType: [],
  timezones: [],
  fileTemplateStaticData: []
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.GET_TEMPLATE_TYPES_SUCCESS:
    case actions.GET_TEMPLATE_TYPES_FAILURE:
      return {
        ...state,
        fileTemplatesType: action.data
      }
    case actions.GET_COLUMN_TYPES_SUCCESS:
    case actions.GET_COLUMN_TYPES_FAILURE:
      return {
        ...state,
        columnTypes: action.data
      }
    case actions.CREATE_FILE_TEMPLATE_SUCCESS:
    case actions.CREATE_FILE_TEMPLATE_FAILURE:
      return {
        ...state,
        createTemplate: action.data,
        createTemplateStatus: action.message
      }
    case actions.LIST_TEMPLATE_SUCCESS:
    case actions.LIST_TEMPLATE_FAILURE:
      return {
        ...state,
        fileTemplates: action.data
      }
    case actions.LIST_TIMEZONE_SUCCESS:
    case actions.LIST_TIMEZONE_FAILURE:
      return {
        ...state,
        timezones: action.data
      }
    case actions.EXPORT_TEMPLATE_SUCCESS:
    case actions.EXPORT_TEMPLATE_FAILURE:
      return {
        ...state,
        exportTemplate: action.data
      }
    case actions.IMPORT_TEMPLATE_SUCCESS:
    case actions.IMPORT_TEMPLATE_FAILURE:
      return {
        ...state,
        importTemplate: action.data,
        importTemplateStatus: action.message
      }
    case actions.GET_TEMPLATE_DETAILS_SUCCESS:
    case actions.GET_TEMPLATE_DETAILS_FAILURE:
      return {
        ...state,
        templateDetails: action.data
      }
    case actions.GET_FILE_TEMPLATE_STATIC_DATA_SUCCESS:
    case actions.GET_FILE_TEMPLATE_STATIC_DATA_FAILURE:
      return {
        ...state,
        fileTemplateStaticData: action.data
      }
    case actions.GET_DEFAULT_RECON_CONFIG_SUCCESS:
    case actions.GET_DEFAULT_RECON_CONFIG_FAILURE:
      return {
        ...state,
        defaultConfig: action.data
      }
    default:
      return state
  }
}
