import _ from 'lodash'
import actions from './actions'

const initialState = {
  serviceCenterList: [],
  serviceCenterListMessage: '',

  createServiceCenterData: {},
  createServiceCenterMessage: '',

  updateServiceCenterData: {},
  updateServiceCenterDataMessage: '',

  getServiceCenterDetail: {},
  getServiceCenterDetailMessage: '',

  serviceCenterBranchList: [],
  serviceCenterBranchListMessage: '',

  bulkUploadBranchData: {},
  bulkUploadBranchMessage: '',

  createServiceCenterBranchMessage: '',

  inactiveServiceCenterMessage: '',

  getServiceCenterBranchDetailsMessage: '',
  getServiceCenterBranchDetailsData: {},

  downloadCurrentBranchDataInfo: {},
  downloadCurrentBranchDataMessage: '',

  changeServicecenterUserStatusMessage: '',
  changeServicecenterUserStatusError: null,

  addServiceCenterUserData: {},
  addServiceCenterUserDataMessage: '',

  serviceCenterUsersList: [],
  submitServiceCenterMessage: ''
}

const reducer = (state = initialState, action) => {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_SERVICE_CENTER: {
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state,
          ...initialState
        }
      }
    }

    case actions.GET_SERVICE_CENTER_LIST_SUCCESS:
    case actions.GET_SERVICE_CENTER_LIST_FAILURE:

      return {
        ...state,
        serviceCenterList: _.get(action, 'data', []).map(({ name, ...center }) => ({ ...center, name: decodeURI(name) })),
        serviceCenterListMessage: action.message
      }

    case actions.CREATE_SERVICE_CENTER_SUCCESS:
    case actions.CREATE_SERVICE_CENTER_FAILURE:
      return {
        ...state,
        createServiceCenterData: action.data,
        createServiceCenterMessage: action.message
      }

    case actions.UPDATE_SERVICE_CENTER_SUCCESS:
    case actions.UPDATE_SERVICE_CENTER_FAILURE:
      return {
        ...state,
        updateServiceCenterData: action.data,
        updateServiceCenterDataMessage: action.message
      }

    case actions.GET_SERVICE_CENTER_DETAIL_SUCCESS:
    case actions.GET_SERVICE_CENTER_DETAIL_FAILURE:
      return {
        ...state,
        getServiceCenterDetail: action.data,
        getServiceCenterDetailMessage: action.message
      }

    case actions.GET_SERVICE_CENTER_BRANCH_LIST_DETAIL_SUCCESS:
    case actions.GET_SERVICE_CENTER_BRANCH_LIST_DETAIL_FAILURE:
      return {
        ...state,
        serviceCenterBranchList: action.data,
        serviceCenterBranchListMessage: action.message
      }

    case actions.UPLOAD_BULK_BRANCH_DETAIL_SUCCESS:
    case actions.UPLOAD_BULK_BRANCH_DETAIL_FAILURE:
      return {
        ...state,
        bulkUploadBranchData: action.data,
        bulkUploadBranchMessage: action.message
      }

    case actions.CREATE_SERVICE_CENTER_BRANCH_SUCCESS:
    case actions.CREATE_SERVICE_CENTER_BRANCH_FAILURE:
      return {
        ...state,
        createServiceCenterBranchMessage: _.get(action, 'message', '')
      }

    case actions.UPDATE_SERVICE_CENTER_BRANCH_FAILURE:
    case actions.UPDATE_SERVICE_CENTER_BRANCH_SUCCESS:
      return {
        ...state,
        updateServiceCenterBranchMessage: _.get(action, 'message', '')
      }

    case actions.INACTIVE_SERVICE_CENTER_BRANCH_FAILURE:
    case actions.INACTIVE_SERVICE_CENTER_BRANCH_SUCCESS:
      return {
        ...state,
        inactiveServiceCenterMessage: _.get(action, 'message', '')
      }

    case actions.GET_SERVICE_CENTER_BRANCH_DETAIL_SUCCESS:
    case actions.GET_SERVICE_CENTER_BRANCH_DETAIL_FAILURE:
      return {
        ...state,
        getServiceCenterBranchDetailsMessage: _.get(action, 'message', ''),
        getServiceCenterBranchDetailsData: _.get(action, 'data', {})
      }

    case actions.DOWNLOAD_CURRENT_BRANCH_DETAIL_SUCCESS:
    case actions.DOWNLOAD_CURRENT_BRANCH_DETAIL_FAILURE:
      return {
        ...state,
        downloadCurrentBranchDataInfo: _.get(action, 'data', {}),
        downloadCurrentBranchDataMessage: _.get(action, 'message', '')
      }

    case actions.CHANGE_SERVICE_CENTER_USER_STATUS_SUCCESS:
      return {
        ...state,
        changeServicecenterUserStatusError: false,
        changeServicecenterUserStatusMessage: action.message
      }
    case actions.CHANGE_SERVICE_CENTER_USER_STATUS_FAILURE:
      return {
        ...state,
        changeServicecenterUserStatusError: true,
        changeServicecenterUserStatusMessage: action.message || 'Error'
      }

    case actions.ADD_SERVICE_CENTER_USER_SUCCESS:
    case actions.ADD_SERVICE_CENTER_USER_FAILURE:
      return {
        ...state,
        addServiceCenterUserData: _.get(action, 'data', {}),
        addServiceCenterUserDataMessage: _.get(action, 'message', '')
      }

    case actions.GET_SERVICE_CENTER_USER_LIST_FAILURE:
    case actions.GET_SERVICE_CENTER_USER_LIST_SUCCESS:
      return {
        ...state,
        serviceCenterUsersList: _.get(action, 'data', [])
      }

    case actions.GET_SERVICE_CENTER_USER_GROUP_LIST_SUCCESS:
    case actions.GET_SERVICE_CENTER_USER_GROUP_LIST_FAILURE:
      return {
        ...state,
        serviceCenterGroupList: _.get(action, 'data', {})
      }

    case actions.SUBMIT_SERVICE_CENTER_CONFIG_FAILURE:
    case actions.SUBMIT_SERVICE_CENTER_CONFIG_SUCCESS:
      return {
        ...state,
        submitServiceCenterMessage: _.get(action, 'message', '')
      }

    case actions.GET_SERVICE_CENTER_DEFAULT_CONFIG_SUCCESS:
    case actions.GET_SERVICE_CENTER_DEFAULT_CONFIG_FAILURE:
      return {
        ...state,
        defaultConfigList: _.get(action, 'data', [])
      }

    case actions.GET_SERVICE_CENTER_EXISTING_CONFIG_SUCCESS:
    case actions.GET_SERVICE_CENTER_EXISTING_CONFIG_FAILURE:
      return {
        ...state,
        existingServiceCenterConfig: _.get(action, 'data', []),
        existingServiceCenterMessage: _.get(action, 'message', '')
      }

    case actions.GET_SERVICE_CENTER_BRAND_LIST_SUCCCESS:
    case actions.GET_SERVICE_CENTER_BRAND_LIST_FAILURE:
      return {
        ...state,
        brandList: _.get(action, 'data', [])
      }

    default:
      return state
  }
}

export default reducer
