import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../helpers/callApi'
import _ from 'lodash/object'

export function* getPolicyListDashboardRequest() {
  yield takeEvery('GET_POLICY_LIST_DASHBOARD_REQUEST', function* (payload) {
    try {
      let res = yield call(callApi.getPolicyListDashboard, payload)
      if (res.status === 200) {
        yield put({
          type: actions.GET_POLICY_LIST_DASHBOARD_SUCCESS,
          data: res.data,
          policyListDashboardStatus: 'success'
        })
      } else {
        yield put({
          type: actions.GET_POLICY_LIST_DASHBOARD_FAILURE,
          data: [],
          policyListDashboardStatus: _.get(res, 'data', 'Ooops, something went terribly wrong!')
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_POLICY_LIST_DASHBOARD_FAILURE,
        data: [],
        policyListDashboardStatus: 'Ooops, something went terribly wrong!'
      })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(getPolicyListDashboardRequest)
  ])
}
