export function* getInsuranceRequest() {
  yield takeEvery(actions.GET_INSURANCE_DATA_REQUEST, function* (payload) {
    try {
      const res = yield call(callApi.insuranceApi, payload);
      if (res.status === 200) {
        const policyList = res.data.data || [];
        const metadata = res.data.metadata || {};
        const formattedPolicyList = dataFormatter(policyList);
        yield put({
          type: actions.GET_INSURANCE_DATA_SUCCESS,
          policyList: formattedPolicyList,
          metadata,
          policyMessage: "success",
        });
        yield put({
          type: actions.GET_PARTNERS_REQUEST,
        });
        yield put({
          type: actions.GET_PRODUCTS_REQUEST,
          payload: {
            query: {
              partner_code: _.get(payload, "payload.partner", ""),
            },
          },
        });
      } else {
        const message = exceptionHandlerSanitizer(res.data);
        yield put({
          type: actions.GET_INSURANCE_DATA_FAILURE,
          policyMessage: message,
        });
      }
    } catch (error) {
      yield put({
        type: actions.GET_INSURANCE_DATA_FAILURE,
        policyMessage: "Error while getting Insurance data",
      });
    }
  });
}

