export function* uploadEndorsePolicyFileRequest() {
  yield takeEvery(
    actions.UPLOAD_ENDORSE_POLICY_FILE_REQUEST,
    function* ({ payload }) {
      const key = _.get(payload, "extra.key");
      yield put({
        type: actions.UPDATE_ENDORSE_POLICY_FILE_LOADING,
        target: { [key]: true },
      });
      try {
        const res = yield call(authPostFormData, {
          ...payload,
          url: policyUrls.uploadFileUrl,
        });
        if ([201, 200].includes(res.status)) {
          const url = _.get(res, "data.url");
          yield put({
            type: actions.UPLOAD_ENDORSE_POLICY_FILE_SUCCESS,
            message: "Success",
            target: {
              [key]: url,
            },
          });
        } else {
          yield put({
            type: actions.UPLOAD_ENDORSE_POLICY_FILE_FAILURE,
            message: "Failed uploading",
          });
        }
        yield put({
          type: actions.UPDATE_ENDORSE_POLICY_FILE_LOADING,
          target: { [key]: false },
        });
      } catch (error) {
        yield put({
          type: actions.UPDATE_ENDORSE_POLICY_FILE_LOADING,
          target: { [key]: false },
        });
        yield put({
          type: actions.UPLOAD_ENDORSE_POLICY_FILE_FAILURE,
          message: error.message,
        });
      }
    }
  );
}

