export function* evaluateFormulaRequest() {
  yield takeEvery(
    actions.EVALUATE_FORMULA_REQUEST,
    function* ({ payload }) {
      console.log(payload)
      try {
        const res = yield call(authPost, {
          body: { expression: payload.expression },
          url: policyUrls.evaluateFormula(
            payload.productCode,
            payload.packageCode
          ),
        });
        if ([200, 201].includes(res.status)) {
          yield put({
            type: actions.EVALUATE_FORMULA_SUCCESS,
            data: res.data,
            message: "success",
          });

          payload.onSuccess()
        } else {
          yield put({
            type: actions.EVALUATE_FORMULA_FAILURE,
            data: {},
            message: _.get(
              res,
              "data.error",
              "failed to create formula attribute"
            ),
          });

          payload.onError()
        }
      } catch (error) {
        yield put({
          type: actions.EVALUATE_FORMULA_FAILURE,
          data: {},
          message: error.message || "error",
        });

        payload.onError()
      }
    }
  );
}

