import actions from './actions'

const initialState = {
  listData: [],
  listMeta: {},
  listMessage: '',
  detailData: {},
  detailLogs: [],
  detailMessage: '',
  progressMessage: '',
  rejectMessage: ''
}

export default function hardcopyReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_HARDCOPY_STATE: {
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        const stateToReset = {}
        payload.forEach(key => { stateToReset[key] = initialState[key] })
        return { ...state, ...stateToReset }
      }
      return { ...state, ...initialState }
    }
    case actions.LIST_HARDCOPY_SUCCESS:
    case actions.LIST_HARDCOPY_FAILURE:
      return {
        ...state,
        listData: action.listData,
        listMeta: action.listMeta,
        listMessage: action.listMessage
      }
    case actions.GET_HARDCOPY_SUCCESS:
    case actions.GET_HARDCOPY_FAILURE:
      return {
        ...state,
        detailData: action.detailData,
        detailLogs: action.detailLogs,
        detailMessage: action.detailMessage
      }
    case actions.PROGRESS_HARDCOPY_SUCCESS:
    case actions.PROGRESS_HARDCOPY_FAILURE:
      return { ...state, progressMessage: action.progressMessage }
    case actions.REJECT_HARDCOPY_SUCCESS:
    case actions.REJECT_HARDCOPY_FAILURE:
      return { ...state, rejectMessage: action.rejectMessage }
    default:
      return state
  }
}
