import actions from './actions'

const initialState = {
  salesAgentReferralCode: '',
  salesAgentReferralCodeStatus: ''
}

export default function salesAgentReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_SALES_AGENT_STORE:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    case actions.GET_SALES_REFERRAL_CODE_SUCCESS:
    case actions.GET_SALES_REFERRAL_CODE_FAILURE:
      return {
        ...state,
        salesAgentReferralCode: action.data,
        salesAgentReferralCodeStatus: action.message
      }
    default:
      return state
  }
}
