import React, { Component } from 'react'
import { Alert } from 'antd'
import { connect } from 'react-redux'
import { Link } from 'react-router-dom'
import Input from '../../../components/uielements/input'
import Button from '../../../components/uielements/button'
import ForgotPasswordStyleWrapper from './forgotPassword.style'
import userAction from '../../redux/user/actions'
import { clearToken } from '../../../helpers/utility'

const { forgotPassword } = userAction

class ForgotPassword extends Component {
  constructor (props) {
    super(props)
    this.state = {
      email: '',
      loading: false,
      status: ''
    }
  }

  componentDidMount () {
    clearToken()
  }

  onHandleChange = (val) => {
    this.setState({
      [val.target.name]: val.target.value,
      status: ''
    })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { forgotPasswordStatus } = nextProps.forgotPasswordStatus
    this.setState({ status: forgotPasswordStatus, loading: false })
  }

  onHandleSubmit () {
    this.props.forgotPassword(this.state.email)
    this.setState({ loading: true, email: '' })
  }

  render () {
    const { status, email } = this.state
    if (status === 'User not found') {
      return (
        <ForgotPasswordStyleWrapper className='isoForgotPassPage'>
          <div className='isoFormContentWrapper'>
            <div className='isoFormContent'>
              <div className='isoLogoWrapper'>
                <Link to='/signin'>
                  Operations Panel
                </Link>
              </div>
              <div>
                <Alert message='Warning!' description='Your email was not found!' type='warning' style={{ marginBottom: '20px' }} />
                <div className='isoFormHeadText'>
                  <h3>
                    Forgot Password
                  </h3>
                  <p>
                    Enter your email and we send you a reset link.
                  </p>
                </div>
                <div className='isoForgotPassForm'>
                  <div className='isoInputWrapper'>
                    <Input size='large' placeholder='Email' name='email' onChange={(e) => this.onHandleChange(e)} />
                  </div>
                  <div className='isoInputWrapper'>
                    <Button type='primary' loading={this.state.loading} onClick={() => this.onHandleSubmit()} disabled={email === ''}>
                      Send Request
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </ForgotPasswordStyleWrapper>
      )
    }
    return (
      <ForgotPasswordStyleWrapper className='isoForgotPassPage'>
        <div className='isoFormContentWrapper'>
          <div className='isoFormContent'>
            <div className='isoLogoWrapper'>
              <Link to='/signin'>
                Operations Panel
              </Link>
            </div>
            {
              (status === 'Success')
                ? (
                  <Alert message='Success!' description='We just sent reset password link to your email. Please check your email!' type='success' />)
                : (
                  <div>
                    <div className='isoFormHeadText'>
                      <h3>
                        Forgot Password
                      </h3>
                      <p>
                        Enter your email and we send you a reset link.
                      </p>
                    </div>
                    <div className='isoForgotPassForm'>
                      <div className='isoInputWrapper'>
                        <Input size='large' placeholder='Email' name='email' onChange={(e) => this.onHandleChange(e)} />
                      </div>
                      <div className='isoInputWrapper'>
                        <Button type='primary' loading={this.state.loading} onClick={() => this.onHandleSubmit()} disabled={email === ''}>
                          Send Request
                        </Button>
                      </div>
                    </div>
                  </div>)
            }
          </div>
        </div>
      </ForgotPasswordStyleWrapper>
    )
  }
}

export default connect(
  state => ({
    forgotPasswordStatus: state.User
  }),
  { forgotPassword }
)(ForgotPassword)
