import { lazy } from 'react'
import retry from '../../../components/utility/retryLogic'

const permission = {
  preset: 'ops.preset',
  create: 'ops.create_preset',
  list: 'ops.view_preset_list',
  edit: 'ops.edit_preset',
  view: 'ops.view_preset'
}

const routes = [
  {
    title: 'Preset',
    path: 'preset',
    component: false,
    permission: permission.preset,
    icon: 'fa fa-list-alt',
    subPaths: [
      {
        title: 'Preset List',
        path: '/list',
        permission: permission.list,
        component: lazy(() => retry(() => import('../../containers/Preset/pages/PresetListContainer'))),
        icon: 'fa fa-list-alt',
        subMenu: true
      },
      {
        title: 'Create Preset',
        path: '/create',
        permission: permission.create,
        component: lazy(() => retry(() => import('../../containers/Preset/pages/CreatePreset'))),
        icon: 'fa fa-list-alt',
        subMenu: false
      },
      {
        title: 'Edit Preset',
        path: '/:presetId/edit',
        component: lazy(() => retry(() => import('../../containers/Preset/pages/EditPreset'))),
        permission: permission.edit,
        icon: 'fa fa-list-alt',
        subMenu: false
      },
      {
        title: 'Preset Details',
        path: '/:presetId/',
        component: lazy(() => retry(() => import('../../containers/Preset/pages/PresetDetails'))),
        permission: permission.view,
        icon: 'fa fa-list-alt',
        subMenu: false
      }
    ]
  }
]

export default routes
