import actions from './actions'

const initialState = {
  policy: {},
  policyList: [],
  providerUserList: [],
  providerList: [],
  agentProviderList: [],
  providerMessage: '',
  providerListMessage: '',
  providerUserMessage: '',
  agentProviderListMessage: [],
  userProfile: {}
}

export default function providerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.GET_PROVIDER_USER_DATA_SUCCESS:
    case actions.GET_PROVIDER_USER_DATA_FAILURE:
      return {
        ...state,
        providerUserList: action.providerUserList,
        providerMessage: action.providerMessage
      }
    case actions.GET_PROVIDER_LIST_SUCCESS:
    case actions.GET_PROVIDER_LIST_FAILURE:
      return {
        ...state,
        providerList: action.providerList,
        providerListMessage: action.providerListMessage
      }
    case actions.GET_AGENT_PROVIDER_LIST_SUCCESS:
    case actions.GET_AGENT_PROVIDER_LIST_FAILURE:
      return {
        ...state,
        agentProviderList: action.agentProviderList,
        agentProviderListMessage: action.agentProviderListMessage
      }
    case actions.POST_PROVIDER_USER_SUCCESS:
    case actions.POST_PROVIDER_USER_FAILURE:
      return {
        ...state,
        providerUserMessage: action.providerUserMessage
      }
    case actions.RESET_REDUX_STATE:
      const { payload } = action
      if (payload && Array.isArray(payload)) {
        let stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = initialState[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state,
          ...initialState
        }
      }
    case actions.GET_PROVIDER_CONFIG_SUCCESS:
    case actions.GET_PROVIDER_CONFIG_FAILURE:
      return {
        ...state,
        providerConfig: action.data
      }
    case actions.GET_PROVIDER_USER_SUCCESS:
    case actions.GET_PROVIDER_USER_FAILURE:
      return {
        ...state,
        providerUser: action.data
      }
    case actions.GET_DEFAULT_CONFIG_SUCCESS:
    case actions.GET_DEFAULT_CONFIG_FAILURE:
      return {
        ...state,
        defaultConfig: action.data
      }
    case actions.ADD_PROVIDER_CONFIG_SUCCESS:
    case actions.ADD_PROVIDER_CONFIG_FAILURE:
      return {
        ...state,
        addProviderConfigMessage: action.message
      }
    case actions.UPDATE_PROVIDER_CONFIG_SUCCESS:
    case actions.UPDATE_PROVIDER_CONFIG_FAILURE:
      return {
        ...state,
        updateProviderConfigMessage: action.message
      }
    case actions.GET_GROUP_LIST_SUCCESS:
    case actions.GET_GROUP_LIST_FAILURE:
      return {
        ...state,
        providerGroupList: action.data
      }
    case actions.ADD_PROVIDER_USER_SUCCESS:
    case actions.ADD_PROVIDER_USER_FAILURE:
      return {
        ...state,
        addProviderUserMessage: action.message
      }
    case actions.UPDATE_PROVIDER_USER_SUCCESS:
    case actions.UPDATE_PROVIDER_USER_FAILURE:
      return {
        ...state,
        updateProviderUserMessage: action.message
      }
    case actions.UPDATE_PROVIDER_USER_STATUS_SUCCESS:
    case actions.UPDATE_PROVIDER_USER_STATUS_FAILURE:
      return {
        ...state,
        updateProviderUserStatusMessage: action.message
      }
    case actions.ADD_PROVIDER_SUCCESS:
    case actions.ADD_PROVIDER_FAILURE:
      return {
        ...state,
        addProviderMessage: action.message
      }
    case actions.GET_PROVIDER_DETAILS_SUCCESS:
    case actions.GET_PROVIDER_DETAILS_FAILURE:
      return {
        ...state,
        providerDetails: action.data,
        getProviderDetailsMessage: action.message
      }
    default:
      return state
  }
}
