const actions = {
  WHATSAPP_LIST_DATA_REQUEST: ' WHATSAPP_LIST_DATA_REQUEST',
  WHATSAPP_LIST_DATA_SUCCESS: 'WHATSAPP_LIST_DATA_SUCCESS',
  WHATSAPP_LIST_DATA_FAILURE: 'WHATSAPP_LIST_DATA_FAILURE',

  WHATSAPP_DETAIL_MESSAGE_REQUEST: 'WHATSAPP_DETAIL_MESSAGE_REQUEST',
  WHATSAPP_DETAIL_MESSAGE_SUCCESS: 'WHATSAPP_DETAIL_MESSAGE_SUCCESS',
  WHATSAPP_DETAIL_MESSAGE_FAILURE: 'WHATSAPP_DETAIL_MESSAGE_FAILURE',

  WHATSAPP_READ_STATUS_REQUEST: 'WHATSAPP_READ_STATUS_REQUEST',
  WHATSAPP_READ_STATUS_SUCCESS: 'WHATSAPP_READ_STATUS_SUCCESS',
  WHATSAPP_READ_STATUS_FAILURE: 'WHATSAPP_READ_STATUS_FAILURE',

  SEND_WHATSAPP_MESSAGE_REQUEST: 'SEND_WHATSAPP_MESSAGE_REQUEST',
  SEND_WHATSAPP_MESSAGE_SUCCESS: 'SEND_WHATSAPP_MESSAGE_SUCCESS',
  SEND_WHATSAPP_MESSAGE_FAILURE: 'SEND_WHATSAPP_MESSAGE_FAILURE',

  UPLOAD_FILES_REQUEST: 'UPLOAD_FILES_REQUEST',
  UPLOAD_FILES_SUCCESS: 'UPLOAD_FILES_SUCCESS',
  UPLOAD_FILES_FAILURE: 'UPLOAD_FILES_FAILURE',

  SHOW_CONTACT_DATA: 'SHOW_CONTACT_DATA',
  PREVIEW_SELECTED_IMAGE: 'PREVIEW_SELECTED_IMAGE',

  IMAGE_BLANK: 'IMAGE_BLANK',

  RESET_WHATSAPP_REQUEST: 'RESET_WHATSAPP_REQUEST',

  getWhatsappList: payload => ({
    type: actions.WHATSAPP_LIST_DATA_REQUEST,
    payload
  }),
  getWhatsappData: payload => ({
    type: actions.WHATSAPP_DETAIL_MESSAGE_REQUEST,
    payload
  }),
  readWhatsappStatus: payload => ({
    type: actions.WHATSAPP_READ_STATUS_REQUEST,
    payload
  }),
  sendWhatsappMessage: payload => ({
    type: actions.SEND_WHATSAPP_MESSAGE_REQUEST,
    payload
  }),
  uploadData: payload => ({
    type: actions.UPLOAD_FILES_REQUEST,
    payload
  }),
  displayContactData: payload => ({
    type: actions.SHOW_CONTACT_DATA,
    payload
  }),
  resetRedux: payload => ({
    type: actions.RESET_WHATSAPP_REQUEST,
    payload
  }),
  previewSelected: payload => ({
    type: actions.PREVIEW_SELECTED_IMAGE,
    payload
  }),
  imageBlank: payload => ({
    type: actions.IMAGE_BLANK,
    payload
  })

}

export default actions
