import { update } from "lodash";
import actions from "./actions";
import _ from "lodash/object";

const initialState = {
  policy: {},
  policyList: [],
  failedFetchPolicyDetail: {},
  successMessage: "",
  failedMessage: "",
  failedMessageGetPartner: "",
  sendPolicyReportStatus: "",
  sendPolicyRangeReportStatus: "",
  updatePolicyNoStatus: "",
  policyDetail: {},
  getDetailPolicyStatus: "",
  products: [],
  partners: [],
  uploadUpdatePolicyNumberFileMessage: "",
  policySearchResult: {},
  policySearchMetadata: {},
  policySearchMessage: "",
  endorsePolicyFile: {},
  endorsePolicyFileLoading: {},
  endorsePolicyMessage: "",
  enqueuePolicyData: {},
  enqueuePolicyDataMessage: "",
  certificateRetryData: {},
  certificateRetryDataMessage: "",
  dynamicEndorseMessage: "",
  internalCancellationMessage: "",
  policyEditAttributeData: {},
  policyEditAttributeDataMessage: "",
  editPolicyDataMessage: "",
  editPolicyData: {},
  createEndorsementData: {},
  uploadBulkRetryMessage: "",
  policyRetryList: {},
  policyRetryListMessage: "",
  policyRetryFileDetailData: [],
  policyRetryFileDetailDataMessage: "",
  createOfflinePolicyData: {},
  createOfflinePolicyStatus: "",
  webhookLogMessage: "",
  webhookLogData: [],
  masterListData: [],
  wehbookRetryMessage: "",
  bulkInternalCancellationMessage: "",
  bulkCancellationMessage: "",
  bulkUpdatePremiumMessage: "",
  uploadCsvMessage: "",
  uploadCsvData: {},
  bulkOperationsTypesData: [],
  bulkOperationsTypesMessage: "",
  bulkOperateUploadMessage: "",
  reactivatePolciyData: {},
  reactivatePolciyMessage: "",
  createFormulaAttributeData: {},
  createFormulaAttributeMessage: "",
  getFormulaAttributeData: {},
  getFormulaAttributeMessage: "",
  updateFormulaAttributeData: {},
  updateFormulaAttributeMessage: "",
  deleteFormulaAttributeData: {},
  deleteFormulaAttributeMessage: "",
};

export default function insuranceReducer(state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_POLICY: {
      const { payload } = action;
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {};
        payload.forEach((key) => {
          stateToBeReset[key] = initialState[key];
        });
        return {
          ...state,
          ...stateToBeReset,
        };
      } else {
        return {
          ...state,
        };
      }
    }
    case actions.RESET_DOWNLOAD_STATUS:
      return {
        ...state,
        sendPolicyReportStatus: "",
      };
    case actions.GET_INSURANCE_DATA_SUCCESS:
      return {
        ...state,
        policyList: action.policyList,
        successMessage: action.policyMessage,
      };
    case actions.GET_INSURANCE_DATA_COUNT_SUCCESS:
      return {
        ...state,
        metadata: action.metadata,
        successMessage: action.policyMessage,
      };
    case actions.GET_INSURANCE_DATA_FAILURE:
      return {
        ...state,
        failedMessage: action.policyMessage,
      };
    case actions.INSURANCE_DETAIL:
      return {
        ...state,
        policyDetail: action.policyDetail,
        message: "",
      };
    case actions.FAILED_GET_INSURANCE_DETAIL:
      return {
        ...state,
        getDetailPolicyStatus: action.getDetailPolicyStatus,
        policyDetail: action.policyDetail,
      };
    case actions.GET_POLICY_DETAILS_SUCCESS:
    case actions.GET_POLICY_DETAILS_FAILURE:
      return {
        ...state,
        policyDetail: action.policyDetail,
        getPolicyDetailsMessage: action.message,
      };
    case actions.POLICY_PAYMENT_DETAILS:
      return {
        ...state,
        policyPaymentData: action.policyPaymentData,
      };
    case actions.FAILED_GET_POLICY_PAYMENT_DETAILS:
      return {
        ...state,
        statusGetPaymentDetails: action.statusGetPaymentDetails,
      };
    // case actions.DATA_PARTNERS:
    //   return {
    //     ...state,
    //     partners: action.partners
    //   }
    case actions.GET_PARTNERS_SUCCESS:
    case actions.GET_PARTNERS_FAILURE:
      return {
        ...state,
        partners: action.partners,
      };
    case actions.GET_PRODUCTS_SUCCESS:
    case actions.GET_PRODUCTS_FAILURE:
      return {
        ...state,
        products: action.products,
        getProductsMessage: action.message,
      };
    case actions.FAILED_GET_DATA_PARTNERS:
      return {
        ...state,
        failedMessageGetPartner: action.failedMessageGetPartner,
      };
    case actions.SUCCESS_SEND_REPORT_POLICY:
      return {
        ...state,
        sendPolicyReportStatus: action.sendPolicyReportStatus,
      };
    case actions.FAILED_SEND_REPORT_POLICY:
      return {
        ...state,
        sendPolicyReportStatus: action.sendPolicyReportStatus,
      };
    case actions.SUCCESS_SEND_REPORT_POLICY_RANGE:
      return {
        ...state,
        sendPolicyRangeReportStatus: action.sendPolicyRangeReportStatus,
      };
    case actions.FAILED_SEND_REPORT_POLICY_RANGE:
      return {
        ...state,
        sendPolicyRangeReportStatus: action.sendPolicyRangeReportStatus,
      };
    case actions.SUCCESS_UPDATE_POLICY_NO:
      return {
        ...state,
        updatePolicyNoStatus: action.updatePolicyNoStatus,
      };
    case actions.FAILED_UPDATE_POLICY_NO:
      return {
        ...state,
        updatePolicyNoStatus: action.updatePolicyNoStatus,
      };
    case actions.UPLOAD_UPDATE_POLICY_NUMBER_FILE_SUCCESS:
    case actions.UPLOAD_UPDATE_POLICY_NUMBER_FILE_FAILURE:
      return {
        ...state,
        uploadUpdatePolicyNumberFileMessage: action.message,
      };
    case actions.UPLOAD_FILE_SUCCESS:
    case actions.UPLOAD_FILE_FAILURE:
    case actions.UPLOAD_GENERIC_FILE_SUCCESS:
    case actions.UPLOAD_GENERIC_FILE_FAILURE:
      return {
        ...state,
        uploadPolicyFileStatus: action.message,
        uploadPolicyFileData: action.data,
      };
    case actions.FIND_POLICY_SUCCESS:
    case actions.FIND_POLICY_FAILURE:
      return {
        ...state,
        policySearchResult: action.policySearchResult,
        policySearchMetadata: action.policySearchMetadata,
        policySearchMessage: action.policySearchMessage,
      };
    case actions.UPLOAD_ENDORSE_POLICY_FILE_SUCCESS:
    case actions.UPLOAD_ENDORSE_POLICY_FILE_FAILURE:
    case actions.RESET_ENDORSE_POLICY_FILE: {
      const currentState = Object.assign({}, state.endorsePolicyFile);
      const mergedState = _.merge(currentState, action.target);
      return {
        ...state,
        endorsePolicyFile: {
          ...mergedState,
        },
        uploadEndorsePolicyFileMessage: action.message,
      };
    }
    case actions.UPDATE_ENDORSE_POLICY_FILE_LOADING: {
      const currentLoadingState = Object.assign(
        {},
        state.endorsePolicyFileLoading
      );
      const mergedLoadingState = _.merge(currentLoadingState, action.target);
      return {
        ...state,
        endorsePolicyFileLoading: {
          ...mergedLoadingState,
        },
        uploadEndorsePolicyFileMessage: action.message,
      };
    }
    case actions.ENDORSE_POLICY_SUCCESS:
    case actions.ENDORSE_POLICY_FAILURE:
      return {
        ...state,
        endorsePolicyMessage: action.message,
      };
    case actions.ENQUEUE_POLICY_SUCCESS:
    case actions.ENQUEUE_POLICY_FAILURE:
      return {
        ...state,
        enqueuePolicyData: action.enqueueData,
        enqueuePolicyDataMessage: action.message,
      };
    case actions.CERTIFICATE_RETRY_SUCCESS:
    case actions.CERTIFICATE_RETRY_FAILURE:
      return {
        ...state,
        certificateRetryData: action.certificateData,
        certificateRetryDataMessage: action.message,
      };
    case actions.DYNAMIC_ENDORSE_SUCCESS:
    case actions.DYNAMIC_ENDORSE_FAILURE:
      return {
        ...state,
        dynamicEndorseMessage: action.message,
      };
    case actions.INTERNAL_CANCELLATION_POLICY_SUCCESS:
    case actions.INTERNAL_CANCELLATION_POLICY_FAILURE:
      return {
        ...state,
        internalCancellationMessage: action.statusCancelPolicy,
      };
    case actions.GET_POLICY_EDIT_ATTRIBUTES_SUCCESS:
    case actions.GET_POLICY_EDIT_ATTRIBUTES_FAILURE:
      return {
        ...state,
        policyEditAttributeData: action.data,
        policyEditAttributeDataMessage: action.statusPolicyEdit,
      };
    case actions.EDIT_POLICY_DATA_SUCCESS:
    case actions.EDIT_POLICY_DATA_FAILURE:
      return {
        ...state,
        editPolicyDataMessage: action.statusPolicyEditMessage,
        editPolicyData: action.statusPolicyData,
      };
    case actions.CREATE_POLICY_ENDORSEMENT_SUCCESS:
    case actions.CREATE_POLICY_ENDORSEMENT_FAILURE:
      return {
        ...state,
        editPolicyDataMessage: action.statusPolicyEditMessage,
        createEndorsementData: action.statusPolicyData,
      };
    case actions.UPLOAD_BULK_POLICY_RETRY_NOTIFICATION_SUCCESS:
    case actions.UPLOAD_BULK_POLICY_RETRY_NOTIFICATION_FAILURE:
      return {
        ...state,
        uploadBulkRetryMessage: action.message,
      };
    case actions.BULK_POLICY_RETRY_LIST_SUCCESS:
    case actions.BULK_POLICY_RETRY_LIST_FAILURE:
      return {
        ...state,
        policyRetryList: action.data,
        policyRetryListMessage: action.message,
      };
    case actions.CREATE_OFFLINE_POLICY_SUCCESS:
    case actions.CREATE_OFFLINE_POLICY_FAILURE:
      return {
        ...state,
        createOfflinePolicyData: action.data,
        createOfflinePolicyStatus: action.message,
      };
    case actions.BULK_POLICY_RETRY_LIST_FILE_DATA_SUCCESS:
    case actions.BULK_POLICY_RETRY_LIST_FILE_DATA_FAILURE:
      return {
        ...state,
        policyRetryFileDetailData: action.data,
        policyRetryFileDetailDataMessage: action.message,
      };
    case actions.GET_CHANGE_HISTORY_DATA_SUCCESS:
    case actions.GET_CHANGE_HISTORY_DATA_FAILURE:
      return {
        ...state,
        changeHistoryData: action.data,
        changeHistoryMessage: action.message,
      };
    case actions.GET_WEBHOOK_LOGS_SUCCESS:
    case actions.GET_WEBHOOK_LOGS_FAILURE:
      return {
        ...state,
        webhookLogData: action.data,
        webhookLogMessage: action.message,
      };
    case actions.GET_MASTER_LIST_SUCCESS:
      return {
        ...state,
        masterListData: { ...action.data },
      };
    case actions.GET_MASTER_LIST_FAILURE:
      return {
        ...state,
        masterListData: [],
      };
    case actions.GET_WEBHOOK_RETRY_SUCCESS:
      return {
        ...state,
        wehbookRetryMessage: action.message,
      };
    case actions.GET_WEBHOOK_RETRY_FAILURE:
      return {
        ...state,
        wehbookRetryMessage: action.message,
      };
    case actions.UPLOAD_CSV_SUCCESS:
    case actions.UPLOAD_CSV_FAILURE:
      return {
        ...state,
        uploadCsvMessage: action.message,
        uploadCsvData: action.data,
      };
    case actions.BULK_INTERNAL_CANCEL_SUCCESS:
    case actions.BULK_INTERNAL_CANCEL_FAILURE:
      return {
        ...state,
        bulkInternalCancellationMessage: action.message,
      };
    case actions.BULK_CANCEL_SUCCESS:
    case actions.BULK_CANCEL_FAILURE:
      return {
        ...state,
        bulkCancellationMessage: action.message,
      };
    case actions.BULK_UPDATE_PREMIUM_SUCCESS:
    case actions.BULK_UPDATE_PREMIUM_FAILURE:
      return {
        ...state,
        bulkUpdatePremiumMessage: action.message,
      };
    case actions.BULK_OPERATIONS_TYPE_SUCCESS:
    case actions.BULK_OPERATIONS_TYPE_FAILURE:
      return {
        ...state,
        bulkOperationsTypesData: action.data,
        bulkOperationsTypesMessage: action.message,
      };
    case actions.BULK_OPERATE_SUCCESS:
    case actions.BULK_OPERATE_FAILURE:
      return {
        ...state,
        bulkOperateUploadMessage: action.message,
      };
    case actions.BULK_OPERATION_LIST_SUCCESS:
    case actions.BULK_OPERATION_LIST_FAILURE:
      return {
        ...state,
        bulkOperationListData: action.data,
        bulkOperationListMessage: action.message,
      };
    case actions.INSURANCE_OPERATION_LIST_SUCCESS:
    case actions.INSURANCE_OPERATION_LIST_FAILURE:
      return {
        ...state,
        insuranceOperationListData: action.data,
        insuranceOperationListMessage: action.message,
      };
    case actions.DOWNLOAD_OPERATION_LIST_SUCCESS:
    case actions.DOWNLOAD_OPERATION_LIST_FAILURE:
      return {
        ...state,
        downloadOperationListData: action.data,
        downloadOperationListMessage: action.message,
      };
    case actions.REACTIVATE_POLICY_SUCCESS:
    case actions.REACTIVATE_POLICY_FAILURE:
      return {
        ...state,
        reactivatePolciyData: action.data,
        reactivatePolciyMessage: action.message,
      };
    case actions.CREATE_FORMULA_ATTRIBUTE_SUCCESS:
    case actions.CREATE_FORMULA_ATTRIBUTE_FAILURE:
      return {
        ...state,
        createFormulaAttributeData: action.data,
        createFormulaAttributeMessage: action.message,
      };
    case actions.GET_FORMULA_ATTRIBUTE_SUCCESS:
    case actions.GET_FORMULA_ATTRIBUTE_FAILURE:
      return {
        ...state,
        getFormulaAttributeData: action.data,
        getFormulaAttributeMessage: action.message,
      };
    case actions.UPDATE_FORMULA_ATTRIBUTE_SUCCESS:
    case actions.UPDATE_FORMULA_ATTRIBUTE_FAILURE:
      return {
        ...state,
        updateFormulaAttributeData: action.data,
        updateFormulaAttributeMessage: action.message,
      };
    case actions.DELETE_FORMULA_ATTRIBUTE_SUCCESS:
    case actions.DELETE_FORMULA_ATTRIBUTE_FAILURE:
      return {
        ...state,
        deleteFormulaAttributeData: action.data,
        deleteFormulaAttributeMessage: action.message,
      };
    default:
      return state;
  }
}
