
import { AGENT_ACTIONS } from './actions'
export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload } = action

  switch (type) {
    case AGENT_ACTIONS.GET_PRODUCT_ADDONS:
    case AGENT_ACTIONS.UPLOAD_FILE:
    case AGENT_ACTIONS.GET_ADDONS:
    case AGENT_ACTIONS.GET_ADDONS_PREMIUM:
    case AGENT_ACTIONS.GET_PROVIDER_LIST:
    case AGENT_ACTIONS.RESET_AGENT_STORE:
    case AGENT_ACTIONS.GET_APPLICATION_FILTER:
    case AGENT_ACTIONS.GET_AGENT_PACKAGE_LIST:
      return {
        ...state,
        ...payload
      }
    default:
      return state
  }
}

export default reducer
