import { all, takeEvery, call, fork, put } from 'redux-saga/effects'
import actions from './actions'
import authGet from '../../../request/methods/authGet'
import authPost from '../../../request/methods/authPost'
import urls from '../../../request/urls/productConfig'
import authPut from '../../../request/methods/authPut'

export function * getProductList () {
  yield takeEvery(actions.GET_PRODUCT_LIST_REQUEST, function * ({ payload }) {
    try {
      const res = yield call(authGet, {
        query: payload.query,
        url: urls.getConfigurableProductListUrl
      })
      if (res.status === 200) {
        yield put({
          type: actions.GET_PRODUCT_LIST_SUCCESS,
          data: res.data,
          getProductListMessage: 'success'
        })
      } else {
        yield put({
          type: actions.GET_PRODUCT_LIST_FAILURE,
          data: [],
          getProductListMessage: 'error'
        })
      }
    } catch (error) {
      yield put({
        type: actions.GET_PRODUCT_LIST_FAILURE,
        data: [],
        getProductListMessage: error.message
      })
    }
  })
}
