const actions = {
    RESET_TAP_INSURE_CONFIG: "RESET_FINANCIAL_LIST",

  ADD_UPDATE_FINANCIAL_REPORTS_REQUEST: "ADD_UPDATE_FINANCIAL_REPORTS_REQUEST",
  ADD_UPDATE_FINANCIAL_REPORTS_SUCCESS: "ADD_UPDATE_FINANCIAL_REPORTS_SUCCESS",
  ADD_UPDATE_FINANCIAL_REPORTS_FAILURE: "ADD_UPDATE_FINANCIAL_REPORTS_FAILURE",

  GET_WORKSHOP_REPORTS_REQUEST: "GET_WORKSHOP_REPORTS_REQUEST",
  GET_WORKSHOP_REPORTS_SUCCESS: "GET_WORKSHOP_REPORTS_SUCCESS",
  GET_WORKSHOP_REPORTS_FAILURE: "GET_WORKSHOP_REPORTS_FAILURE",

  resetReportingConfigRedux: (payload) => ({
    type: actions.RESET_TAP_INSURE_CONFIG,
    payload,
  }),
  addUpdateReport: (payload = {}) => ({
    type: actions.ADD_UPDATE_FINANCIAL_REPORTS_REQUEST,
    payload,
  }),
  getWorkshopList: (query = {}) => ({
    type: actions.GET_WORKSHOP_REPORTS_REQUEST,
    payload: { query },
  }),
};
export default actions;
