  GET_EVENT_TYPE_SUCCESS: 'GET_EVENT_TYPE_SUCCESS',
  GET_EVENT_TYPE_FAILURE: 'GET_EVENT_TYPE_FAILURE',

  GET_WEBHOOK_LIST_REQUEST: 'GET_WEBHOOK_LIST_REQUEST',
  GET_WEBHOOK_LIST_SUCCESS: 'GET_WEBHOOK_LIST_SUCCESS',
  GET_WEBHOOK_LIST_FAILURE: 'GET_WEBHOOK_LIST_FAILURE',

  CREATE_WEBHOOK_REQUEST: 'CREATE_WEBHOOK_REQUEST',
  CREATE_WEBHOOK_SUCCESS: 'CREATE_WEBHOOK_SUCCESS',
  CREATE_WEBHOOK_FAILURE: 'CREATE_WEBHOOK_FAILURE',

  UPDATE_WEBHOOK_REQUEST: 'UPDATE_WEBHOOK_REQUEST',
  UPDATE_WEBHOOK_SUCCESS: 'UPDATE_WEBHOOK_SUCCESS',
  UPDATE_WEBHOOK_FAILURE: 'UPDATE_WEBHOOK_FAILURE',

  GET_FUNCTIONS_REQUEST: 'GET_FUNCTIONS_REQUEST',
  GET_FUNCTIONS_SUCCESS: 'GET_FUNCTIONS_SUCCESS',
  GET_FUNCTIONS_FAILURE: 'GET_FUNCTIONS_FAILURE',

  GET_HEADERS_REQUEST: 'GET_HEADERS_REQUEST',
