import React, { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { Layout, notification } from 'antd'
import PropTypes from 'prop-types'

import { ThemeProvider } from 'styled-components'
import authAction from '../../redux/auth/actions'
import appActions from '../../redux/app/actions'
import loadingActions from '../../redux/loading/actions'
import errorActions from '../../redux/error/actions'
import Sidebar from '../Sidebar/Sidebar'
import Topbar from '../Topbar/Topbar'
import AppRouter from './AppRouter'
import themes from '../../settings/themes'
import { themeConfig, siteConfig } from '../../settings'
import AppHolder from './commonStyle'
import './global.css'
import './ionicons.min.css'
import CircularLoader from '../../components/CircularLoader'

const { Content, Footer } = Layout
const { logout } = authAction
const { toggleAll } = appActions
const { resetErrorRedux } = errorActions
const { resetLoadingRedux } = loadingActions

const env = process.env.REACT_APP_ENV?.toLowerCase()

export class App extends Component {
  state = {
    defaultUri: '',
    key: 0
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { getUserProfileLoading, getUserProfileError, getUserProfileErrorData = {} } = nextProps

    if (getUserProfileLoading === false) {
      if (getUserProfileError) {
        if (get(getUserProfileErrorData, 'reset_request_id')) {
          const errorMessage = get(getUserProfileErrorData, 'message')
          this.props.logout()
          notification.error({ message: errorMessage })
          const resetRequestID = get(getUserProfileErrorData, 'reset_request_id')
          setTimeout(() => {
            this.props.history.push(`/reset_password/${resetRequestID}`)
          }, 10)
        }
      }
      this.props.resetLoadingRedux(['GET_PROFILE_DETAIL'])
      this.props.resetErrorRedux(['GET_PROFILE_DETAIL'])
    }
  }

  uriDetection = uri => {
    this.setState({ defaultUri: uri })
  }

  render () {
    const { url } = this.props.match
    const {
      location,
      history,
      profile,
      permissions,
      getUserProfileLoading
    } = this.props
    const { defaultUri } = this.state
    return (
      <ThemeProvider theme={themes[themeConfig.theme]}>
        <AppHolder>
          {
            getUserProfileLoading
              ? (
                <div className='page-loader'>
                  <CircularLoader isSpining={getUserProfileLoading} size='48px' />
                </div>)
              : (
                <>
                  {!getUserProfileLoading && profile.id &&
                    (
                      <Layout>
                        <Topbar
                          history={history}
                          location={location}
                          url={url}
                          dataProfile={profile}
                          permissions={permissions}
                          env={env}
                        />
                        <Layout style={{ flexDirection: 'row', overflowX: 'hidden' }}>
                          <Sidebar
                            url={url}
                            uriDetection={this.uriDetection}
                            permissions={permissions}
                            {...this.props}
                          />
                          <Layout
                            className='isoContentMainLayout'
                          >
                            <Content
                              className='isomorphicContent'
                              style={{
                                padding: '70px 0 0',
                                flexShrink: '0',
                                background: '#f1f3f6',
                                position: 'relative'
                              }}
                            >
                              <AppRouter
                                url={url}
                                defaultUri={defaultUri}
                                permissions={permissions}
                                {...this.props}
                              />
                            </Content>
                            <Footer
                              style={{
                                background: '#ffffff',
                                textAlign: 'center',
                                borderTop: '1px solid #ededed'
                              }}
                            >
                              {siteConfig.footerText}
                            </Footer>
                          </Layout>
                        </Layout>
                      </Layout>
                    )}
                </>
                )
          }
        </AppHolder>
      </ThemeProvider>
    )
  }
}

App.propTypes = {
  permissions: PropTypes.array.isRequired
}

App.defaultProps = {
  permissions: []
}

export default connect(
  state => ({
    profile: state.Auth.profile,
    height: state.App.height,
    permissions: state.Auth.permissions,
    getUserProfileLoading: state.Loading.GET_PROFILE_DETAIL,
    getUserProfileError: state.Error.GET_PROFILE_DETAIL,
    getUserProfileErrorData: state.Auth.getUserProfileErrorData
  }),
  {
    logout,
    toggleAll,
    resetLoadingRedux,
    resetErrorRedux
  }
)(App)
