import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

export function* getAgentRequest() {
  yield takeEvery('GET_AGENT_DATA', function* () {
    try {
      let res = yield call(callApi.getAgentData)
      if (res) {
        yield put({ type: actions.AGENT_DATA, data: res.data })
      } else {
        yield put({ type: actions.REFERAL_NOT_FOUND, message: 'Agent not found!' })
      }
    } catch (e) {
      yield put({ type: actions.REFERAL_NOT_FOUND, message: 'Agent not found!' })
    }
  })
}

export function* getReferralRequest() {
  yield takeEvery('GET_REFERAL_DATA', function* (payload) {
    try {
      let res = yield call(callApi.getReferralData, payload)
      if (res.status === 200) {
        yield put({ type: actions.REFERAL_DATA, data: res.data })
      } else {
        yield put({ type: actions.REFERAL_NOT_FOUND, message: 'Referal not found!' })
      }
    } catch (e) {
      yield put({ type: actions.REFERAL_NOT_FOUND, message: 'Referal not found!' })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(getAgentRequest),
    fork(getReferralRequest)
  ])
}
