import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import { saveAs } from 'file-saver'
import _ from 'lodash'
import actions from './actions'
import authPost from '../../../request/methods/authPost'
import authGet from '../../../request/methods/authGet'
import partnerFileTemplateUrls from '../../../request/urls/partnerFIleTemplate'

export function * getFileTemplates () {
  yield takeEvery(actions.GET_TEMPLATE_TYPES_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(authGet, { ...payload, url: partnerFileTemplateUrls.getTemplateTypes })
      if (res.status === 200) {
        yield put({
          type: actions.GET_TEMPLATE_TYPES_SUCCESS,
          data: res.data.data,
          message: _.get(res.data, 'message', 'Success') || 'Success'
        })
      } else {
        yield put({
          type: actions.GET_TEMPLATE_TYPES_FAILURE,
          data: [],
          message: _.get(res.data, 'message', 'Error') || 'Error'
        })
      }
    } catch (error) {
      yield put({
        type: actions.GET_TEMPLATE_TYPES_FAILURE,
        data: [],
        sendOtpStatus: _.get(error.data, 'message', 'Error') || 'Error'
      })
    }
  })
}

