export function * exportTemplate () {
  yield takeEvery(actions.EXPORT_TEMPLATE_REQUEST, function * ({ payload }) {
    try {
      let res = yield call(authPost, { ...payload, url: partnerFileTemplateUrls.exportFileTemplate })
      if (res.status === 200) {
        const blob = new Blob([JSON.stringify(res.data)], { type: 'application/json;charset=utf-8' })
        yield saveAs(blob, 'PartnerFileTemplate.json')
        yield put({
          type: actions.EXPORT_TEMPLATE_SUCCESS,
          data: res.data,
          message: _.get(res.data, 'message', 'Success') || 'Success'
        })
      } else {
        yield put({
          type: actions.EXPORT_TEMPLATE_FAILURE,
          data: '',
          message: _.get(res.data, 'message', 'Error') || 'Error'
        })
      }
    } catch (error) {
      yield put({
        type: actions.EXPORT_TEMPLATE_FAILURE,
        data: '',
        message: _.get(error.data, 'message', 'Error')
      })
    }
  })
}

