export default function * rootSaga () {
  yield all([
    fork(getFileTemplates),
    fork(getColumnTypes),
    fork(createFileTemplate),
    fork(listFileTemplate),
    fork(listTimezone),
    fork(exportTemplate),
    fork(importTemplate),
    fork(changeTemplateStatus),
    fork(getTemplateDetails),
    fork(getFileTemplateStaticData),
    fork(getDefaultReconConfig)
  ])
}
