export function* postEditFeedback() {
  yield takeEvery(actions.POST_EDIT_FEEDBACK_FORM_REQUEST, function* (payload) {
    try {
      let res = yield call(callApi.postEditFeedbackForm, payload)
      if (res.status === 201 || res.status === 200) {
        yield put({ type: actions.GET_FEEDBACK_FORM_REQUEST })
        yield put({ type: actions.POST_EDIT_FEEDBACK_FORM_SUCCESS, postFeedbackFormMessage: 'Successfully edited' })
      } else {
        yield put({ type: actions.POST_EDIT_FEEDBACK_FORM_FAILURE, postFeedbackFormMessage: res.data.error })
      }
    } catch (e) {
      yield put({ type: actions.POST_EDIT_FEEDBACK_FORM_FAILURE, postFeedbackFormMessage: 'Error' })

    }
  })
}

export function* downloadFeedback() {
  yield takeEvery(actions.DOWNLOAD_FEEDBACK_REPORT_REQUEST, function* ({ payload }) {
    try {
      let res = yield call(authPost, { body: { ...payload }, url: configUrl.downloadFeedbackApi })
      if (res.status === 200) {
        yield put({ type: actions.DOWNLOAD_FEEDBACK_REPORT_SUCCESS, message: res.data?.message || 'Feedback Download Triggered' })
      } else {
        yield put({ type: actions.DOWNLOAD_FEEDBACK_REPORT_FAILURE, message: res.data?.message || 'Feedback Download Failed' })
      }
    } catch (error) {
      yield put({ type: actions.DOWNLOAD_FEEDBACK_REPORT_FAILURE, message: error?.data?.error || 'Feedback Download Failed' })
    }
  })
}

export default function* rootSaga() {
  yield all([
    fork(getFeedbackDashboard),
    fork(getFeedbackTable),
    fork(getProduct),
    fork(getFeedbackForm),
    fork(postEditFeedback),
    fork(downloadFeedback)
  ])
}
