const actions = {
  RESET_REDUX_STATE_MASTERDATA: 'RESET_REDUX_STATE_MASTERDATA',
  GET_MASTER_DATA_REQUEST: 'GET_MASTER_DATA_REQUEST',
  GET_MASTER_DATA_SUCCESS: 'GET_MASTER_DATA_SUCCESS',
  GET_MASTER_DATA_FAILURE: 'GET_MASTER_DATA_FAILURE',
  resetReduxMasterData: (payload) => ({
    type: actions.RESET_REDUX_STATE_MASTERDATA,
    payload
  }),
  getMasterData: (payload) => ({
    type: actions.GET_MASTER_DATA_REQUEST,
    payload
  })
}
export default actions
