import { all, takeEvery, call, put, fork } from 'redux-saga/effects'
import actions from './actions'
import callApi from '../../../helpers/callApi'

function * listHardcopy () {
  yield takeEvery(actions.LIST_HARDCOPY_REQUEST, function * ({ payload = {} }) {
    try {
      const res = yield call(callApi.listHardcopyRequests, { query: payload })
      if (res && (res.status === 200 || res.status === 201)) {
        yield put({
          type: actions.LIST_HARDCOPY_SUCCESS,
          listData: res.data.data?.details || [],
          listMeta: res.data.data?.metadata || {},
          listMessage: 'success'
        })
      } else {
        yield put({
          type: actions.LIST_HARDCOPY_FAILURE,
          listData: [],
          listMeta: {},
          listMessage: res?.data?.message || 'Failed to fetch list'
        })
      }
    } catch (e) {
      yield put({
        type: actions.LIST_HARDCOPY_FAILURE,
        listData: [],
        listMeta: {},
        listMessage: e.message
      })
    }
  })
}

function * getHardcopy () {
  yield takeEvery(actions.GET_HARDCOPY_REQUEST, function * ({ payload = {} }) {
    try {
      const res = yield call(callApi.getHardcopyRequest, { id: payload.id })
      if (res && res.status === 200) {
        yield put({
          type: actions.GET_HARDCOPY_SUCCESS,
          detailData: res.data.data?.details?.request || {},
          detailLogs: res.data.data?.details?.logs || [],
          detailMessage: 'success'
        })
      } else {
        yield put({
          type: actions.GET_HARDCOPY_FAILURE,
          detailData: {},
          detailLogs: [],
          detailMessage: res?.data?.message || 'Failed to fetch detail'
        })
      }
    } catch (e) {
      yield put({
        type: actions.GET_HARDCOPY_FAILURE,
        detailData: {},
        detailLogs: [],
        detailMessage: e.message
      })
    }
  })
}

function * progressHardcopy () {
  yield takeEvery(actions.PROGRESS_HARDCOPY_REQUEST, function * ({ payload = {} }) {
    try {
      const { id, ...body } = payload
      const res = yield call(callApi.progressHardcopyRequest, { id, body })
      if (res && (res.status === 200 || res.status === 201)) {
        yield put({ type: actions.PROGRESS_HARDCOPY_SUCCESS, progressMessage: 'success' })
        // Re-fetch detail after progress
        yield put({ type: actions.GET_HARDCOPY_REQUEST, payload: { id } })
      } else {
        yield put({
          type: actions.PROGRESS_HARDCOPY_FAILURE,
          progressMessage: res?.data?.message || 'Failed to progress'
        })
      }
    } catch (e) {
      yield put({ type: actions.PROGRESS_HARDCOPY_FAILURE, progressMessage: e.message })
    }
  })
}

function * rejectHardcopy () {
  yield takeEvery(actions.REJECT_HARDCOPY_REQUEST, function * ({ payload = {} }) {
    try {
      const { id, ...body } = payload
      const res = yield call(callApi.rejectHardcopyRequest, { id, body })
      if (res && (res.status === 200 || res.status === 201)) {
        yield put({ type: actions.REJECT_HARDCOPY_SUCCESS, rejectMessage: 'success' })
        // Re-fetch detail after reject
        yield put({ type: actions.GET_HARDCOPY_REQUEST, payload: { id } })
      } else {
        yield put({
          type: actions.REJECT_HARDCOPY_FAILURE,
          rejectMessage: res?.data?.message || 'Failed to reject'
        })
      }
    } catch (e) {
      yield put({ type: actions.REJECT_HARDCOPY_FAILURE, rejectMessage: e.message })
    }
  })
}

export default function * rootSaga () {
  yield all([
    fork(listHardcopy),
    fork(getHardcopy),
    fork(progressHardcopy),
    fork(rejectHardcopy)
  ])
}
