const cookies = new Cookies()

/**
 * Fn to detect if passed value is object
 * @argument {any} value
 */
function isObject (value) {
  return value && typeof value === 'object' && value.constructor === Object
}

function isArray (value) {
  return value && typeof value === 'object' && value.constructor === Array
}

export function sortByKey (array, key) {
  if (!isArray(array)) {
    return array
  }

  return array.sort(function (a, b) {
    const x = a[key]
    const y = b[key]
    return x < y ? -1 : x > y ? 1 : 0
  })
}

export function isEmpty (obj) {
  if (!isObject(obj)) return false
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) return false
  }
  return true
}

export function clearToken () {
  localStorage.clear()
  const allCookies = cookies.getAll()
  window.localStorage.removeItem('claimDetailUrl')
  window.localStorage.removeItem('isClaimDetail')
  for (const key in allCookies) {
    cookies.remove(key, { path: '/' })
  }
}

export function getToken () {
  try {
    const idToken = cookies.get('id_token')
    return new Map({ idToken })
  } catch (err) {
    clearToken()
    return new Map()
  }
}

export function getHeaderUploadFile () {
  const token = getToken().get('idToken')
  return {
    'Content-Type': 'multipart/form-data',
    Authorization: 'JWT ' + token
  }
}

export function getHeader () {
  const token = getToken().get('idToken')
  return {
    'Content-Type': 'application/json',
    Authorization: 'jwt ' + token
  }
}

export function getUser () {
  const token = getToken().get('idToken')
  if (token) {
    const profile = jwtDecode(token)
    return profile
  }
}

export function timeDifference (givenTime) {
  givenTime = new Date(givenTime)
  const milliseconds = new Date().getTime() - givenTime.getTime()
  const numberEnding = (number) => {
    return number > 1 ? 's' : ''
  }
  const number = (num) => (num > 9 ? '' + num : '0' + num)
  const getTime = () => {
    let temp = Math.floor(milliseconds / 1000)
    const years = Math.floor(temp / 31536000)
    if (years) {
      const month = number(givenTime.getUTCMonth() + 1)
      const day = number(givenTime.getUTCDate())
      const year = givenTime.getUTCFullYear() % 100
      return `${day}-${month}-${year}`
    }
    const days = Math.floor((temp %= 31536000) / 86400)
    if (days) {
      if (days < 28) {
        return days + ' day' + numberEnding(days)
      } else {
        const months = [
          'Jan',
          'Feb',
          'Mar',
          'Apr',
          'May',
          'Jun',
          'Jul',
          'Aug',
          'Sep',
          'Oct',
          'Nov',
          'Dec'
        ]
        const month = months[givenTime.getUTCMonth()]
        const day = number(givenTime.getUTCDate())
        return `${day} ${month}`
      }
    }
    const hours = Math.floor((temp %= 86400) / 3600)
    if (hours) {
      return `${hours} hour${numberEnding(hours)} ago`
    }
    const minutes = Math.floor((temp %= 3600) / 60)
    if (minutes) {
      return `${minutes} minute${numberEnding(minutes)} ago`
    }
    return 'a few seconds ago'
  }
  return getTime()
}

export const capitalizeFirstLetter = (string) => {
  const str = string.charAt(0).toUpperCase() + string.slice(1)
  return str.replace(/[ _-]/g, ' ')
}

export const serialize = (object) => {
  const str = []
  for (const p in object) {
    if (Object.prototype.hasOwnProperty.call(object, p)) {
      str.push(encodeURIComponent(p) + '=' + encodeURIComponent(object[p]))
    }
  }
  return '?' + str.join('&')
}

export const dataFormatter = (policy) => {
  if (policy.length > 0) {
    const dataPolicy = policy.map((value) => {
      const { Time, Valid } = value.PolicyStart
      return {
        ...value,
        PolicyStart: Valid ? moment(Time).format('YYYY-MM-DD') : ''
      }
    })
    return dataPolicy
  } else {
    return []
  }
}

export const getTableKeys = (val) => {
  const tableKeys = Object.keys(val)
    .sort()
    .map((key) =>
      val[key]
        ? {
            title: capitalizeFirstLetter(key),
            dataIndex: key,
            key: key
          }
        : {}
    )
  return tableKeys
}

export const mapKeysToTableColumns = (val) => {
  const columns = Object.keys(_.get(val, '[0]', {}))
  return columns.map((key) => ({
    title: capitalizeFirstLetter(key),
    dataIndex: key,
    key: key
  }))
}

export const validatorCheck = (val1, val2, operator) => {
  switch (operator) {
    case 'eq':
      return val1 === val2
    case 'gte':
      return val1 >= val2
    case 'gt':
      return val1 > val2
    case 'lt':
      return val1 < val2
    case 'lte':
      return val1 <= val2
    default:
      return false
  }
}

export const getRandomColor = () => {
  let color =
    Math.floor(Math.random() * 6) +
    Math.floor(Math.random() * 16777215)
      .toString(16)
      .substring(1)
  while (color.length < 6) {
    color = '0' + color
  }
  return '#' + color
}

export const validUrl = (str) => {
  const pattern = new RegExp(
    '^(https?:\\/\\/)?' + // protocol
      '((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|' + // domain name
      '((\\d{1,3}\\.){3}\\d{1,3}))' + // OR ip (v4) address
      '(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*' + // port and path
      '(\\?[;&a-z\\d%_.~+=-]*)?' + // query string
      '(\\#[-a-z\\d_]*)?$',
    'i'
  ) // fragment locator
  return !!pattern.test(str)
}

