export const formatIntl = (number) => {
  if (isNaN(number)) return;
  return new Intl.NumberFormat("id-ID").format(number);
};

export const formatIntlCurrency = (number) => {
  if (!number && number !== 0) return;
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
  }).format(number);
};

export const parseIntlCurrency = (currency) => {
  if (!currency) return;
  const res = new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
  })
    .formatToParts(currency)
    .reduce((acc, x) => {
      if (x.type === "integer") {
        return acc + x.value;
      }
      return acc;
    }, "");
  return Number(res);
};

