export const convertPriceStringToNumber = (price = "") => {
  let numbers = "";
  for (let index = 0; index < price.length; index++) {
    let digit = price[index];
    if (!isNaN(digit) || digit === ",") {
      digit = digit === "," ? "." : digit;
      if (digit.trim()) {
        numbers += digit;
      }
    }
  }
  return Number(numbers);
};

export const isVNPath = () => {
  return window.location.pathname.includes("agent/vn");
};

export const stringOfArrayOfStringHandler = (value) => {
  if (typeof value !== "string") {
    return String(value);
  }
  if (value.trim().startsWith("[") && value.trim().endsWith("]")) {
    try {
      const jsonLike = value.replace(/'/g, '"');
      const parsed = JSON.parse(jsonLike);
      if (Array.isArray(parsed)) {
        return parsed.join(", ");
      }
    } catch (e) {
      return value.replace(/[[\]']/g, "");
    }
  }
  return value;
};

export const formatDate = (value, format) => {
  if (!value) return value;
  return moment(value).format(format);
};
