import actions from './actions'

const initialState = {
  getCreateJDStatus: '',
  getCreateOAGStatus: ''
}

export default function partnerReducer (state = initialState, action) {
  switch (action.type) {
    case actions.RESET_REDUX_STATE_DEMO:
      return {
        ...state,
        getCreateJDStatus: '',
        getCreateOAGStatus: ''
      }
    case actions.CREATE_JD_SUCCESS:
      return {
        ...state,
        getCreateJDStatus: action.getCreateJDStatus
      }
    case actions.CREATE_JD_FAILED:
      return {
        ...state,
        getCreateJDStatus: action.getCreateJDStatus
      }
    case actions.CREATE_OAG_NOTIF_SUCCESS:
      return {
        ...state,
        getCreateOAGStatus: action.getCreateOAGStatus
      }
    case actions.CREATE_OAG_NOTIF_FAILED:
      return {
        ...state,
        getCreateOAGStatus: action.getCreateOAGStatus
      }
    default:
      return state
  }
}
