import React, { useState, useContext, useMemo, useEffect, createContext, Suspense } from 'react'
import { Progress } from 'antd'
import ProgressStyleWrapper from './index.style'

const ProgressBarContext = createContext()

function ProgressBarProvider ({ children }) {
  const [active, setActive] = useState(false)
  const value = useMemo(() => ({ active, setActive }), [active, setActive])
  return (
    <ProgressBarContext.Provider value={value}>
      {children}
    </ProgressBarContext.Provider>
  )
}

function ProgressBar () {
  const { active } = useContext(ProgressBarContext)
  const [percent, setPercent] = useState(0)
  useEffect(() => {
    setTimeout(() => {
      setPercent(percent => (percent < 100 ? percent + 10 : 100))
    }, 200)
  })
  return active
    ? (
      <ProgressStyleWrapper>
        <Progress
          className='progress-style'
          showInfo={false} percent={percent} status='active'
        />
      </ProgressStyleWrapper>)
    : null
}

function ProgressbarFallback () {
  const { setActive } = useContext(ProgressBarContext)
  useEffect(() => {
    setActive(true)
    return () => setActive(false)
  })
  return null
}

export default function ProgressBarComponent ({ children }) {
  return (
    <ProgressBarProvider>
      <ProgressBar />
      <Suspense fallback={<ProgressbarFallback />}>
        {children}
      </Suspense>
    </ProgressBarProvider>
  )
}
